  // 重要知识点（按章节分类，每个含专属自测题；部分配真实图片 img）
  const knowledge = [
    /* ============ 导言 ============ */
    {ch:'intro',title:'时间界定',speak:'中国近现代史是指1840年以来的中国历史。从1840年鸦片战争爆发到1949年中华人民共和国成立前夕，是中国近代史；1949年中华人民共和国成立以来的历史，是中国现代史。',
      quiz:{type:'fill',q:'中国近现代史是指 ______ 年以来的中国历史（以鸦片战争为起点）。',answer:'1840',exp:'教材明确：中国近现代史是指 1840 年以来的中国历史，以鸦片战争为起点。'}},
    {ch:'intro',title:'主流本质',speak:'中国近现代史，就其主流和本质来说，是中国人民为救亡图存和实现中华民族伟大复兴而英勇奋斗、艰辛探索并不断取得伟大成就的历史。尤其是各族人民在中国共产党领导下，经过新民主主义革命赢得民族独立、人民解放，建立中华人民共和国；经过社会主义革命、建设、改革，把极度贫穷落后的中国逐步改变成持续走向繁荣富强的社会主义中国。',
      quiz:{type:'choice',q:'中国近现代史的主流和本质是？',opts:['列强单方面侵略中国的历史','中国人民为救亡图存和民族复兴而奋斗、探索、取得成就的历史','封建王朝的更替史','单纯的中外贸易史'],a:1,exp:'主流本质是中国人民为救亡图存和实现中华民族伟大复兴而英勇奋斗、艰辛探索并不断取得伟大成就的历史。'}},
    {ch:'intro',title:'党的最高理想与初心使命',speak:'中国共产党一经成立，就把实现共产主义作为党的最高理想和最终目标，义无反顾肩负起实现中华民族伟大复兴的历史使命。党一经诞生，就把为中国人民谋幸福、为中华民族谋复兴确立为自己的初心使命。一百多年来党团结带领人民取得的一切奋斗、牺牲、创造，归结起来就是一个主题：实现中华民族伟大复兴。',
      quiz:{type:'choice',q:'中国共产党一经诞生确立的初心使命是？',opts:['为中国人民谋幸福、为中华民族谋复兴','优先实现工业化','先成为执政党再谈理想','推翻旧政府即可'],a:0,exp:'党的初心使命是为中国人民谋幸福、为中华民族谋复兴；最高理想是实现共产主义。'}},
    {ch:'intro',title:'必由之路与根本保证',speak:'坚持和发展中国特色社会主义，是实现中华民族伟大复兴的必由之路。坚持中国共产党的领导，是实现中华民族伟大复兴的根本保证。',
      quiz:{type:'choice',q:'实现中华民族伟大复兴的"根本保证"是？',opts:['坚持改革开放','坚持中国共产党的领导','发展资本主义','全盘西化'],a:1,exp:'坚持中国共产党的领导是实现中华民族伟大复兴的根本保证；坚持和发展中国特色社会主义是必由之路。'}},
    {ch:'intro',title:'半殖民地半封建社会的形成',speak:'鸦片战争以后，由于西方列强入侵和封建统治腐败，中国逐步成为半殖民地半封建社会。从那时起，中国社会发生两个根本变化：一是独立的中国逐步变成半殖民地的中国，二是封建的中国逐步变成半封建的中国。从1840年鸦片战争到1949年新中国成立前，中国都属于半殖民地半封建社会。',
      quiz:{type:'fill',q:'鸦片战争后，中国社会的两个根本变化：一是独立的中国逐步变成 ______ 的中国，二是封建的中国逐步变成半封建的中国。',answer:'半殖民地',exp:'两个根本变化：独立的中国逐步变成半殖民地的中国，封建的中国逐步变成半封建的中国。'}},
    {ch:'intro',title:'近代中国社会主要矛盾',speak:'半殖民地半封建社会的性质，决定了近代中国社会主要矛盾是帝国主义和中华民族的矛盾、封建主义和人民大众的矛盾。这两对主要矛盾贯穿半殖民地半封建社会的始终，并对近代中国社会的发展变化起着决定性作用。',
      quiz:{type:'choice',q:'近代中国社会的两对主要矛盾是？',opts:['帝国主义和中华民族、封建主义和人民大众','资产阶级和无产阶级','地主阶级和农民阶级','列强与列强之间'],a:0,exp:'两对主要矛盾：帝国主义和中华民族的矛盾、封建主义和人民大众的矛盾。'}},
    {ch:'intro',title:'反侵略战争失败的根本原因',speak:'从鸦片战争直到抗日战争以前，中国的反侵略战争无不以失败而告结束。正如毛泽东所说，究其根本原因：一是社会制度腐败，二是经济技术落后。也正因如此，争得民族独立、人民解放，实现国家富强、人民幸福，成为中国人民必须完成的两大历史任务。',
      quiz:{type:'fill',q:'毛泽东指出，近代反侵略战争失败的根本原因：一是社会制度腐败，二是 ______ 。',answer:'经济技术落后',exp:'根本原因：一是社会制度腐败，二是经济技术落后。'}},
    {ch:'intro',title:'近代中国的两大历史任务',speak:'争取民族独立、人民解放，实现国家富强、人民幸福，是近代中国人民必须完成的两大历史任务。在两大历史任务中，前一个任务为后一个任务扫清障碍，为实现中华民族伟大复兴创造必要前提。',
      quiz:{type:'choice',q:'关于两大历史任务的关系，正确的是？',opts:['后一个任务为前一个扫清障碍','前一个任务为后一个扫清障碍','两者互不相关','只需完成其一即可'],a:1,exp:'前一任务（民族独立、人民解放）为后一任务（国家富强、人民幸福）扫清障碍。'}},
    {ch:'intro',title:'新兴阶级与工人阶级',speak:'随着近代中国社会性质的改变，社会阶级关系发生深刻变动，不仅原有的地主阶级、农民阶级发生了变化，还产生了工人阶级、资产阶级、小资产阶级等新的阶级。新兴的工人阶级是近代中国最革命的阶级。',
      quiz:{type:'choice',q:'近代中国新兴的、最革命的阶级是？',opts:['地主阶级','农民阶级','工人阶级','买办阶级'],a:2,exp:'新兴的工人阶级是近代中国最革命的阶级。'}},
    {ch:'intro',title:'三座大山',speak:'在1949年新中国成立前，中国人民遭受帝国主义、封建主义的压迫，后来又增加官僚资本主义的压迫。这三者，就是压在中国人民头上的三座大山。推翻三座大山，成为新民主主义革命的主要任务。',
      quiz:{type:'fill',q:'压在中国人民头上的"三座大山"是帝国主义、封建主义和 ______ 。',answer:'官僚资本主义',exp:'三座大山：帝国主义、封建主义、官僚资本主义。'}},
    {ch:'intro',title:'三种建国方案与历史的选择',speak:'在新民主主义革命时期，中国存在三种主要建国方案：一是北洋军阀和国民党统治集团代表的大地主大资产阶级专政；二是中间派别代表的资产阶级共和国；三是中国共产党代表的工人阶级领导的、以工农联盟为基础的人民共和国。实践反复检验后，只有第三种方案赢得最广大人民群众的拥护。中国人民接受中国共产党的领导，是郑重作出的历史性选择，具有历史必然性。',
      quiz:{type:'choice',q:'三种建国方案中最终赢得人民拥护的是？',opts:['大地主大资产阶级专政','资产阶级共和国','工人阶级领导的人民共和国','无政府状态'],a:2,exp:'只有第三种方案——工人阶级领导的人民共和国赢得最广大人民群众拥护；接受党的领导是历史性选择。'}},
    {ch:'intro',title:'新民主主义革命的开端与胜利意义',speak:'五四运动是中国新民主主义革命的伟大开端，领导权的变化是区分新旧民主主义革命的根本标志。1921年中国共产党应运而生。新民主主义革命胜利，彻底结束了旧中国半殖民地半封建社会的历史，实现了中国从几千年封建专制政治向人民民主的伟大飞跃；创立了毛泽东思想，这是马克思主义中国化时代化的第一次历史性飞跃。实践充分说明：没有共产党就没有新中国，只有社会主义才能救中国、发展中国，中国人民从此站起来了。',
      quiz:{type:'choice',q:'区分新旧民主主义革命的根本标志是？',opts:['革命对象不同','领导权的变化','爆发地点不同','群众规模不同'],a:1,exp:'领导权的变化（无产阶级领导）是区分新旧民主主义革命的根本标志；五四运动是开端。'}},
    {ch:'intro',title:'中国现代史综述',speak:'1949年中华人民共和国成立以来的现代史，是各族人民在中国共产党领导下，为实现中华民族伟大复兴开辟新纪元的历史；是探索、开创、坚持、捍卫、发展中国特色社会主义并取得辉煌成就的历史。其历程包括：社会主义革命和建设时期、改革开放和社会主义现代化建设新时期（以1978年党的十一届三中全会为标志），以及中国特色社会主义进入新时代。',
      quiz:{type:'choice',q:'中国现代史的开端是？',opts:['1840 年鸦片战争','1919 年五四运动','1949 年中华人民共和国成立','1978 年十一届三中全会'],a:2,exp:'1949 年中华人民共和国成立，开启中国现代史；1978 年十一届三中全会开启改革开放新时期。'}},
    {ch:'intro',title:'四个选择',speak:'近代以来的历史充分证明，历史和人民作出了四个选择：选择了马克思主义、选择了中国共产党、选择了社会主义道路、选择了改革开放。坚持和发展中国特色社会主义是必由之路，坚持中国共产党的领导是根本保证。',
      quiz:{type:'fill',q:'历史和人民作出了四个选择：选择了马克思主义、选择了中国共产党、选择了社会主义道路、选择了 ______ 。',answer:'改革开放',exp:'四个选择是：马克思主义、中国共产党、社会主义道路、改革开放。'}},

    /* ============ 第一章 ============ */
    {ch:'c1',title:'中国封建社会的衰落与西方殖民扩张',speak:'清朝中期以后中国封建社会由盛转衰，政治腐败、军备废弛、土地兼并严重；与此同时世界资本主义快速发展并加紧殖民扩张，英国以鸦片打开中国大门。',
      quiz:{type:'choice',q:'鸦片战争前，西方列强加紧殖民扩张的直接动因之一是？',opts:['传播基督教义','扭转对华贸易逆差、打开中国市场','援助清廷改革','争夺美洲殖民地'],a:1,exp:'英国为扭转对华贸易逆差，以鸦片打开中国大门，进而发动侵略战争。'}},
    {ch:'c1',title:'鸦片战争与半殖民地半封建社会的形成',speak:'1840年鸦片战争是中国近代史的开端。战后《南京条约》等一系列不平等条约的签订，使中国开始沦为半殖民地半封建社会，这一社会性质延续至1949年。',
      quiz:{type:'fill',q:'______ 年鸦片战争是中国近代史的开端，战后中国开始沦为半殖民地半封建社会。',answer:'1840',exp:'1840 年鸦片战争后，中国逐步沦为半殖民地半封建社会。'}},
    {ch:'c1',title:'近代中国的社会矛盾与两大历史任务',speak:'半殖民地半封建中国的主要矛盾是帝国主义和中华民族的矛盾、封建主义和人民大众的矛盾。两大历史任务是争取民族独立人民解放、实现国家富强人民幸福。',
      quiz:{type:'choice',q:'近代中国的两大历史任务中，前一任务是？',opts:['实现国家富强、人民幸福','争取民族独立、人民解放','发展资本主义','全盘西化'],a:1,exp:'前一任务是争取民族独立、人民解放，为后一任务（国家富强、人民幸福）扫清障碍。'}},
    {ch:'c1',title:'西方列强对中国的侵略',speak:'列强通过军事侵略（发动战争、割占领土）、政治控制（操控内政外交）、经济掠夺（赔款、控制关税）和文化渗透，使中国陷入苦难深渊。',
      quiz:{type:'choice',q:'西方列强对中国的侵略不包括下列哪一项？',opts:['军事侵略','政治控制','经济掠夺','技术无偿援助'],a:3,exp:'列强侵略表现为军事、政治、经济、文化四个方面，并不存在无偿技术援助。'}},
    {ch:'c1',title:'反抗外国侵略的斗争',speak:'中国人民从未屈服：三元里抗英、太平天国运动、左宗棠收复新疆、义和团运动等，沉重打击了侵略者，粉碎了列强瓜分中国的图谋。',
      quiz:{type:'choice',q:'下列哪一事件粉碎了列强瓜分中国的图谋？',opts:['戊戌变法','义和团运动','洋务运动','辛亥革命'],a:1,exp:'义和团运动展现了中国人民不畏强暴的牺牲精神，粉碎了列强瓜分中国的图谋。'}},
    {ch:'c1',title:'反侵略战争的失败与民族意识的觉醒',speak:'反侵略战争屡败的根本原因是社会制度腐败和经济技术落后。甲午战后，中国人民族意识开始普遍觉醒，救亡图存成为时代主题。',
      quiz:{type:'fill',q:'毛泽东指出，近代反侵略战争失败的根本原因：一是社会制度腐败，二是 ______ 。',answer:'经济技术落后',exp:'根本原因：一是社会制度腐败，二是经济技术落后。'}},

    /* ---- 第一章第一节（新增，基于教材PDF：鸦片战争前后的中国与世界） ---- */
    {ch:'c1',title:'中国封建社会的基本特征',speak:'中国封建社会自战国到1840年延续两千多年。经济上，封建地主土地所有制占主导，以个体家庭为单位、与家庭手工业结合的自给自足自然经济为主；政治上，实行高度中央集权的封建君主专制制度；文化上，自汉武帝“独尊儒术”后儒家思想成为正统，并与佛道融合、吸收法家严刑峻法；社会上，实行族权与政权结合的封建宗法等级制度，核心是君权、父权、夫权。这一结构维系了稳定延续，也使其发展迟滞。',
      quiz:{type:'choice',q:'中国封建社会政治的基本特征是？',opts:['高度中央集权的封建君主专制制度','君主立宪制','民主共和制','分封制'],a:0,exp:'自秦始皇建立中央集权封建帝国，历朝不断加强皇权，实行高度中央集权的封建君主专制。'}},
    {ch:'c1',title:'清王朝由盛转衰',speak:'17世纪下半叶至18世纪康雍乾年间是中国封建社会后期鼎盛，但已走向末世。到鸦片战争前夜的嘉庆、道光年间，清王朝衰相尽显：经济生产凋敝、土地高度集中（如乾隆朝权臣和珅有地80多万亩）；对外长期实行“海禁”与闭关政策，乾隆二十四年（1759年）后仅留广州一口通商。封建统治腐败，潜伏深刻危机。',
      quiz:{type:'fill',q:'乾隆二十四年（1759年）后，清廷关闭其他各口，仅留 ______ 一口通商。',answer:'广州',exp:'乾隆朝后期仅留广州一口通商，体现闭关政策，彼时中国经济社会发展已落后于西方。'}},
    {ch:'c1',title:'世界资本主义的发展与殖民扩张',speak:'16至19世纪初中国仍处封建晚期，西方资本主义已产生发展。1640年英国资产阶级革命标志世界进入资本主义时代；18世纪中叶至19世纪中叶工业革命使大机器生产取代工场手工业，资本主义经济迅速发展。殖民主义适应西方资本主义发展要求而产生，目的是把东方国家纳入资本主义世界体系，成为殖民地、半殖民地与附庸。',
      quiz:{type:'fill',q:'______ 年英国资产阶级革命，标志着世界历史开始进入资本主义时代。',answer:'1640',exp:'1640年英国资产阶级革命开启资本主义时代，为资本主义发展提供政治前提。'}},
    {ch:'c1',title:'鸦片贸易与林则徐虎门销烟',speak:'19世纪前期英国完成工业革命成为最强大的资本主义国家，对华贸易长期入超。为扭转逆差、牟取暴利，英国殖民者以走私鸦片为手段，鸦片战争前40年运入中国鸦片约40万箱，掠走3亿至4亿银元，造成白银外流、银贵钱贱、财政危机并毒害人民身心。清政府禁烟，1839年6月林则徐在广东虎门销毁收缴鸦片，是维护国家利益与民族尊严的正义行动。',
      quiz:{type:'choice',q:'1839年6月，钦差大臣林则徐在何地销毁鸦片？',opts:['广东虎门','福建厦门','浙江定海','江苏南京'],a:0,exp:'1839年6月林则徐于广东虎门销烟，是维护国家利益和民族尊严的正义行动。'}},
    {ch:'c1',title:'鸦片战争的爆发与不平等条约',speak:'英国为摆脱经济危机、打开中国市场蓄谋侵华。1840年4月英议会通过对华战争决定，6月英舰抵达中国海面、封锁珠江口，鸦片战争正式爆发。清军屡败，1842年8月29日被迫签订中国近代史上第一个不平等条约——《南京条约》；随后1843年中英《虎门条约》、1844年中美《望厦条约》、中法《黄埔条约》等接踵而至，列强攫取大量侵略特权。',
      quiz:{type:'fill',q:'1842年8月29日，清政府与英国签订中国近代史上第一个不平等条约——《______》。',answer:'南京条约',exp:'《南京条约》是中国近代史上第一个不平等条约，开启列强攫取侵略特权的历史。'}},
    {ch:'c1',title:'鸦片战争：中国近代史的起点',speak:'鸦片战争以清政府失败告终。随着外国资本主义入侵，中国封建社会逐步变为半殖民地半封建社会，中国人民开始反帝反封建的资产阶级民主革命。因此，鸦片战争成为中国近代史的起点。',
      quiz:{type:'choice',q:'成为中国近代史起点的事件是？',opts:['鸦片战争','五四运动','甲午战争','辛亥革命'],a:0,exp:'鸦片战争使中国逐步沦为半殖民地半封建社会，是中国近代史的起点。'}},
    {ch:'c1',title:'两个根本变化与半殖民地半封建性质',speak:'鸦片战争后中国社会发生两个根本变化：一是独立的中国逐步变成半殖民地的中国——列强破坏中国领土、领海、关税、司法等主权并加以控制，中国丧失完全独立地位但仍维持独立国家名义，故称半殖民地；二是封建的中国逐步变成半封建的中国——自然经济被破坏、城乡商品经济发展、资本主义生产关系出现，但封建剥削根基仍在，故称半封建。',
      quiz:{type:'fill',q:'鸦片战争后两个根本变化：独立的中国逐步变成半殖民地的中国，封建的中国逐步变成 ______ 的中国。',answer:'半封建',exp:'两个根本变化：独立的中国→半殖民地，封建的中国→半封建。'}},
    {ch:'c1',title:'半殖民地半封建社会的六大基本特征',speak:'其六大基本特征：①资本—帝国主义侵略势力逐步操纵中国经济命脉并控制政治，成为决定性力量；②封建势力衰败并与侵略势力勾结，成为压迫人民的统治支柱；③封建地主土地所有制仍广占优势，是发展进步的严重障碍；④民族资本主义虽产生但发展缓慢软弱，未能成为主要形式；⑤受列强争夺与地方割据影响，各地区经济政治文化发展极不平衡；⑥在双重压迫下广大人民日益贫困化、破产，毫无政治权利。',
      quiz:{type:'choice',q:'下列关于半殖民地半封建社会特征，错误的是？',opts:['侵略势力逐步操纵中国经济命脉','封建地主土地所有制仍广占优势','民族资本主义成为社会经济主要形式','广大人民日益贫困化'],a:2,exp:'民族资本主义受压迫发展缓慢，始终未能成为中国社会经济的主要形式。'}},
    {ch:'c1',title:'近代社会阶级关系的变动',speak:'社会性质变化引起阶级关系深刻变动。地主阶级仍掌政权，部分迁居城市或投资工商业转化为资本家；农民阶级仍是人数最多被剥削阶级，受压迫深重、革命要求强烈，是民主革命主力军，但作为小生产者有局限；新兴的工人阶级最早出现于19世纪40至50年代外资企业，先于资产阶级产生，身受帝国主义、封建主义和资本主义三重压迫，人数少但很集中，与农民有天然联系，革命性最强，是近代中国最革命的阶级；中国资产阶级分官僚买办资本家与民族资本家两部分，民族资产阶级具有革命与妥协的两面性。',
      quiz:{type:'choice',q:'近代中国新兴的、最革命的阶级是？',opts:['地主阶级','农民阶级','工人阶级','买办阶级'],a:2,exp:'工人阶级先于资产阶级产生，身受帝国主义、封建势力、资产阶级三重压迫，革命性最强，是近代中国最革命的阶级。'}},
    {ch:'c1',title:'近代社会主要矛盾的交织与转化',speak:'近代中国主要矛盾中占支配地位的是：帝国主义和中华民族的矛盾、封建主义和人民大众的矛盾，其中帝国主义和中华民族的矛盾是最主要的矛盾。两对矛盾互相交织：当资本—帝国主义发动侵略战争时，民族矛盾上升为主要矛盾（如鸦片战争、甲午战争）；当其与中国反动统治阶级结成同盟压迫人民时，阶级矛盾上升为主要矛盾（如太平天国、辛亥革命）；当国内战争威胁侵略势力统治时，外国势力甚至直接出兵镇压（如清政府“借师助剿”）。矛盾斗争决定两大历史任务：争得民族独立人民解放、实现国家富强人民幸福。',
      quiz:{type:'choice',q:'近代中国最主要的矛盾是？',opts:['帝国主义和中华民族的矛盾','资产阶级和地主阶级的矛盾','农民和地主的矛盾','列强之间的矛盾'],a:0,exp:'两对主要矛盾中，帝国主义和中华民族的矛盾是最主要的矛盾；民族战争时它上升为主要矛盾。'}},

    /* ---- 第一章第二节（新增，基于教材PDF：西方列强对中国的侵略） ---- */
    {ch:'c1',title:'列强侵略中国的四种主要方式',speak:'资本—帝国主义列强对近代中国的侵略，首先是军事侵略，并由此展开政治控制、经济掠夺和文化渗透。军事上发动侵略战争、屠杀人民、侵占领土、勒索赔款；政治上控制内政外交、把持海关、镇压反抗、扶植代理人；经济上控制通商口岸、剥夺关税自主权、倾销商品与资本输出、操纵经济命脉；文化上披着宗教外衣进行侵略，并为侵略制造舆论。四种方式相互勾结，使中国逐步沦为半殖民地半封建社会。',
      quiz:{type:'choice',q:'资本—帝国主义列强对近代中国的侵略中，“首先和主要的是”？',opts:['军事侵略','政治控制','经济掠夺','文化渗透'],a:0,exp:'教材明确指出：列强对中国的侵略，首先和主要的是进行军事侵略。'}},
    {ch:'c1',title:'军事侵略：侵占领土与划分势力范围',speak:'每次侵华战争后，列强都迫签不平等条约攫取特权。1842年《南京条约》割香港岛；1860年《北京条约》割九龙半岛南端；俄国通过《瑷珲条约》《北京条约》等共割占中国150多万平方公里。1895年《马关条约》割台湾及澎湖。列强还强租港湾、划势力范围（德占山东、俄占东北、英占长江流域、法占两广云南、日占福建），在上海等16城设30多个“国中之国”的租界，并通过《辛丑条约》取得北京至山海关12处驻兵特权。',
      quiz:{type:'fill',q:'通过一系列不平等条约，______ 国共侵占中国领土150多万平方公里。',answer:'俄',exp:'俄国利用第二次鸦片战争等时机，割占中国东北、西北共150多万平方公里领土。'}},
    {ch:'c1',title:'军事侵略：勒索赔款与劫掠财富',speak:'列强勒索巨额赔款，造成中国严重财政危机。《南京条约》赔款2100万元（银元）；《马关条约》赔款2亿两白银加赎辽费3000万两等共2.315亿两；八国联军《辛丑条约》赔款高达4.5亿两白银，分39年还清，本息合计近10亿两。侵华期间还公开抢劫，1860年英法联军劫掠并焚毁圆明园，1900年八国联军侵占北京后大肆劫掠故宫等处的珍宝文物。',
      quiz:{type:'fill',q:'八国联军侵华后签订的《辛丑条约》规定中国赔款4.5亿两白银，分39年还清，本息合计近 ______ 两。',answer:'10亿',exp:'《辛丑条约》赔款本息合计近10亿两，是帝国主义对中国公开掠夺。'}},
    {ch:'c1',title:'军事侵略：屠杀中国人民',speak:'资本—帝国主义在历次侵华战争中大肆屠杀中国人民。甲午战争中，1894年11月日军制造旅顺大屠杀，4天内屠杀中国居民2万余人。1900年7月沙俄制造海兰泡惨案和江东六十四屯惨案，烧光村庄、枪杀居民或驱入黑龙江淹死。同年八国联军侵占北京后，仅在庄王府一处就烧死杀死义和团团民与平民1700多人。这些滔天罪行充分暴露了帝国主义践踏文明的野蛮本性。',
      quiz:{type:'fill',q:'1894年11月，日军在甲午战争中制造了______大屠杀惨案，4天内屠杀中国居民2万余人。',answer:'旅顺',exp:'旅顺大屠杀是日军在甲午战争期间犯下的严重战争罪行。'}},
    {ch:'c1',title:'政治控制：控制内政外交与把持海关',speak:'列强通过控制中国政府来操纵内政外交。《天津条约》规定外国公使常驻北京，公使俨然清政府的“太上皇”，直接发号施令；列强还取得领事裁判权，外国人可在华横行不法而中国政府无权干预。把持中国海关是重要手段：1859年海关总税务司署设于上海，英人李泰国、赫德先后任总税务司，赫德掌权达40余年，海关成了列强控制中国政治经济的工具。',
      quiz:{type:'choice',q:'近代长期把持中国海关、任总税务司达40余年的是？',opts:['赫德','李泰国','瓦德西','戈登'],a:0,exp:'英国人赫德自1863年任总税务司至1908年回国，掌握中国海关大权40余年。'}},
    {ch:'c1',title:'政治控制：镇压反抗与扶植代理人',speak:'列强勾结清政府镇压中国人民反侵略反封建斗争：组织“洋枪队”镇压太平天国，迫使清政府屠杀教案民众，《辛丑条约》更强迫清政府永远禁止中国人成立或加入反帝组织。同时扶植代理人：支持奕䜣等掌权，扶植曾国藩、李鸿章等湘淮系官僚，清末支持袁世凯篡夺革命果实，袁死后又分别扶植皖、直、奉各系军阀作为自己的代理人。',
      quiz:{type:'choice',q:'《辛丑条约》规定清政府必须永远禁止中国人？',opts:['成立或加入任何反帝组织','开设工厂','租赁土地','出国留学'],a:0,exp:'《辛丑条约》强迫清政府严禁反帝活动，各级官员镇压不力即革职永不叙用。'}},
    {ch:'c1',title:'经济掠夺：控制通商口岸',speak:'列强通过不平等条约控制中国通商口岸，作为经济侵略基地。鸦片战争前清廷仅限广州一口通商；1842年《南京条约》开放广州、厦门、福州、宁波、上海五口；1858年《天津条约》增开牛庄（后改营口）、登州（后改烟台）、台湾、淡水、潮州（后改汕头）、琼州、汉口、九江、南京、镇江十口；1860年《北京条约》增开天津。陆路还向俄国开放伊犁、喀什噶尔等商埠。列强在口岸依特权控制工商金融、设立租界、实行殖民统治。',
      quiz:{type:'choice',q:'1842年《南京条约》开放的五处通商口岸不包括下列哪一城市？',opts:['上海','南京','厦门','宁波'],a:1,exp:'南京是1858年《天津条约》增开的通商口岸，不在1842年《南京条约》五口（广、厦、福、宁、上）之列。'}},
    {ch:'c1',title:'经济掠夺：剥夺关税自主权与操纵经济命脉',speak:'列强通过不平等条约剥夺中国关税自主权：《南京条约》规定进出口税率“秉公议定”，《望厦条约》《黄埔条约》更将协定关税写入条约，中国不能自主变更税例。它们控制通商口岸、倾销商品、设厂资本输出（1895年后外资设厂933家），并操纵经济命脉：1913年外资占机械采煤79.6%、新式采铁冶铁100%；1911年外资控制铁路达93.1%；外国银行成为对华经济侵略中心。中国被纳入资本主义世界体系，成为经济附庸。',
      quiz:{type:'choice',q:'标志着中国逐步丧失关税自主权的不平等条约是？',opts:['《南京条约》','《马关条约》','《辛丑条约》','《瑷珲条约》'],a:0,exp:'《南京条约》规定中英协定关税，是中国丧失关税自主权的开端。'}},
    {ch:'c1',title:'经济掠夺：商品倾销与资本输出',speak:'列强凭借特权向华倾销商品、输出资本，把中国变为其商品市场和原料基地。外国洋行垄断进出口贸易，19世纪90年代达500多家（怡和、太古、旗昌、礼和等）。1895年《马关条约》允许外资在华设厂，1895—1900年列强设厂总数达933家，资本雄厚、技术先进，压制中国民族工业。值得注意的是，列强在华投资相当部分并非来自国外，而是用战争赔款等方式掠自中国。',
      quiz:{type:'fill',q:'1895年《马关条约》允许外国人在华设厂后，1895—1900年列强在华设厂总数达______家。',answer:'933',exp:'1895—1900年列强在华设厂达933家，遍及中国各个工业部门。'}},
    {ch:'c1',title:'文化渗透：宗教外衣与为侵略制造舆论',speak:'列强文化渗透披着宗教外衣：传教士郭士立等为侵略刺探情报、参与起草条约，法国传教士私添条文使教会取得内地租买土地特权，不法活动激起反教斗争。它们还办报纸书刊为侵略制造舆论，广学会《万国公报》宣扬殖民奴化思想；美国“庚款兴学”资助留美，毛泽东指出其本质是帝国主义文化侵略。列强还鼓吹“种族优劣论”与“黄祸论”，为侵略压迫中国制造所谓“有理”的舆论。',
      quiz:{type:'choice',q:'毛泽东在哪篇文章中指出“庚款兴学”的实质是帝国主义的文化侵略？',opts:['《“友谊”，还是侵略？》','《论持久战》','《新民主主义论》','《矛盾论》'],a:0,exp:'毛泽东在《“友谊”，还是侵略？》一文中揭露“庚款兴学”的文化侵略实质。'}},

    /* ---- 第一章第三节（新增，基于教材PDF：反抗外国武装侵略的斗争） ---- */
    {ch:'c1',title:'人民群众的反侵略斗争',speak:'资本—帝国主义侵略中国，同时也是中国人民反抗侵略的过程。1841年5月三元里人民抗英，是中国近代史上中国人民第一次大规模的反侵略武装斗争。太平天国后期太平军重创洋枪队，击毙卜罗德、击伤华尔、打死勒伯勒东。台湾人民反割台，与黑旗军浴血奋战。1900年义和团及部分清军与八国联军殊死战斗，义和团运动在粉碎瓜分图谋中发挥重大作用。',
      quiz:{type:'choice',q:'中国近代史上中国人民第一次大规模的反侵略武装斗争是？',opts:['三元里人民抗英','太平天国运动','义和团运动','台湾人民反割台'],a:0,exp:'1841年5月三元里人民抗英，是近代中国人民第一次大规模反侵略武装斗争。'}},
    {ch:'c1',title:'爱国官兵的反侵略斗争',speak:'历次反侵略战争中，爱国官兵英勇顽强。左宗棠力主海防塞防并重，1876年起率军收复新疆，粉碎分裂势力，维护国家领土完整。中法战争中冯子材年近七十，取得镇南关大捷。甲午黄海海战，海军提督丁汝昌负伤仍激励将士，邓世昌指挥“致远”号英勇牺牲，林永升等管带殉国，重创日本舰队。爱国官兵用鲜血铸成中华民族的民族魂。',
      quiz:{type:'choice',q:'中法战争中取得镇南关大捷、年近七十的老将是？',opts:['冯子材','左宗棠','邓世昌','刘铭传'],a:0,exp:'1885年冯子材在镇南关大捷中大败法军，扭转战局。'}},
    {ch:'c1',title:'左宗棠收复新疆（海防塞防之争）',speak:'19世纪70年代，中亚阿古柏在英、俄支持下侵占新疆，日本又企图侵台，清政府内部出现“海防”与“塞防”之争。左宗棠力排众议，主张海防塞防并重，坚决要求收复新疆。1876年3月，他受命率军西征，历时两年浴血奋战，收复新疆，粉碎分裂势力，捍卫了国家领土主权完整，维护了民族尊严。',
      quiz:{type:'fill',q:'19世纪70年代，在清政府“海防”与“塞防”之争中，力主收复新疆并率军西征的是______。',answer:'左宗棠',exp:'左宗棠主张海防塞防并重，1876年起率军收复新疆，维护国家领土完整。'}},
    {ch:'c1',title:'镇南关大捷（冯子材）',speak:'中法战争中，1885年初法军进犯中越边境镇南关（今友谊关）。年近七十的老将冯子材激励诸军：“法军再入关，何颜见粤民？”率二子跃出搏战，诸军感奋俱随杀出，大败法军，取得镇南关大捷，扭转了战局，沉重打击了法国侵略者的嚣张气焰。',
      quiz:{type:'choice',q:'1885年取得镇南关大捷、年近七十率二子跃出搏战的老将是？',opts:['冯子材','左宗棠','邓世昌','刘铭传'],a:0,exp:'冯子材在镇南关大捷中大败法军，是中法战争的关键胜利。'}},
    {ch:'c1',title:'黄海海战与邓世昌殉国',speak:'1894年9月17日甲午黄海海战，北洋舰队与日本联合舰队主力决战。海军提督丁汝昌负伤仍坐甲板激励将士；“致远”号管带邓世昌在舰受伤下沉时下令向敌舰“吉野”猛撞，不幸中鱼雷牺牲，全舰250名官兵壮烈殉国；“经远”号管带林永升等亦殉国。此战重创日本舰队，粉碎其“聚歼清舰于黄海”的计划，爱国官兵用鲜血谱写反侵略战歌。',
      quiz:{type:'fill',q:'甲午黄海海战中，指挥“致远”号奋勇作战、不幸中雷牺牲的管带是______。',answer:'邓世昌',exp:'邓世昌在黄海海战指挥致远舰英勇殉国，是著名民族英雄。'}},
    {ch:'c1',title:'边疆危机与瓜分狂潮',speak:'19世纪70至90年代，资本主义向帝国主义过渡，列强掀起瓜分殖民地狂潮，中国陷入“边疆危机”：英侵西藏云南、法侵广西、俄侵新疆、日吞琉球侵台。甲午战争后瓜分达高潮：《马关条约》割台湾等刺激列强野心，俄德法“三国干涉还辽”，随后各国竞相租借港湾、划分势力范围，掀起了瓜分中国的狂潮。',
      quiz:{type:'fill',q:'甲午战后，俄、德、法三国以“干涉还辽有功”为由，向日本施压迫其放弃辽东半岛，史称 ______ 。',answer:'三国干涉还辽',exp:'三国干涉还辽后，列强竞相租借港湾、划分势力范围，掀起瓜分中国狂潮。'}},
    {ch:'c1',title:'义和团运动与瓜分中国图谋的破产',speak:'列强始终未能实现瓜分中国的图谋。重要原因是列强间矛盾互相制约；但根本原因是中华民族不屈不挠的反侵略斗争。1900年义和团兴起，廊坊大捷粉碎联军进犯北京计划，八国联军统帅瓦德西也认为“瓜分一事，实为下策”。列强转而采取“保全清政府”、实行“以华治华”。义和团虽有笼统排外、受欺骗、迷信落后等局限，但在粉碎瓜分图谋中发挥了重大历史作用。',
      quiz:{type:'choice',q:'帝国主义未能实现瓜分中国图谋的最根本原因是什么？',opts:['中华民族不屈不挠的反侵略斗争','列强间矛盾互相制约','清政府妥协求和','地理辽阔难以统治'],a:0,exp:'最根本原因是中国人民前赴后继的反侵略斗争，义和团等运动使列强不敢贸然瓜分。'}},
    {ch:'c1',title:'义和团运动的历史作用与局限性',speak:'义和团运动在粉碎帝国主义瓜分中国图谋中发挥了重大历史作用。八国联军统帅瓦德西也承认中国人民“尚含有无限蓬勃生气”，瓜分“实为下策”。但义和团也有历史局限：对帝国主义的认识停留在感性阶段，存在笼统排外主义错误；认识不到帝国主义联合封建地主阶级压迫人民的实质，曾受封建统治者欺骗；作为小生产者还有迷信、落后的倾向。孙中山后来评价其“勇锐之气殊不可当”，证明中华民族不可消灭。',
      quiz:{type:'choice',q:'下列关于义和团运动历史作用与评价的表述，正确的是？',opts:['在粉碎列强瓜分图谋中发挥重大作用','是一场彻底的反帝反封建革命','使中国摆脱了半殖民地命运','由资产阶级领导'],a:0,exp:'义和团虽有笼统排外等局限，但在粉碎帝国主义瓜分中国图谋中发挥了重大历史作用。'}},

    /* ---- 第一章第四节（新增，基于教材PDF：反侵略战争的失败与民族意识的觉醒） ---- */
    {ch:'c1',title:'反侵略战争失败的原因：社会制度腐败',speak:'从1840到1919年的反侵略战争，都以中国失败、签订丧权辱国条约告终。内因主要有二：一是社会制度腐败，二是经济技术落后，前者更根本。清王朝昏庸愚昧、官员贪污、将帅贪生，尤其害怕和压制人民群众。如林则徐等被革职，妥协派受重用；中法战争冯子材大捷却“中国不败而败”；甲午战争挪用海军军费贺寿；八国联军时慈禧转而镇压义和团求和。腐败的社会制度阻碍了人民动员，是屡败最重要原因。',
      quiz:{type:'fill',q:'毛泽东指出，近代反侵略战争失败的两个内因中，更根本的原因是 ______ 。',answer:'社会制度腐败',exp:'社会制度的腐败使经济技术落后长期得不到改变，是反侵略战争屡败最根本原因。'}},
    {ch:'c1',title:'反侵略战争失败的原因：经济技术落后',speak:'另一重要原因是国家综合实力尤其是经济技术和作战能力落后。西方经工业革命飞速发展，中国封建统治闭关锁国、夜郎自大，被远远抛在后面。鸦片战争中清军多持刀矛弓箭，英军已普遍使用步枪开花炮；清常备军虽多达80万，但装备、素质、实力悬殊。武器是重要因素但非决定因素，决定因素是人不是物；而反动统治阶级错误方针、压制人民动员，使失败不可避免。',
      quiz:{type:'choice',q:'关于反侵略战争失败，下列哪一表述正确？',opts:['武器是重要因素但不是决定因素','经济技术落后就不该反抗','武器决定一切','失败全因外敌太强'],a:0,exp:'教材强调：武器是战争重要因素但不是决定因素，决定因素是人不是物。'}},
    {ch:'c1',title:'民族意识的觉醒：师夷长技以制夷与早期维新',speak:'受鸦片战争刺激，少数爱国士大夫开始睁眼看世界、研究外国。林则徐是近代中国睁眼看世界第一人，主持编译《四洲志》；魏源据此编《海国图志》，提出“师夷长技以制夷”，主张学习西方军事科技以御外侮。19世纪70年代后，王韬、薛福成、郑观应等不仅主张学科技，还要求学西方政法经济；郑观应《盛世危言》主张发展民族工商业、与西人“商战”、设议院实行“君民共主”，具重要启蒙意义。',
      quiz:{type:'fill',q:'魏源在《海国图志》中提出“______”的思想，主张学习西方长处以抵御侵略。',answer:'师夷长技以制夷',exp:'魏源编《海国图志》，提出“师夷长技以制夷”，开启近代中国向西方学习的思潮。'}},
    {ch:'c1',title:'民族意识的觉醒：救亡图存与振兴中华',speak:'鸦片战争后民族觉醒尚朦胧；甲午战败割台偿款，才使中国人开始普遍觉醒。梁启超说“吾国四千余年大梦之唤醒，实自甲午战败……始也”。严复译《天演论》，以“物竞天择，适者生存”为危机意识提供理论根据；康有为在保国会演说痛陈危局；孙中山1894年创立兴中会，喊出“振兴中华”这一时代最强音。救亡图存成为时代主旋律，中华民族日益觉醒。',
      quiz:{type:'choice',q:'孙中山在创立兴中会时喊出的时代最强音是？',opts:['振兴中华','师夷长技以制夷','救亡','物竞天择'],a:0,exp:'1894年孙中山创立兴中会，喊出“振兴中华”的时代最强音。'}},
    {ch:'c1',title:'中法战争：“中国不败而败”',speak:'中法战争中，1885年3月老将冯子材在镇南关、谅山大败法军，使法国茹费理内阁垮台，中国战场占优。但清政府当权者力主避战求和，接受法国条件签订《中法新约》，并令前线停战撤兵。中法战争最终以“中国不败而败，法国不胜而胜”而告结束，暴露了清政府的腐败无能。',
      quiz:{type:'fill',q:'中法战争中国战场占优却签订《中法新约》，史称“中国不败而败，______ 不胜而胜”。',answer:'法国',exp:'中法战争“中国不败而败，法国不胜而胜”，反映清政府腐败妥协、畏战求和。'}},
    {ch:'c1',title:'魏源与《海国图志》：“师夷长技以制夷”',speak:'林则徐是近代中国睁眼看世界第一人，主持编译《四洲志》。魏源受林则徐嘱托，1843年编成《海国图志》，介绍世界各国史地，并提出“师夷长技以制夷”的思想，主张学习西方先进军事和科学技术，以期富国强兵、抵御侵略。这一主张开启了近代中国向西方学习的思潮。',
      quiz:{type:'fill',q:'魏源在《海国图志》中提出“______”的思想，主张学习西方长处以抵御侵略。',answer:'师夷长技以制夷',exp:'魏源《海国图志》提出“师夷长技以制夷”，开近代向西方学习之先河。'}},
    {ch:'c1',title:'严复与《天演论》：“物竞天择，适者生存”',speak:'甲午战败后，严复于1898年正式出版译著《天演论》，借用进化论“物竞天择，适者生存”的社会进化论思想，为中华民族的危机意识和民族觉醒提供了理论根据，警醒国人：中国若不变法自强，就会亡国灭种。《天演论》犹如振聋发聩的警世钟，极大促进了民族觉醒。',
      quiz:{type:'choice',q:'严复译《天演论》借用的核心思想是？',opts:['物竞天择，适者生存','师夷长技以制夷','君主立宪','平均地权'],a:0,exp:'严复《天演论》以“物竞天择，适者生存”警醒国人变法图强。'}},
    {ch:'c1',title:'孙中山与兴中会：“振兴中华”',speak:'甲午战败与瓜分狂潮使民族危机空前严重。1894年11月，孙中山在檀香山创立革命团体兴中会，指出“强邻环列，虎视鹰瞵”，中国面临瓜分豆剖之危，疾呼“亟拯斯民于水火，切扶大厦之将倾”，并喊出“振兴中华”这一时代最强音，成为民族复兴口号的源头。',
      quiz:{type:'choice',q:'1894年孙中山创立兴中会，喊出的时代最强音是？',opts:['振兴中华','救亡图存','师夷长技','物竞天择'],a:0,exp:'1894年孙中山创立兴中会，首次喊出“振兴中华”的时代最强音。'}},

    /* 大纲补缺：中国封建社会的主要矛盾 */
    {ch:'c1',title:'中国封建社会的主要矛盾与阶级结构',speak:'中国封建社会的主要矛盾，是地主阶级和农民阶级的矛盾。地主占有大部分土地并掌握国家政权，农民租种地主土地、承担沉重的地租赋税和徭役；封建国家又通过宗法等级制度和儒家思想教化维持统治秩序。这一矛盾贯穿封建社会始终，历代农民起义都是这一矛盾的集中表现。',
      quiz:{type:'choice',q:'鸦片战争前，中国封建社会的主要矛盾是？',opts:['地主阶级和农民阶级的矛盾','资产阶级和无产阶级的矛盾','帝国主义和中华民族的矛盾','大资产阶级和民族资产阶级的矛盾'],a:0,exp:'中国封建社会的主要矛盾是地主阶级和农民阶级的矛盾，这也是大纲第一章的识记要求。'}},

    /* ============ 第二章 ============ */
    {ch:'c2',title:'太平天国农民战争',speak:'1851年洪秀全发动金田起义，建号太平天国，定都天京，颁布《天朝田亩制度》，后期提出《资政新篇》。因农民阶级局限性和中外势力联合镇压而失败。',
      quiz:{type:'fill',q:'______ 年洪秀全发动金田起义，建号太平天国。',answer:'1851',exp:'1851 年太平天国运动爆发，是近代规模宏大的农民战争。'}},
    {ch:'c2',title:'洋务运动',speak:'洋务派以"自强""求富"为目标，兴办近代军事工业、民用企业，建立新式海陆军，创办新式学堂。它没有使中国富强，但开启了中国近代化。',
      quiz:{type:'choice',q:'洋务运动的根本局限性在于？',opts:['没有引进西方技术','不改变封建制度而单纯学习器物','完全排斥外国','只办教育不办工业'],a:1,exp:'洋务运动"中体西用"，不改变封建制度，因而难以实现富强目标。'}},
    {ch:'c2',title:'戊戌维新运动',speak:'1898年康有为、梁启超推动戊戌变法，主张君主立宪、发展资本主义。变法仅103天即被顽固势力镇压，证明改良道路在中国行不通。',
      quiz:{type:'fill',q:'1898 年戊戌变法又称" ______ 变法"，仅持续 103 天即失败。',answer:'百日',exp:'戊戌变法又称百日维新，1898 年，仅 103 天被镇压。'}},

    /* ---- 第二章第一节 太平天国运动的起落（新增，基于教材PDF：第二章-part0.pdf） ---- */
    {ch:'c2',title:'金田起义与太平天国政权的建立',speak:'鸦片战争后清政府加重盘剥、自然经济解体，农民反抗此起彼伏。1843年洪秀全创立拜上帝教；1851年1月在广西桂平金田村发动起义，建号太平天国；1853年3月占领南京，改名天京并定都，正式建立农民政权。',
      quiz:{type:'fill',q:'1851 年 1 月，洪秀全在广西桂平县 ______ 村发动起义，建号太平天国。',answer:'金田',exp:'1851 年 1 月金田起义，标志太平天国运动爆发。'}},
    {ch:'c2',title:'太平军的北伐、西征与军事全盛',speak:'定都天京后，太平军进行了北伐、西征和天京城外破围战。到 1856 年上半年，除北伐失利外，在湖北、江西、安徽和天京附近等战场均获重大胜利，控制了大片地区，达到军事上的全盛时期。',
      quiz:{type:'fill',q:'到 ______ 年上半年，太平天国在军事上达到全盛时期（除北伐失利外各战场告捷）。',answer:'1856',exp:'1856 年上半年太平天国军事全盛，北伐失利是主要挫折。'}},
    {ch:'c2',title:'《天朝田亩制度》：平均土地的社会改革方案',speak:'太平天国定都天京后颁布《天朝田亩制度》，是最能体现其社会理想和农民起义特色的纲领性文件。它按"凡天下田，天下人同耕"原则，将土地分 9 等、按人口平均分配，试图建立"无处不均匀，无人不饱暖"的理想社会。它否定封建土地所有制、表达农民土地渴望，具有进步意义，但具有不切实际的空想性质，未能付诸实行。',
      quiz:{type:'choice',q:'《天朝田亩制度》的核心土地分配原则是？',opts:['凡天下田，天下人同耕','平均地权','打土豪分田地','耕者有其田'],a:0,exp:'《天朝田亩制度》以"凡天下田，天下人同耕"原则平均分配土地。'}},
    {ch:'c2',title:'《资政新篇》：近代第一个发展资本主义的方案',speak:'1859 年洪仁玕从香港来到天京，提出统筹全局的改革方案《资政新篇》。政治上禁朋党、加强集权、学习西方法制；经济上发展近代工矿交通银行、奖励科技与机器制造、提倡雇佣劳动；外交上主张同外国平等通商、严禁鸦片。这是一个具有资本主义色彩的方案，洪秀全基本赞同并颁行，但限于历史条件未能实施。',
      quiz:{type:'fill',q:'太平天国后期由洪仁玕提出、具有资本主义色彩的改革发展方案是《 ______ 》。',answer:'资政新篇',exp:'《资政新篇》是近代中国第一个比较系统的发展资本主义的方案。'}},
    {ch:'c2',title:'天京事变：太平天国由盛转衰的分水岭',speak:'在军事胜利的同时，太平天国内部矛盾日益暴露。1856 年 9 月发生天京事变，东王杨秀清、北王韦昌辉先后被杀，翼王石达开率部出走。天京事变严重削弱了领导和军事力量，成为太平天国由盛转衰的分水岭。',
      quiz:{type:'fill',q:'1856 年 9 月发生的 ______ 事变，是太平天国由盛转衰的分水岭。',answer:'天京',exp:'天京事变导致领导集团分裂，太平天国由盛转衰。'}},
    {ch:'c2',title:'天京陷落与太平天国失败',speak:'天京事变后洪秀全提拔陈玉成、李秀成等青年将领，1859 年封洪仁玕为干王总理朝政，但已无法根本挽回败局。1864 年 6 月洪秀全病故，7 月天京被湘军攻破，太平天国起义失败。',
      quiz:{type:'fill',q:'______ 年 7 月，天京被湘军攻破，太平天国起义失败。',answer:'1864',exp:'1864 年天京陷落，标志太平天国农民战争失败。'}},
    {ch:'c2',title:'太平天国农民起义的历史意义',speak:'太平天国历时 14 载、转战 18 省，建立了与清王朝对峙的政权，是中国旧式农民战争的最高峰：《天朝田亩制度》完整表达了农民对土地的渴望，《资政新篇》是近代第一个发展资本主义的方案。它冲击了孔子和儒家经典的正统权威，有力打击了外国侵略势力，也是 19 世纪中叶亚洲民族解放运动中时间最久、规模最大、影响最深的一次。',
      quiz:{type:'choice',q:'太平天国起义在中国历史上地位是？',opts:['中国旧式农民战争的最高峰','第一次资产阶级革命','无产阶级革命开端','新民主主义革命起点'],a:0,exp:'太平天国是旧式农民战争的最高峰，兼具新的历史特点。'}},
    {ch:'c2',title:'太平天国失败原因（一）：农民阶级的历史局限性',speak:'农民阶级不是新的生产力和生产关系的代表，无法克服小生产者固有的阶级局限性，缺乏科学思想理论的指导，没有先进阶级的领导，因而无法从根本上提出完整的、正确的政治纲领和社会改革方案。这是其失败的根本原因。',
      quiz:{type:'fill',q:'太平天国失败的根本原因在于农民阶级不是 ______ 的代表。',answer:'新的生产力和生产关系',exp:'农民阶级受小生产局限，缺乏先进阶级领导与科学理论，难以成功。'}},
    {ch:'c2',title:'太平天国失败教训（二）：腐败、战略与宗教之失',speak:'太平天国后期领导集团滋生腐败、争权夺利，诸王大兴土木、彼此猜忌，严重削弱向心力。军事上战略失误，未能联合捻军，天京被围时洪秀全拒绝李秀成"让城别走"的建议而死守孤城。以拜上帝教发动群众却有害斗争，也未能把西方侵略者与人民群众区别开来。',
      quiz:{type:'fill',q:'天京被围时，洪秀全拒绝了李秀成" ______ "的建议，死守孤城导致最后失败。',answer:'让城别走',exp:'拒绝"让城别走"、死守天京是太平天国后期重大战略失误。'}},
    {ch:'c2',title:'太平天国的总体历史定位',speak:'太平天国起义表明，在半殖民地半封建的中国，农民具有伟大的革命潜力，但它自身不能担负起领导反帝反封建斗争取得胜利的重任。单纯的农民战争不可能完成争取民族独立和人民解放的历史任务，需要新的阶级来领导。',
      quiz:{type:'choice',q:'太平天国起义表明，在半殖民地半封建中国，单纯农民战争？',opts:['能完成反帝反封建任务','不可能完成争取民族独立和人民解放的历史任务','应长期坚持游击战','应放弃土地纲领'],a:1,exp:'农民有革命潜力，但单纯农民战争不能领导反帝反封建取得胜利。'}},

    /* ---- 第二章第二节 洋务运动的兴衰（新增，基于教材PDF：第二章-part1.pdf） ---- */
    {ch:'c2',title:'洋务运动的兴起与洋务派',speak:'洋务运动兴起于 19 世纪 60 年代初第二次鸦片战争结束后，是在清政府镇压太平天国、捻军起义的过程中出现的。封建统治阶级中的奕䜣、曾国藩、李鸿章、左宗棠、张之洞等主张引进西方武器装备与科学技术、创设近代企业，被称为"洋务派"。其目的首先是镇压农民起义，同时加强海防、边防并发展本集团实力。',
      quiz:{type:'fill',q:'洋务运动兴起于 19 世纪 ______ 年代初第二次鸦片战争结束后。',answer:'60',exp:'19 世纪 60 年代，洋务派在镇压农民起义与应对外患中兴办洋务。'}},
    {ch:'c2',title:'洋务运动的指导思想："中体西用"',speak:'最早较完整表述洋务指导思想的是冯桂芬，他在《校邠庐抗议》中提出"以中国之伦常名教为原本，辅以诸国富强之术"。这一思想后来在张之洞《劝学篇》中被概括为"中学为体，西学为用"，即以中国封建伦理纲常所维护的统治秩序为主体，用西方近代工业和技术为辅助，并以前者支配后者。',
      quiz:{type:'choice',q:'张之洞在《劝学篇》中将洋务指导思想概括为？',opts:['中学为体，西学为用','全盘西化','师夷长技以制夷','实业救国'],a:0,exp:'"中体西用"是洋务运动的指导思想，张之洞在《劝学篇》中系统概括。'}},
    {ch:'c2',title:'洋务派创办的近代军用工业',speak:'洋务派首先兴办官办军用工业。最早是 1861 年的安庆军械所；1865 年曾国藩支持、李鸿章筹办的上海江南制造总局是当时国内最大的兵工厂；同年金陵机器局、1866 年福州船政局（附设船政学堂，国内最大造船厂）、1867 年天津机器局、1890 年张之洞创办湖北枪炮厂，均为重要军工企业。',
      quiz:{type:'fill',q:'1865 年曾国藩支持、李鸿章筹办的 ______ 是当时国内最大的兵工厂。',answer:'江南制造总局',exp:'江南制造总局是洋务派创办的规模最大的军事工业。'}},
    {ch:'c2',title:'洋务派创办的民用企业（官督商办）',speak:'除少数官办、官商合办外，洋务派民用企业多数采取官督商办方式。最重要的官督商办企业有轮船招商局、开平矿务局、天津电报局和上海机器织布局，多由李鸿章筹办或控制。这些企业虽受官僚控制、发展受限，但基本上是资本主义性质的近代企业。',
      quiz:{type:'choice',q:'洋务派民用企业多数采取哪种经营方式？',opts:['官督商办','完全商办','外资独资','中外合资'],a:0,exp:'轮船招商局、开平矿务局等民用企业多采取官督商办方式。'}},
    {ch:'c2',title:'建立新式海陆军',speak:'19 世纪 60 年代起，京师及天津、上海、广州、福州等地军队纷纷改用洋枪洋炮、聘用外国教练，淮军、湘军也装备洋枪。1874 年日本侵台后，清政府筹办海防、建设海军。19 世纪 70—90 年代，先后建成福建、广东、南洋、北洋四支水师，其中北洋水师是海军主力，拥有舰艇 20 多艘，一直归李鸿章管辖。',
      quiz:{type:'fill',q:'洋务派建立的海军中，______ 水师是清政府海军主力，一直归李鸿章管辖。',answer:'北洋',exp:'北洋水师是洋务派海军主力，甲午战争中全军覆没。'}},
    {ch:'c2',title:'创办新式学堂与派遣留学生',speak:'洋务派创办的新式学堂主要有三类：翻译学堂（如京师同文馆，培养翻译人才）、工艺学堂（培养电报、铁路、矿务、西医等专门人才）、军事学堂（如船政学堂，培养海军人才）。同时先后派遣赴美幼童和官费赴欧留学生 200 多人，开中国近代教育之先声。',
      quiz:{type:'fill',q:'洋务派创办的培养翻译人才的新式学堂是京师 ______ 馆。',answer:'同文',exp:'京师同文馆是洋务派创办的翻译学堂，培养外交翻译人才。'}},
    {ch:'c2',title:'洋务运动的历史作用',speak:'洋务运动提出"自强""求富"，优先发展军事工业并发展若干民用企业，在客观上对中国的早期工业和民族资本主义的发展起了促进作用。它开办新式学堂、派出最早官派留学生，是中国近代教育的开始；同时翻译近代自然科学书籍，开阔了眼界。伴随资本主义生产方式出现，传统"重本抑末"观念受冲击，工商业者地位上升，社会风气和价值观念开始变化。',
      quiz:{type:'choice',q:'洋务运动客观上促进了中国早期工业和什么的发展？',opts:['民族资本主义','小农经济','自然经济','宗法制度'],a:0,exp:'洋务新政在客观上对早期工业和民族资本主义起了某些促进作用。'}},
    {ch:'c2',title:'洋务运动失败的标志：甲午战争北洋海军覆没',speak:'洋务运动历时 30 多年，虽办起一批企业、建立海军，却未使中国富强。甲午战争中，洋务派经营多年的北洋海军全军覆没，标志着以"自强""求富"为目标的洋务运动失败。',
      quiz:{type:'choice',q:'标志洋务运动失败的历史事件是？',opts:['甲午战争北洋海军全军覆没','鸦片战争失败','八国联军侵华','中法战争'],a:0,exp:'甲午一战北洋海军覆没，标志洋务运动失败。'}},
    {ch:'c2',title:'洋务运动失败原因（一）：封建性',speak:'洋务运动具有封建性。其指导思想"中体西用"企图以西方近代生产技术为手段来维护封建统治，但新的生产力不可能在封建主义桎梏下充分发展。洋务派既要发展近代企业，又用垄断经营、侵吞商股等手段压制民族资本；既想培养洋务人才，又不愿改变封建科举制度，注定必然失败。',
      quiz:{type:'choice',q:'洋务运动失败的根本原因在于其具有？',opts:['封建性','革命性','进步性','国际性'],a:0,exp:'洋务运动的指导思想"中体西用"决定了其封建性，必然失败。'}},
    {ch:'c2',title:'洋务运动失败原因（二）：对外依赖性与管理腐朽性',speak:'洋务运动对列强具有依赖性：清政府已签一批不平等条约，列强并不希望中国真正富强；洋务派却主张对外"和戎"，所办企业一切仰赖外国，无异于与虎谋皮。同时洋务企业管理具有腐朽性，基本仍是封建衙门式管理，不讲效益、质量低下，官督商办企业商人无发言权，内部充斥营私舞弊、贪污受贿等官场恶习。',
      quiz:{type:'choice',q:'洋务企业"管理上具有腐朽性"，其管理基本是哪种方式？',opts:['封建衙门式','现代公司制','股份制','合作社制'],a:0,exp:'洋务企业管理基本仍是封建衙门式，腐败低效。'}},

    /* ---- 第二章第三节 维新运动的兴起和夭折（新增，基于教材PDF：第二章-part2.pdf） ---- */
    {ch:'c2',title:'戊戌维新运动的兴起背景与维新派',speak:'19 世纪 90 年代以后，中国民族资本主义有了初步发展，1895—1898 年出现民族资本设厂高潮。甲午惨败造成新的民族危机，激发新的民族觉醒。站在救亡图存和变法维新前列的，是代表民族资本主义发展要求的知识分子。以康有为、梁启超、谭嗣同、严复等为主要代表的资产阶级维新派，把向西方学习推进到学习资本主义政治制度和思想文化的新高度。',
      quiz:{type:'choice',q:'甲午战争惨败后，站在救亡图存和变法维新前列的是代表什么发展要求的知识分子？',opts:['民族资本主义','小农经济','官僚地主','外国资本'],a:0,exp:'维新派代表民族资本主义发展要求，主张学习西方政治制度。'}},
    {ch:'c2',title:'维新派倡导变法的活动',speak:'维新派采取多种方式宣传主张：向皇帝上书（康有为多次上书，1895 年联合 1300 多名举人发起"公车上书"）；著书立说（康有为《新学伪经考》《孔子改制考》、梁启超《变法通议》、谭嗣同《仁学》、严复译《天演论》）；介绍外国变法经验（如《日本变政考》）；办学会（强学会、南学会、保国会）；设学堂（万木草堂、时务学堂）；办报纸（上海《时务报》、天津《国闻报》、湖南《湘报》）。重点争取光绪皇帝及帝党官员支持，图谋自上而下变法。',
      quiz:{type:'fill',q:'1895 年康有为联合 1300 多名举人发起的请愿运动是" ______ 上书"。',answer:'公车',exp:'"公车上书"是维新派自下而上推动变法的重要开端。'}},
    {ch:'c2',title:'维新派与守旧派的论战',speak:'维新派与守旧派、洋务派展开激烈论战，围绕三大问题：第一，要不要变法（维新派主张"变者，天下之公理也"）；第二，要不要兴民权、设议院、实行君主立宪（谭嗣同"君末也，民本也"，严复"民之公产"）；第三，要不要废八股、改科举、兴西学（严复"民智者，富强之原"）。这场论战实质上是资产阶级思想与封建主义思想在中国的第一次正面交锋，开阔了知识分子眼界，为戊戌变法拉开帷幕。',
      quiz:{type:'choice',q:'维新派与守旧派的论战，实质上是资产阶级思想与什么思想在中国的第一次正面交锋？',opts:['封建主义','资本主义','帝国主义','无政府主义'],a:0,exp:'这场论战是资产阶级思想与封建主义思想的第一次正面交锋。'}},
    {ch:'c2',title:'昙花一现的百日维新',speak:'1898 年 6 月 11 日，光绪皇帝颁布"明定国是"谕旨，宣布变法，此后 103 天接连发布新政政令，史称"戊戌变法"，又称"百日维新"。内容包括：政治上裁冗员、澄清吏治；经济上保护农工商业、设农工商总局；军事上裁旧练新；文教上创设京师大学堂、废八股、兴西学。这是一场资产阶级性质的改良运动，但新政未采纳开国会、定宪法等主张，未触及封建制度根本，是温和而不彻底的改革方案。',
      quiz:{type:'fill',q:'1898 年 6 月 11 日光绪帝颁布"明定国是"谕旨，史称"戊戌变法"，又称" ______ 维新"。',answer:'百日',exp:'戊戌变法仅持续 103 天，故称"百日维新"。'}},
    {ch:'c2',title:'戊戌政变与戊戌六君子',speak:'守旧势力于 1898 年 9 月 21 日发动政变，慈禧太后以"训政"名义重新独揽大权，将光绪帝软禁于中南海瀛台，搜捕维新人士。康有为、梁启超逃亡海外；谭嗣同拒绝出走，慨言"请自嗣同始"。9 月 28 日，谭嗣同、刘光第、林旭、杨锐、杨深秀、康广仁 6 人被害，史称"戊戌六君子"。除京师大学堂外新政多被废除，戊戌政变标志维新运动失败。',
      quiz:{type:'fill',q:'1898 年 9 月 28 日谭嗣同等六人被害，史称" ______ 六君子"。',answer:'戊戌',exp:'戊戌六君子就义，标志戊戌维新运动失败。'}},
    {ch:'c2',title:'戊戌维新运动的历史意义',speak:'戊戌维新运动虽失败，但有重大历史意义：第一，是一次爱国救亡运动，高举救亡图存旗帜，推动中华民族觉醒；第二，是一场资产阶级性质的政治改良运动，突破洋务派"中体西用"局限，主张以君主立宪取代君主专制，在政治经济领域一定程度冲击了封建制度；第三，更是一场思想启蒙运动，传播西方社会政治学说与自然科学，批判封建君权纲常，推动"诗界革命""史学革命"等文化革新，促进近代教育发展。',
      quiz:{type:'choice',q:'戊戌维新运动是一场什么性质的政治改良运动？',opts:['资产阶级','无产阶级','农民阶级','地主阶级'],a:0,exp:'戊戌维新是资产阶级性质的改良运动，主张君主立宪。'}},
    {ch:'c2',title:'戊戌维新运动失败的原因',speak:'戊戌维新失败，主要是由于维新派自身的局限以及以慈禧太后为首的强大的守旧势力的反对。当时民族资本主义经济力量微弱，民族资产阶级社会基础狭窄，维新派势力非常弱小，既无严密组织，也不掌握实权和军队，更没有发动群众，只能把希望寄托在毫无实权的光绪皇帝身上，因而难免失败。',
      quiz:{type:'fill',q:'戊戌维新失败主要是由于维新派自身局限及以 ______ 太后为首的守旧势力反对。',answer:'慈禧',exp:'以慈禧太后为首的守旧势力发动戊戌政变，扼杀维新。'}},
    {ch:'c2',title:'维新派的局限性（一）：不敢否定封建主义',speak:'维新派自身的局限性突出表现为三方面。首先，不敢否定封建主义：政治上不敢根本否定封建君主制度，只幻想依靠光绪皇帝"以君权雷厉风行"实现自上而下改良；经济上要求发展民族资本主义，却未触及封建经济基础——封建土地所有制；思想上提倡西学，却仍打着孔子旗号，借古代圣贤之名"托古改制"。',
      quiz:{type:'choice',q:'维新派在政治上不敢根本否定什么制度，只幻想依靠光绪帝改良？',opts:['封建君主制度','科举制度','八股取士','缠足陋习'],a:0,exp:'维新派不敢根本否定封建君主制，改良道路不彻底。'}},
    {ch:'c2',title:'维新派的局限性（二、三）：幻想列强与惧怕群众',speak:'其次，对帝国主义抱有幻想：维新派大声疾呼救亡，却幻想西方列强帮助自己，甚至建议聘请日本前首相伊藤博文任维新顾问，政变前夕分别乞求英、美、日公使支持均落空。最后，惧怕人民群众：维新派活动局限于官僚士大夫和知识分子小圈子，脱离甚至仇视群众，只得依靠掌兵权的袁世凯，反被其出卖；一旦守旧派反击便毫无抵抗之力。谭嗣同"有心杀贼，无力回天"正道出这一点。',
      quiz:{type:'fill',q:'维新派幻想依靠英、日帮助，甚至建议聘请日本前首相 ______ 任维新顾问。',answer:'伊藤博文',exp:'维新派对帝国主义抱有幻想，终致乞求列强支持落空。'}},
    {ch:'c2',title:'戊戌维新运动的历史定位',speak:'戊戌维新运动的失败表明，在半殖民地半封建的旧中国，企图通过统治者走自上而下的改良道路根本行不通，必须用革命的手段，推翻帝国主义、封建主义联合统治的半殖民地半封建的社会制度。"戊戌六君子"流血的教训，促使一部分人放弃改良主张，开始走上革命的道路。',
      quiz:{type:'choice',q:'戊戌维新的失败表明，在旧中国企图通过统治者走什么道路根本行不通？',opts:['自上而下的改良道路','武装革命道路','农民起义道路','实业救国道路'],a:0,exp:'改良道路行不通，必须用革命手段推翻半殖民地半封建制度。'}},

    /* 大纲补缺：总理各国事务衙门、早期维新思想家 */
    {ch:'c2',title:'总理各国事务衙门',speak:'1861年清政府设立总理各国事务衙门，简称总理衙门，主管外交与通商事务，后来职权扩大到军事、矿务、铁路、电报、海关等，成为洋务运动的中枢机构。它是近代中国第一个常设的外交机构，1901年《辛丑条约》后改为外务部，班列六部之前。',
      quiz:{type:'fill',q:'1861年清政府设立 ______ ，成为洋务运动的中枢机构。',answer:'总理各国事务衙门',exp:'总理各国事务衙门是洋务运动的中枢机构，也是近代中国第一个常设外交机构。'}},
    {ch:'c2',title:'早期维新思想家及其主张',speak:'19世纪70年代以后，王韬、郑观应、马建忠、薛福成等早期维新思想家提出：发展民族工商业，同外国进行“商战”；设立议院、实行君主立宪；兴办学校、废除科举、学习西方政治制度。郑观应著《盛世危言》，主张“商战”和“开设议院”，为戊戌维新运动作了思想准备。',
      quiz:{type:'choice',q:'主张“商战”、著有《盛世危言》的早期维新思想家是？',opts:['郑观应','王韬','严复','康有为'],a:0,exp:'郑观应《盛世危言》主张“商战”与“开设议院”，是早期维新思想的代表作。'}},

    /* ============ 第三章 ============ */
    {ch:'c3',title:'辛亥革命的历史条件与三民主义',speak:'辛亥革命爆发于民族危机加深、清末"新政"破产之际。孙中山提出民族、民权、民生三民主义，成为革命的指导思想。',
      quiz:{type:'choice',q:'三民主义不包括下列哪一项？',opts:['民族主义','民权主义','民生主义','民主主义'],a:3,exp:'三民主义是民族、民权、民生三大主义。'}},
    {ch:'c3',title:'辛亥革命与中华民国的建立',speak:'1911年武昌起义点燃辛亥革命，1912年中华民国建立，清帝退位，结束了两千多年的君主专制制度，但革命果实被袁世凯窃取。',
      quiz:{type:'fill',q:'______ 年中华民国建立，结束了两千多年的君主专制制度。',answer:'1912',exp:'1912 年中华民国成立，清朝统治终结，帝制结束。'}},
    {ch:'c3',title:'北洋军阀统治与旧民主主义革命的失败',speak:'袁世凯死后北洋军阀割据混战，实行专制统治。辛亥革命未能完成反帝反封建任务，证明资产阶级共和国方案在中国行不通。',
      quiz:{type:'choice',q:'辛亥革命失败的根本原因在于？',opts:['革命党人不够英勇','资产阶级的软弱性和妥协性','列强支持革命','民众反对共和'],a:1,exp:'资产阶级的软弱性和妥协性，使辛亥革命未能完成反帝反封建任务。'}},

    /* ---- 第三章第一节 举起近代民族民主革命的旗帜（新增，基于教材PDF：第三章-part0.pdf） ---- */
    {ch:'c3',title:'辛亥革命爆发的背景：民族危机与社会矛盾',speak:'戊戌维新失败后，革命派掀起资产阶级革命运动。20 世纪初，《辛丑条约》后列强加强对清政府政治控制、扩张在华经济势力（日俄战争在中国东北开战、英国侵藏）；清政府为支付巨额赔款横征暴敛，民怨沸腾。1902—1911 年间各地较大规模民变多达 1300 余起，包括反洋教、抗租抗捐、罢工罢市、拒俄拒法、抵制美货、收回利权与保路运动等。中外反动派的严重压迫使人民群众已不能照旧生活下去。',
      quiz:{type:'choice',q:'20世纪初，标志清政府彻底沦为"洋人的朝廷"的条约是？',opts:['《辛丑条约》','《马关条约》','《南京条约》','《天津条约》'],a:0,exp:'《辛丑条约》签订后清政府甘当"洋人的朝廷"，民族危机进一步加深。'}},
    {ch:'c3',title:'清末"新政"及其破产',speak:'为摆脱困境，清政府于 1901 年设督办政务处宣布"新政"，推行设商部学部巡警部、建新军、奖励工商、鼓励留学、1906 年起废科举等措施；又于 1906 年"预备仿行宪政"、1908 年颁布《钦定宪法大纲》、定 9 年预备期。但其根本目的是延续反动统治，迟迟不答应立即召开国会，镇压立宪请愿，借立宪加强皇权。1911 年 5 月"皇族内阁"（13 名大臣中满 9 人、皇族 7 人）使立宪派大失所望、统治集团分崩离析，表明清政府已无法照旧统治下去。',
      quiz:{type:'fill',q:'1911 年 5 月清政府成立的责任内阁被讥为" ______ 内阁"（13 名大臣中皇族占 7 人）。',answer:'皇族',exp:'"皇族内阁"暴露清廷假立宪真专制的面目，加速其统治危机。'}},
    {ch:'c3',title:'资产阶级革命派的阶级基础与骨干力量',speak:'19 世纪末 20 世纪初中国民族资本主义初步发展：1895—1911 年新设资本额超万元的民族资本厂矿达 800 家、资本超 1.6 亿元。民族资产阶级为冲破帝国主义、封建主义桎梏需要自己的政治代言人，这是革命派形成的阶级基础。革命派的骨干是一批资产阶级、小资产阶级知识分子——与戊戌维新及清末兴学堂、派留学生有关；留日学生最多时近万人，这些人成为辛亥革命的中坚力量。',
      quiz:{type:'fill',q:'中国资产阶级民主革命的阶级基础是 ______ 阶级的初步发展。',answer:'民族资本',exp:'民族资本主义初步发展为革命派提供了阶级基础。'}},
    {ch:'c3',title:'孙中山与民主革命的开始：兴中会的建立',speak:'革命根本上由外国侵略者和本国封建统治者逼迫而出。孙中山早年也曾尝试和平改革——1894 年北上天津向李鸿章上书，提出"人能尽其才，地能尽其利，物能尽其用，货能畅其流"，未被重视。他目睹清政府腐败，决心以革命推翻清朝，同年 11 月在檀香山组建第一个革命团体兴中会，立誓"驱除鞑虏，恢复中国，创立合众政府"；1895 年策划广州起义失败流亡海外。1904 年发表《中国问题的真解决》，主张以"中华民国"代替旧政府，高举民主革命旗帜、选择武装起义道路，这是革命派与改良派的根本不同。',
      quiz:{type:'fill',q:'1894 年 11 月孙中山在檀香山组建的第一个革命团体是 ______ 会。',answer:'兴中',exp:'兴中会是孙中山创立的第一个革命团体，标志其走上革命道路。'}},
    {ch:'c3',title:'革命派的宣传与组织：革命著作与革命团体',speak:'20 世纪初革命书刊涌现，民主革命思想广泛传播：1903 年章炳麟发表《驳康有为论革命书》歌颂革命为"除旧布新"良药；18 岁留日学生邹容写《革命军》号召建立"中华共和国"；陈天华写《警世钟》《猛回头》揭露清政府已成"洋人的朝廷"。在思想传播中，1904 年起华兴会、科学补习所、光复会、岳王会等革命团体次第成立，为革命提供组织力量。',
      quiz:{type:'choice',q:'下列哪部著作是邹容为号召推翻清朝、建立"中华共和国"所写？',opts:['《革命军》','《驳康有为论革命书》','《猛回头》','《建国方略》'],a:0,exp:'邹容《革命军》热情讴歌革命，号召建立中华共和国。'}},
    {ch:'c3',title:'中国同盟会的成立',speak:'1905 年 8 月 20 日，孙中山和黄兴、宋教仁等以兴中会、华兴会为基础，在日本东京成立中国同盟会，孙中山被公举为总理，黄兴任执行部庶务主持日常工作。同盟会以《民报》为机关报并确定革命纲领，是近代中国第一个领导资产阶级革命的全国性政党。其成员 98% 以上是中小资产阶级及其知识分子，它的成立标志着中国资产阶级民主革命进入新阶段。',
      quiz:{type:'fill',q:'1905 年 8 月 20 日在日本东京成立的近代中国第一个全国性资产阶级革命政党是 ______ 会。',answer:'中国同盟',exp:'同盟会是第一个领导资产阶级革命的全国性政党。'}},
    {ch:'c3',title:'三民主义的提出',speak:'同盟会政治纲领为"驱除鞑虏，恢复中华，创立民国，平均地权"。1905 年 11 月，孙中山在《民报》发刊词中将纲领概括为三大主义，即民族主义、民权主义、民生主义，后称三民主义。这一学说初步描绘出中国还不曾有过的资产阶级共和国方案，是比较完整而明确的资产阶级民主革命纲领，对推动革命发展产生重大而积极影响。',
      quiz:{type:'choice',q:'1905 年孙中山在《民报》发刊词中将同盟会纲领概括为？',opts:['三民主义','新三民主义','三大政策','新民主主义'],a:0,exp:'《民报》发刊词中孙中山提出民族、民权、民生三大主义，即三民主义。'}},
    {ch:'c3',title:'民族主义："驱除鞑虏，恢复中华"',speak:'民族主义包括"驱除鞑虏，恢复中华"两项内容：一是以革命手段推翻清朝政府，改变其民族歧视与压迫政策；二是建立中华民族"独立的国家"。孙中山强调民族主义不是简单排满，不是针对一切满人，而是要扫除清政府的专制不平政治、暴虐刑罚、苛捐与纵容的虎狼官吏。但其局限在于：未从正面鲜明提出反帝主张，对帝国主义本质认识不清、甚至幻想以承认不平等条约换取列强支持；也未明确把汉族军阀官僚地主作为革命对象，给后来破坏革命以可乘之机。',
      quiz:{type:'choice',q:'同盟会纲领中的民族主义局限性在于？',opts:['未正面鲜明提出反帝主张','主张全盘排满','反对建立民国','主张平均地权'],a:0,exp:'民族主义未正面反帝、对帝国主义本质认识不清，是其局限。'}},
    {ch:'c3',title:'民权主义："创立民国"',speak:'民权主义的内容是"创立民国"，即推翻封建君主专制制度，建立资产阶级民主共和国，这是孙中山所说的政治革命。《军政府宣言》规定国民平等有参政权、大总统与议员由国民公举、制定宪法人人共守、敢有帝制自为者天下共击之。他强调政治革命应与民族革命并行，矛头直指集民族压迫与封建专制于一身的清政府。但其局限在于忽略了广大劳动群众在国家中的地位，难以真正保证人民的民主权利。',
      quiz:{type:'fill',q:'三民主义中，主张"推翻封建君主专制、建立资产阶级民主共和国"的是 ______ 主义。',answer:'民权',exp:'民权主义即"创立民国"，是政治革命的核心。'}},
    {ch:'c3',title:'民生主义："平均地权"',speak:'民生主义当时指"平均地权"，即孙中山所说的社会革命。他主张核定全国土地地价，现有地价仍属原主，革命后的增价则归国家为国民共享，国家可按原定地价收买地主土地，试图"举政治革命、社会革命毕其功于一役"，既使中国富强又避免贫富悬殊。但其局限在于没有正面触及封建土地所有制，不能满足广大农民的土地要求，难以成为发动工农群众的理论武器。',
      quiz:{type:'choice',q:'三民主义中，主张核定地价、土地增价归国家的"社会革命"是？',opts:['民生主义','民族主义','民权主义','民主主义'],a:0,exp:'民生主义即"平均地权"，是孙中山的社会革命主张。'}},
    {ch:'c3',title:'革命派与改良派的论战',speak:'1905—1907 年间，革命派与改良派分别以《民报》《新民丛报》为主要阵地，围绕中国应革命还是改良展开大论战。焦点之一：要不要以革命手段推翻清王朝——革命派指出清政府是帝国主义"鹰犬"，爱国必须革命，可"免瓜分之祸"；焦点之二：要不要推翻帝制、实行共和——革命派认为"政府恶劣"而非"国民恶劣"，民主共和大势所趋；焦点之三：要不要进行社会革命——革命派主张平均地权、实现土地国有。论战划清了革命与改良的界限，传播了民主革命思想，促进革命形势发展（也暴露革命派在反帝、依靠群众等方面的理论弱点）。',
      quiz:{type:'choice',q:'1905—1907 年革命派与改良派论战的主要阵地是《民报》对阵哪份报刊？',opts:['《新民丛报》','《时务报》','《国闻报》','《湘报》'],a:0,exp:'革命派《民报》与改良派《新民丛报》的大论战，划清了革命与改良界限。'}},

    /* ---- 第三章第二节（新增，基于教材PDF：辛亥革命与中华民国的建立） ---- */
    {ch:'c3',title:'辛亥革命的爆发：黄花岗起义与保路风潮',speak:'同盟会先后发动多次武装起义。影响最大的是 1911 年 4 月 27 日广州黄花岗起义，黄兴率 120 余敢死队员，大部牺牲，72 位烈士合葬于黄花岗。1911 年 5 月，清政府宣布"铁路干线收归国有"并借"国有"之名出卖利权，激起湖北、湖南、广东、四川四省保路风潮，其中以四川最烈；署理四川总督赵尔丰下令向请愿群众开枪，造成"成都血案"，全川掀起武装暴动，加速了革命的爆发。',
      quiz:{type:'fill',q:'1911 年 4 月 27 日广州起义中牺牲的 72 位烈士被合葬于 ______，史称黄花岗起义。',answer:'黄花岗',exp:'黄花岗起义是同盟会影响最大的武装起义，72 烈士葬于黄花岗。'}},
    {ch:'c3',title:'武昌首义与各地响应',speak:'1911 年 10 月 10 日晚，湖北新军中的共进会和文学社在武昌联合起义，工程第八营革命党人打响第一枪，占领楚望台军械所，血战通宵占领武昌，3 天内光复武汉三镇，成立湖北军政府。一个月内即有 13 个省及上海等宣布独立，清王朝土崩瓦解。1912 年 2 月 12 日清帝退位，中国延续两千多年的封建君主专制制度终于覆灭。',
      quiz:{type:'fill',q:'1911 年 10 月 10 日，湖北新军中的 ______ 和文学社在武昌发动起义，打响辛亥革命第一枪。',answer:'共进会',exp:'共进会与文学社在武昌联合发动起义，掀开辛亥革命高潮。'}},
    {ch:'c3',title:'革命派在政权更迭中的软弱与妥协',speak:'在武昌起义和各省政权更迭中，革命派既表现出革命性和勇敢，又暴露软弱性和妥协：他们不敢发动群众保卫政权，致使政权落到立宪派或旧官僚、旧军官手里。如湖北把原清军协统黎元洪硬拉为都督，湖南焦达峰、陈作新被害后推立宪派谭延闿为都督。革命发展很快但基础不牢，内外潜伏深刻危机。',
      quiz:{type:'choice',q:'武昌起义后，湖北革命党人把原清军协统 ______ 硬拉出来当了都督。',opts:['黎元洪','谭延闿','袁世凯','赵尔丰'],a:0,exp:'黎元洪被推为湖北军政府都督，反映革命派的妥协性。'}},
    {ch:'c3',title:'中华民国临时政府的成立',speak:'1911 年底孙中山从海外回到上海。独立各省代表在南京选举孙中山为临时大总统。1912 年 1 月 1 日，孙中山在南京宣誓就职，改国号为中华民国，定 1912 年为民国元年，成立中华民国临时政府。这是一个资产阶级共和国性质的革命政权，革命派在政权中占领导和主体地位，陆军、外交等重要部总长及所有次长均由革命党人担任，临时参议院中同盟会会员占多数。',
      quiz:{type:'fill',q:'1912 年 1 月 1 日，孙中山在 ______ 宣誓就职临时大总统，宣告中华民国成立，定 1912 年为民国元年。',answer:'南京',exp:'1912 年 1 月 1 日中华民国临时政府在南京成立。'}},
    {ch:'c3',title:'南京临时政府的政策措施',speak:'南京临时政府的政策集中代表民族资产阶级愿望，也符合广大人民利益：扫除封建弊端、保护人权；鼓励发展资本主义工商业，兴办工厂、矿山、银行、垦殖；宣布禁止刑讯、保护华侨、禁止贩卖华工、禁止买卖人口、废除奴婢、禁种禁吸鸦片；改革文化教育，否定忠君尊孔教育、废止小学读经、禁用清学部颁行教科书。',
      quiz:{type:'choice',q:'南京临时政府在文化教育上采取的重要措施不包括？',opts:['废止小学读经','否定忠君尊孔教育','恢复科举','禁用清学部教科书'],a:2,exp:'南京临时政府废止读经、否定忠君尊孔，并未恢复科举。'}},
    {ch:'c3',title:'南京临时政府的局限性',speak:'南京临时政府也有局限：在《告友邦书》中试图用承认清政府与列强所订一切不平等条约和所欠外债，来换取列强承认中华民国；同时没有提出任何满足农民土地要求的政策，反而以保护私有财产为借口，维护封建土地制度及官僚、地主所占有的土地和财产。',
      quiz:{type:'fill',q:'南京临时政府在《告友邦书》中承认清政府与列强所订的不平等条约和所欠外债，以换取列强承认 ______。',answer:'中华民国',exp:'《告友邦书》妥协承认不平等条约，暴露南京临时政府的外交软弱。'}},
    {ch:'c3',title:'《中华民国临时约法》：第一部资产阶级共和国宪法性质的法典',speak:'1912 年 3 月，临时参议院颁布《中华民国临时约法》，这是中国历史上第一部具有资产阶级共和国宪法性质的法典。它规定"中华民国之主权属于国民全体"，由参议院、临时大总统、国务员、法院分掌统治权；参议院行使立法权并可弹劾大总统和国务员；国民一律平等，享有人身、财产、集会、结社、出版、言论等自由及请愿、考试、选举与被选举权。它以根本大法废除两千年封建君主专制，确认资产阶级共和制度。毛泽东评价它"带有革命性、民主性"。',
      quiz:{type:'fill',q:'1912 年 3 月颁布的《中华民国临时约法》规定"中华民国之主权属于 ______ 全体"。',answer:'国民',exp:'《临时约法》以根本大法确认主权在民、资产阶级共和制度。'}},
    {ch:'c3',title:'辛亥革命的历史意义（一）（二）：推翻清王朝与终结帝制',speak:'辛亥革命是资产阶级领导的、以反对封建君主专制、建立资产阶级共和国为目的的较完全意义的资产阶级民主革命。意义一：推翻清王朝统治，沉重打击中外反动势力，使其再不能建立较稳定统治，为中国人民斗争开辟道路。意义二：结束延续两千多年的封建君主专制，建立中国第一个资产阶级共和政府，民主共和观念深入人心，形成"敢有帝制自为者，天下共击之"的观念；后来袁世凯、张勋先后复辟均遭谴责与反抗。',
      quiz:{type:'choice',q:'辛亥革命结束了延续两千多年的封建君主专制，使什么观念开始深入人心？',opts:['民主共和','君主立宪','君权神授','闭关锁国'],a:0,exp:'辛亥革命使民主共和观念深入人心，复辟帝制遭天下共击。'}},
    {ch:'c3',title:'辛亥革命的历史意义（三）（四）：思想解放与社会变革',speak:'意义三：推动思想解放。皇帝被看作至高无上的绝对权威，如今连皇帝都可被打倒，激发了人民爱国热情和民族觉醒，打开了禁锢思想进步的闸门。意义四：推动社会变革。南京临时政府设实业部、颁行有利工商业政策，使随后几年成为资本主义发展的"黄金时代"；提倡社会新风，以公元纪年改用公历，废除跪拜礼，以"先生""君"取代"老爷"等称呼，男子剪辫、女子放足之风席卷全国，改变社会风气、助益精神解放。',
      quiz:{type:'fill',q:'南京临时政府成立后以振兴实业为目标，使随后几年成为资本主义发展的" ______ 时代"。',answer:'黄金',exp:'辛亥革命后几年民族资本主义出现"黄金时代"。'}},
    {ch:'c3',title:'辛亥革命的历史意义（五）与总体评价',speak:'意义五：辛亥革命在一定程度上打击了帝国主义侵略势力，推动亚洲各国民族解放运动高涨。毛泽东指出"中国反帝反封建的资产阶级民主革命，正规地说起来，是从孙中山先生开始的"。辛亥革命是中国人民为救亡图存、振兴中华而奋起革命的一座里程碑，使中国发生历史性巨变；但它未能完成反帝反封建任务，证明资产阶级共和国方案在中国行不通。',
      quiz:{type:'choice',q:'毛泽东指出，中国反帝反封建的资产阶级民主革命"正规地说起来"是从谁开始的？',opts:['孙中山','康有为','李鸿章','洪秀全'],a:0,exp:'毛泽东评价辛亥革命正规说起来从孙中山开始，是较完全意义的民主革命。'}},

    /* ---- 第三章第三节（新增，基于教材PDF：北洋军阀统治与旧民主主义革命的失败） ---- */
    {ch:'c3',title:'袁世凯窃国与辛亥革命流产',speak:'辛亥革命虽取得巨大成功，仍以失败告终，南京临时政府仅存三个月便夭折。北洋军阀首领袁世凯在帝国主义、国内反动势力及附从革命的旧官僚、立宪派共同支持下窃夺果实。武昌起义后袁世凯以武力压迫革命派，列强调军舰助威、攻击孙中山；革命派内部也造"非袁莫属"舆论。孙中山被迫表示只要清帝退位、袁世凯拥护共和就让位，并附以南京为首都、总统南京就职、遵守约法三条件制约袁。袁世凯指使部下在北京发动"兵变"、列强调兵配合，迫使革命派再妥协。1912 年 3 月 10 日袁世凯在北京就任临时大总统，4 月 1 日孙中山正式卸任，临时政府迁往北京。',
      quiz:{type:'fill',q:'袁世凯不肯离开北京老巢，指使部下在北京发动" ______ "，西方列强也调兵进京配合，迫使革命派让步。',answer:'兵变',exp:'北京兵变是袁世凯迫使革命派妥协、在北京就任大总统的手段。'}},
    {ch:'c3',title:'北洋军阀的专制统治：政治上的独裁',speak:'袁世凯窃取果实后建立代表大地主、买办资产阶级利益的北洋军阀反动政权。政治上实行军阀官僚专制：大力扩充军队、建立特务警察系统，制定《暂行新刑律》《戒严法》等反动法令，剥夺《临时约法》赋予人民的言论、出版、集会、结社等权利，任意逮捕杀害革命党人。1912 年 8 月宋教仁联合组建国民党并在第一届国会选举获多数席位，试图推行责任内阁；1913 年 3 月袁世凯指使刺杀宋教仁，7—9 月镇压南方七省"二次革命"。同年 10 月袁指使军警流氓包围国会当选正式大总统，11 月解散国民党、收缴议员证书使国会无法开会，1914 年 1 月停止两院议员职务，5 月撕毁《临时约法》炮制《中华民国约法》以总统制取代内阁制，又修改《总统选举法》使大总统可无限期连任并推荐继承人，至此中华民国只剩一块空招牌。',
      quiz:{type:'fill',q:'1913 年 3 月，袁世凯指使心腹刺杀了试图组织责任内阁的国民党领袖 ______。',answer:'宋教仁',exp:'宋教仁被刺是袁世凯破坏资产阶级议会民主、走向独裁的关键一步。'}},
    {ch:'c3',title:'北洋军阀的专制统治：经济与思想文化',speak:'经济上，北洋政府竭力维护帝国主义、地主阶级和买办资产阶级利益。军阀、官僚本身是大地主，还以各种手段兼并土地（袁世凯在河南安阳等县占地 4 万多亩、奉系张作霖在东北占地 150 万亩），通过"清丈地亩"、苛捐杂税对农民敲骨吸髓；官僚买办资本集团如梁士诒的交通系控制了铁路和交通银行，操纵垄断财政金融与工矿运输。文化思想上，尊孔复古思潮猖獗：1913 年 6 月袁世凯发布《通令尊崇孔圣文》，恢复祀孔、祭孔典礼和跪拜礼节，中、小学恢复尊孔读经，保守势力甚至要求将孔教定为"国教"，攻击民主共和、宣传封建伦常。',
      quiz:{type:'choice',q:'以 ______ 为首的交通系集团控制了铁路和交通银行，操纵垄断财政金融与工矿运输。',opts:['梁士诒','张作霖','黎元洪','冯国璋'],a:0,exp:'梁士诒交通系是北洋时期典型的官僚买办资本集团。'}},
    {ch:'c3',title:'袁世凯复辟帝制及其失败',speak:'为达到专制独裁，袁世凯公然复辟帝制：1915 年 12 月 12 日发表接受帝位申令，中南海居仁堂受百官朝贺，31 日下令以 1916 年为"中华帝国洪宪元年"准备元旦登基。复辟遭举国反对，1916 年 1 月 1 日至 3 月 23 日他只当了 83 天皇帝便被迫取消帝制和洪宪年号。1917 年 6 月，前清官僚张勋率"辫子军"北上拥废帝溥仪复辟，仅 12 天即在全国声讨中失败。',
      quiz:{type:'fill',q:'1915 年 12 月袁世凯称帝，1916 年定为"中华帝国 ______ 元年"，但他只当了 83 天皇帝就被迫取消帝制。',answer:'洪宪',exp:'袁世凯洪宪帝制仅 83 天即破产，说明帝制已失民心。'}},
    {ch:'c3',title:'军阀割据局面的形成及其原因',speak:'袁世凯 1916 年称帝败亡后，连形式上的统一也维持不住，中国陷入军阀割据。原因深刻：一方面中国主要是地方性的农业经济，未形成统一的资本主义市场；另一方面帝国主义在中国采取划分势力范围的分裂剥削政策。各派系军阀为争夺中央政权或保持扩大地盘连年纷争、引发多次战乱，专制统治与割据混战给人民带来无穷灾难，极大破坏经济。总之北洋政府从政治、经济、文化思想对辛亥革命全面反攻倒算，中国重新落入黑暗深渊。',
      quiz:{type:'choice',q:'袁世凯败亡后中国陷入军阀割据，其深刻原因不包括？',opts:['地方性农业经济未形成统一市场','帝国主义划分势力范围分裂剥削','统一的资本主义市场已经形成','各派系军阀连年纷争'],a:2,exp:'恰恰是统一市场未能形成才导致割据，而非已经形成。'}},
    {ch:'c3',title:'挽救共和的努力：二次革命与中华革命党',speak:'辛亥革命失败后革命派内部分化：有人丧失革命意志，追逐官职利禄甚至投靠军阀；孙中山一度受袁世凯欺骗表示"十年不预政治"办实业。1913 年宋教仁被刺后，孙中山看清袁真面目，毅然发动武装反袁的"二次革命"，因北洋军事占优、国民党缺兵缺饷、内部分歧，仅坚持两个月便失败。1914 年孙中山在日本组织中华革命党坚持反袁武装斗争，但该党提不出动员群众的纲领，入党须宣誓绝对服从孙中山个人、带强烈宗派性，严重脱离群众，参加者少、社会影响小。',
      quiz:{type:'fill',q:'1913 年宋教仁被刺后，孙中山毅然发动武装反袁的" ______ 革命"，但因北洋军事占优、国民党缺乏兵饷，仅坚持两个月便失败。',answer:'二次',exp:'二次革命是革命派维护共和的第一次武装反抗，终告失败。'}},
    {ch:'c3',title:'护国运动与护法运动',speak:'1915 年 12 月 25 日蔡锷等在云南组织"护国军"宣布独立，很快形成席卷半个中国的护国运动；次年 3 月袁世凯在全国反对声中被迫取消帝制，不久忧惧而死。皖系段祺瑞掌权后变本加厉独裁卖国，拒绝恢复《临时约法》和国会，孙中山举起"护法"旗帜，但口号缺乏群众号召力，又不得不依靠与皖系有矛盾的西南军阀。1917 年 9 月广州成立以孙中山为大元帅的护法军政府并出师北伐，不久西南军阀勾结直系擅自停战、排挤孙中山，1918 年 5 月 21 日孙中山愤然离广州去上海，护法运动失败使他认识到"南与北如一丘之貉"。1919 年 10 月孙中山将中华革命党改组为中国国民党。',
      quiz:{type:'fill',q:'护法运动失败后，孙中山认识到"南与北如一丘之 ______ "，依靠南方军阀反对北洋军阀行不通。',answer:'貉',exp:'护法失败使孙中山看清南北军阀本质相同，须另寻出路。'}},
    {ch:'c3',title:'辛亥革命失败的根本原因：资本主义建国方案行不通',speak:'辛亥革命失败的的根本原因在于：在帝国主义时代、半殖民地半封建的中国，资本主义的建国方案行不通。当时先进中国人真诚希望建立独立富强的资产阶级共和国，但帝国主义决不容许中国成为独立富强的资产阶级共和国而失去占世界人口四分之一的剥削对象，遂用政治、外交、军事、经济、财政等手段破坏干涉中国革命，扶植支持其代理人袁世凯夺取政权，并与大地主大买办势力、旧官僚、立宪派勾结从内外绞杀革命。毛泽东说"帝国主义的侵略打破了中国人学西方的迷梦"，"先生老是侵略学生"，多次奋斗包括辛亥革命都失败了，教训深刻。',
      quiz:{type:'choice',q:'辛亥革命失败的"根本原因"在于？',opts:['资本主义建国方案在半殖民地半封建中国行不通','革命党人不够勇敢','列强过于强大不可战胜','农民反对革命'],a:0,exp:'根本在于帝国主义时代半殖民地半封建中国，资产阶级共和国方案行不通。'}},
    {ch:'c3',title:'辛亥革命失败的主观原因（一）：没有彻底的反帝反封建纲领',speak:'从主观方面看，领导者资产阶级革命派自身存在弱点错误。第一，没有提出彻底的反帝反封建革命纲领：未明确提出反帝口号，甚至幻想以妥协退让换取帝国主义承认支持；只强调反满和建立共和政体，未认识到必须反对整个封建统治阶级，致使一些汉族旧官僚、旧军官混入革命营垒，最后还把政权拱手让给袁世凯。孙中山后来总结妥协"实间接与帝国主义相调和，遂为革命第一次失败之根源"。',
      quiz:{type:'fill',q:'资产阶级革命派未明确提出反帝口号，甚至幻想以妥协退让换取帝国主义对中国革命的承认和支持，最终把政权拱手让给了 ______。',answer:'袁世凯',exp:'革命派妥协退让、未提反帝反封建纲领，是失败的主观原因之一。'}},
    {ch:'c3',title:'辛亥革命失败的主观原因（二）（三）：脱离群众与政党涣散',speak:'第二，不能充分发动和依靠人民群众。中国民族资产阶级同封建势力有千丝万缕联系，不敢依靠反封建主力军农民群众；推翻清政府后未进一步领导农民反封建斗争，革命根基单薄（毛泽东说国民革命需要大的农村变动，辛亥革命没有这个变动所以失败）。第三，不能建立坚强的革命政党作为团结一切革命力量的核心。同盟会内部组织松懈、派系纷杂，缺乏统一稳定的领导核心，甚至有人主张"革命军起，革命党消"、另建党派自立山头。孙中山指出辛亥革命失败"非袁氏兵力之强，实同党人心之涣"。这些弱点根源于中国民族资产阶级的软弱性和妥协性。',
      quiz:{type:'choice',q:'孙中山总结辛亥革命失败"非袁氏兵力之强，实同党人 ______ 之涣"。',opts:['心','兵','财','势'],a:0,exp:'同盟会组织松懈、人心涣散，是革命失败的主观原因。'}},
    {ch:'c3',title:'辛亥革命的历史教训与总体评价',speak:'毛泽东指出辛亥革命"有它胜利的地方，也有它失败的地方"：把皇帝赶跑是胜利，但只赶跑一个皇帝，中国仍在帝国主义和封建主义压迫之下，反帝反封建任务并未完成。辛亥革命表明资产阶级共和国方案没能救中国，先进中国人需要进行新的探索、为中国谋求新出路。但辛亥革命作为中国人民救亡图存、振兴中华的里程碑，使民主共和思想流传广远，十年后中国共产党宣告成立，共产党人继承发展孙中山革命事业并推进到新阶段。对他们的缺点要从历史条件出发说明，不可苛求前人。',
      quiz:{type:'choice',q:'毛泽东评价辛亥革命：把皇帝赶跑是胜利，但中国仍在帝国主义和封建主义压迫下，这说明？',opts:['反帝反封建的革命任务并未完成','革命完全失败毫无意义','应该立即建立社会主义','帝国主义已经退出中国'],a:0,exp:'辛亥革命只赶跑一个皇帝，反帝反封建任务未完成，须继续探索新出路。'}},

    /* ============ 第四章 ============ */
    {ch:'c4',title:'新文化运动和五四运动',speak:'新文化运动提倡民主与科学，解放思想；1919年五四运动中，工人阶级开始登上政治舞台，标志着新民主主义革命的开端。',
      quiz:{type:'choice',q:'区分新旧民主主义革命的根本标志是？',opts:['革命对象不同','领导权的变化','爆发地点不同','群众规模不同'],a:1,exp:'领导权的变化（无产阶级领导）是区分新旧民主主义革命的根本标志。'}},
    {ch:'c4',title:'马克思主义的传播与中国共产党的诞生',speak:'十月革命后马克思主义广泛传播，并与工人运动结合。1921年中共一大召开，中国共产党诞生，这是开天辟地的大事变。',
      quiz:{type:'fill',q:'中国共产党诞生于 ______ 年。',answer:'1921',exp:'1921 年中共一大召开，中国共产党应运而生。'}},
    {ch:'c4',title:'中国革命的新局面',speak:'党制定反帝反封建的民主革命纲领，发动工农运动，推动国共合作与北伐战争（大革命），虽遭失败但积累了宝贵经验。',
      quiz:{type:'choice',q:'中国共产党制定的民主革命纲领的核心目标是？',opts:['反帝反封建','单纯反满','发展资本主义','联省自治'],a:0,exp:'党的一大后制定反帝反封建的民主革命纲领，发动工农运动。'}},

    /* ---- 第四章第一节（新增，基于教材PDF：新文化运动和五四运动） ---- */
    {ch:'c4',title:'新文化运动的兴起及其历史背景',speak:'近代以来中国先进分子向西方寻找真理却一再碰壁，辛亥革命失败、北洋军阀建立更使人陷入绝望苦闷。一些知识分子认为以往救国斗争成效甚少，是因国民"若观对岸之火，熟视而无所容心"，故"欲图根本之救亡"须改造国民性，发动一场新的启蒙运动使人们从封建思想束缚中解放出来，即新文化运动。它从 1915 年 9 月陈独秀在上海创办《青年杂志》（后改名《新青年》）开始；1917 年 1 月蔡元培出任北大校长，聘陈独秀为文科学长，《新青年》编辑部迁北京，李大钊、鲁迅、胡适等加入成为主要撰稿人，《新青年》与北京大学成为新文化运动主要阵地。',
      quiz:{type:'fill',q:'新文化运动从 1915 年 9 月 ______ 在上海创办《青年杂志》（后改名《新青年》）开始。',answer:'陈独秀',exp:'陈独秀创办《新青年》是新文化运动兴起的标志。'}},
    {ch:'c4',title:'新文化运动的基本口号：民主与科学',speak:'新文化运动的基本口号是拥护"德先生"(Democracy)和"赛先生"(Science)，即提倡民主与科学。民主既指资产阶级民主主义制度，也指资产阶级民主主义思想；科学有广狭二义，狭义指自然科学，广义指社会科学。倡导者以进化论观点和个性解放思想为主要武器，猛烈抨击以孔子为代表的"往圣先贤"。',
      quiz:{type:'choice',q:'新文化运动的基本口号"德先生"和"赛先生"分别指？',opts:['民主与科学','民主与自由','科学与共和','自由与平等'],a:0,exp:'德先生(Democracy)民主、赛先生(Science)科学，是新文化运动两面旗帜。'}},
    {ch:'c4',title:'新文化运动的内容：批判孔学与文学革命',speak:'新文化运动的倡导者大力提倡新道德、反对旧道德，提倡新文学、反对旧文学，包括提倡白话文、反对文言文。通过批判孔学，动摇了封建正统思想的统治地位，在中国社会掀起一股思想解放的潮流。在封建主义仍居支配地位时，提倡资产阶级民主主义客观上仍有振聋发聩的作用，冲决了禁锢人们思想的闸门。',
      quiz:{type:'choice',q:'新文化运动中"提倡白话文、反对文言文"属于哪方面的主张？',opts:['文学革命','政治革命','经济改革','军事改革'],a:0,exp:'新文化运动提倡新文学反对旧文学、提倡白话文反对文言文，即文学革命。'}},
    {ch:'c4',title:'五四以前新文化运动的局限',speak:'五四以前的新文化运动也有局限：第一，倡导者批判孔学是为中国发展资本主义扫清障碍，但资产阶级共和国方案在中国行不通，提倡资产阶级民主主义并不能提供有效思想武器去认识、改造中国；第二，把改造国民性置于优先地位，但离开改造产生封建思想的社会环境的革命实践，仅靠少数人呐喊和有限宣传不可能根本改造国民性；第三，许多领导人物还没有马克思主义的批判精神，方法一般是资产阶级的，看问题很片面，"坏就是绝对的坏，好就是绝对的好"，形式主义影响了运动后来发展。',
      quiz:{type:'fill',q:'五四以前新文化运动的一个局限是：许多领导人物还没有 ______ 的批判精神，看问题往往好就是绝对的好、坏就是绝对的坏。',answer:'马克思主义',exp:'五四前新文化运动的倡导者多使用资产阶级方法，缺乏马克思主义批判精神。'}},
    {ch:'c4',title:'十月革命对中国先进分子的影响',speak:'1917 年俄国十月社会主义革命是具有划时代意义的世界性事件，昭示资本主义制度并非永恒，无产阶级和其他劳动群众可依靠自身力量创造维护绝大多数人利益的崭新社会制度。它发生在中国学习西方努力失败、先进分子陷于苦闷彷徨之时，使人看到民族解放新希望。其推动中国先进分子目光从西方转向东方、从资产阶级民主主义转向社会主义：一、发生在国情相同或近似的俄国，对中国先进分子有特殊吸引力，青年毛泽东称俄国式革命是"诸路皆走不通了的一个变计"；二、社会主义俄国反对帝国主义、以新平等态度对待中国，1919 年苏维埃第一次对华宣言放弃沙俄在华特权引起很大震动；三、俄国工农兵广泛发动赢得胜利的事实，给予中国先进分子新的革命方法启示，推动他们研究这个革命所遵循的主义。',
      quiz:{type:'fill',q:'1919 年苏维埃俄国第一次对华宣言声明放弃沙俄在中国攫取的一切特权，有力推动了 ______ 思想在中国的传播。',answer:'社会主义',exp:'苏俄对华宣言以平等态度对待中国，推动社会主义思想在华传播。'}},
    {ch:'c4',title:'社会主义思潮的纷然杂陈与马克思主义的选择',speak:'十月革命后中国思想界产生一批赞成俄国十月革命、具有初步共产主义思想的知识分子，社会主义形成有相当影响的思想潮流。但最初人们对社会主义只是朦胧向往，无政府主义、工团主义、基尔特（行会）社会主义、社会民主主义以及新村主义、泛劳动主义等各种社会主义流派在报刊上纷然杂陈，其中无政府主义占优势。中国先进分子是经过反复比较才选择了马克思主义的。',
      quiz:{type:'choice',q:'五四前后各种社会主义流派纷然杂陈，其中占优势的是？',opts:['无政府主义','马克思主义','基尔特社会主义','新村主义'],a:0,exp:'当时无政府主义在众多社会主义流派中占优势，先进分子经反复比较才选马克思主义。'}},
    {ch:'c4',title:'李大钊率先举起马克思主义旗帜',speak:'在中国大地上率先举起马克思主义旗帜的是李大钊。他从爱国立场出发，从民主主义者转变为共产主义者。从 1918 年 7 月起，他先后发表《法俄革命之比较观》《庶民的胜利》《Bolshevism 的胜利》等文，热情讴歌十月革命胜利，指出它是"二十世纪中世界革命的先声"，确信"将来的环球，必是赤旗的世界"。五四后他更致力宣传马克思主义；1919 年 9 月、11 月发表《我的马克思主义观》，比较系统地介绍马克思主义理论，在当时思想界产生重大影响，标志着马克思主义在中国进入比较系统的传播阶段。',
      quiz:{type:'fill',q:'1919 年 9 月、11 月，______ 发表《我的马克思主义观》，比较系统地介绍马克思主义理论，标志马克思主义在中国进入比较系统的传播阶段。',answer:'李大钊',exp:'李大钊《我的马克思主义观》是马克思主义在华系统传播的标志。'}},
    {ch:'c4',title:'五四运动爆发的时代条件与社会历史背景',speak:'1919 年五四运动是在新的时代条件和社会历史条件下发生的。首先，新的社会力量成长壮大：一战期间中国资本主义经济迅速发展，资产阶级和工人阶级进一步成长，五四前夕中国产业工人已达 200 万人左右，使运动获得比以往更广泛的群众基础。其次，新文化运动掀起的思想解放潮流，尤其是具有初步共产主义思想的知识分子，为运动准备了最初的群众队伍和骨干力量。最后，是俄国十月革命的影响，毛泽东指出俄罗斯以民众大联合打倒贵族、驱逐富人的事实震动全世界，"异军特起，更有中华长城渤海之间，发生了“五四”运动”。',
      quiz:{type:'fill',q:'五四运动前夕，中国产业工人已达 ______ 万人左右，使运动获得比以往革命斗争更广泛的群众基础。',answer:'200',exp:'一战期间中国工人阶级成长，五四前夕产业工人约 200 万，成为运动主力。'}},
    {ch:'c4',title:'五四运动的直接导火线：巴黎和会外交失败',speak:'五四运动的直接导火线是巴黎和会上中国外交的失败。1919 年 1 月召开的巴黎和会上，中国政府代表提出废除外国在华势力范围、撤退外国驻军等七项希望和取消日本强加的"二十一条"及换文的陈述书，均遭拒绝；这个由西方列强把持的会议竟规定德国应将在中国山东获得的一切特权转交给日本，北洋政府居然准备在这一和约上签字。消息传到国内，激起各阶层人民强烈愤怒。',
      quiz:{type:'choice',q:'五四运动的直接导火线是？',opts:['巴黎和会上中国外交失败','五四运动前的学生游行','新文化运动的兴起','十月革命的胜利'],a:0,exp:'巴黎和会竟将德国在山东特权转交日本，北洋政府准备签字，成为五四导火线。'}},
    {ch:'c4',title:'五四运动的经过与群众斗争的发展',speak:'五四运动开始时，英勇出现在斗争前面的是学生。1919 年 5 月 4 日，北大等北京十几所学校三千余名学生冲破阻拦在天安门前集会，提出"外争主权、内除国贼""取消二十一条""还我青岛"等口号并示威游行。学生爱国行动遭北洋政府严厉镇压。在此关口，中国工人阶级开始以独立的姿态登上政治舞台：从 6 月 5 日起，上海六七万工人为声援学生先后罢工，推动商人罢市、学生罢课，运动扩展到 20 多个省区、100 多个城市。五四运动突破知识分子狭小范围，成为有工人、小资产阶级和民族资产阶级参加的全国规模革命运动；斗争主力由学生转向工人，中心由北京转到上海。迫于压力，北洋政府释放被捕学生、罢免亲日派官僚曹汝霖、章宗祥、陆宗舆，6 月 28 日中国代表未出席巴黎和约签字仪式，直接斗争目标实现。',
      quiz:{type:'fill',q:'五四运动后期，斗争主力由学生转向 ______，运动的中心由北京转到上海。',answer:'工人',exp:'6 月 5 日起上海工人罢工，工人阶级以独立姿态登上政治舞台，成为运动主力。'}},
    {ch:'c4',title:'五四运动的历史特点',speak:'五四运动是在新的社会历史条件下发生的，具有旧民主主义革命不具备的历史特点。就特点看，它是一场以先进青年知识分子为先锋、广大人民群众参加的彻底反帝反封建的伟大爱国革命运动，是一场中国人民为拯救民族危亡、捍卫民族尊严、凝聚民族力量而掀起的伟大社会革命运动，是一场传播新思想新文化新知识的伟大思想启蒙运动和新文化运动，以磅礴之力鼓动了中国人民和中华民族实现民族复兴的志向和信心。',
      quiz:{type:'choice',q:'就特点看，五四运动是一场以先进青年知识分子为先锋、广大人民群众参加的彻底的什么性质的运动？',opts:['反帝反封建的伟大爱国革命运动','君主立宪运动','实业救国运动','改良主义运动'],a:0,exp:'五四运动是彻底反帝反封建的伟大爱国革命运动。'}},
    {ch:'c4',title:'五四运动的伟大意义',speak:'就意义看：第一，五四运动是中国旧民主主义革命走向新民主主义革命的转折点，在近代中华民族追求独立和发展进步的历史进程中具有里程碑意义；它以彻底反帝反封建的革命性、追求救国强国真理的进步性、各族各界群众广泛参与的广泛性，促进了马克思主义在中国的传播及其同中国工人运动的结合，为中共成立做了思想上干部上的准备，成为新民主主义革命的开端。第二，它以全民族力量高举爱国主义旗帜，孕育了以爱国、进步、民主、科学为主要内容的伟大五四精神，核心是爱国主义。第三，它以全民族行动激发了追求真理、追求进步的伟大觉醒，实现了中国人民和中华民族自鸦片战争以来的第一次全面觉醒。第四，它以全民族的搏击培育了永久奋斗的伟大传统。',
      quiz:{type:'fill',q:'五四运动是中国旧民主主义革命走向 ______ 革命的转折点，成为中国新民主主义革命的开端。',answer:'新民主主义',exp:'五四运动是旧民主主义革命走向新民主主义革命的转折点，为中共成立做了准备。'}},

    /* ---- 第四章第二节（新增，基于教材PDF：马克思主义广泛传播与中国共产党诞生） ---- */
    {ch:'c4',title:'中国早期马克思主义者的三种类型',speak:'五四运动后中国先进分子逐步走上马克思主义道路，主要有三种类型：一是新文化运动的精神领袖李大钊、陈独秀（李大钊起主要作用，1919年将《新青年》编为“马克思主义研究”专号）；二是五四运动的左翼骨干如毛泽东等（是主体部分）；三是原同盟会会员、辛亥革命活动家如董必武等。',
      quiz:{type:'choice',q:'在中国早期的马克思主义思想运动中起着主要作用的人物是？',opts:['李大钊','胡适','梁启超','张东荪'],a:0,exp:'李大钊是中国早期马克思主义思想运动的主要先驱者和擎旗人。'}},
    {ch:'c4',title:'早期马克思主义思想运动的特点（一）：重视理论、划清与第二国际界限',speak:'第一特点是重视对马克思主义基本理论的学习，明确同第二国际的社会民主主义、修正主义划清界限。毛泽东指出“社会民主主义借议会为改造工具，但事实上议会的立法总是保护有产阶级的”，说明一开始就坚持了马克思主义的革命原则和正确方向。',
      quiz:{type:'choice',q:'中国早期马克思主义思想运动一开始就明确同哪种思潮划清了界限？',opts:['第二国际的社会民主主义与修正主义','无政府主义','实用主义','空想社会主义'],a:0,exp:'中国早期马克思主义者对社会民主主义、修正主义采取明确批判态度。'}},
    {ch:'c4',title:'早期马克思主义思想运动的特点（二）：从中国实际出发运用马克思主义',speak:'第二特点是注意从中国的实际出发学习、运用马克思主义。李大钊在1919年《再论问题与主义》中针对胡适“多研究些问题，少谈些主义”的主张，强调社会问题“必须有一个根本解决”，并主张马克思主义必须同中国实境结合，初步形成了马克思主义应当与中国具体实际相结合的思想。',
      quiz:{type:'fill',q:'李大钊在《再论问题与主义》中针对胡适“多研究些问题，少谈些主义”，强调社会问题“必须有一个 ______ 解决”。',answer:'根本',exp:'李大钊主张根本解决，初步形成了马克思主义与中国实际相结合的思想。'}},
    {ch:'c4',title:'早期马克思主义思想运动的特点（三）：知识分子同劳动群众相结合',speak:'第三特点是开始提出知识分子应当同劳动群众相结合的思想。李大钊主张知识分子“向农村去”“到民间去”，指引北大邓中夏等到工人中去活动，预示着先进知识分子应当遵循的新方向和新道路。',
      quiz:{type:'fill',q:'李大钊指出“我们很盼望知识阶级作民众的先驱，民众作知识阶级的 ______”，主张知识分子到民间去。',answer:'后盾',exp:'李大钊主张知识分子作民众先驱、民众作知识阶级后盾，到民间去。'}},
    {ch:'c4',title:'新文化运动在五四后的新发展',speak:'五四以后的新文化运动发展到新阶段，马克思主义逐步在思想文化领域发挥指导作用：民主不再指狭隘的资产阶级民主，而是指多数人以劳动群众为主体的民主；科学除自然科学外主要指马克思主义的科学世界观和社会革命论；马克思主义的传播有力推动了反封建的启蒙运动。',
      quiz:{type:'choice',q:'五四以后新文化运动中“民主”被赋予的新含义是指？',opts:['多数人的民主、以劳动群众为主体的民主','资产阶级议会民主','君主专制','精英贵族民主'],a:0,exp:'五四后民主指多数人的民主、以劳动群众为主体的民主。'}},
    {ch:'c4',title:'共产党早期组织的酝酿（陈独秀、李大钊）',speak:'最早酝酿在中国建立共产党的是陈独秀和李大钊。1920年2月两人商讨建党；3月李大钊在北京大学组织马克思学说研究会；4月俄共（布）派维经斯基来华促进；8月上海共产党早期组织成立，陈独秀任书记，实际是发起组织和联络中心；11月拟定《中国共产党宣言》。',
      quiz:{type:'fill',q:'1920年8月，在 ______ 成立的共产党早期组织是各地共产主义者进行建党活动的发起组织和联络中心。',answer:'上海',exp:'上海共产党早期组织于1920年8月成立，陈独秀任书记，是发起组织。'}},
    {ch:'c4',title:'各地共产党早期组织的建立',speak:'1920年10月李大钊等在北京成立共产党早期组织；秋至1921年春，董必武等在武汉、毛泽东在长沙、王尽美等在济南、谭平山等在广州，以及旅日、旅法都成立了共产党早期组织，全国早期组织约58人，促进了马克思主义传播及其与工人运动的结合。',
      quiz:{type:'choice',q:'1920年10月，在 ______ 成立共产党早期组织，李大钊任书记。',opts:['北京','上海','长沙','广州'],a:0,exp:'1920年10月李大钊等在北京成立共产党早期组织。'}},
    {ch:'c4',title:'共产党早期组织的活动（一）：研究宣传马克思主义与反马克思主义论战',speak:'早期组织着重研究和宣传马克思主义：陈望道1920年8月翻译《共产党宣言》中文全译本公开出版（真理的味道非常甜）。同时同反马克思主义思潮斗争：1920年底张东荪、梁启超挑起社会主义论战，主张依靠“绅商阶级”振兴实业；还同黄凌霜、区声白等无政府主义者论战，反对绝对自由、主张无产阶级专政。',
      quiz:{type:'choice',q:'1920年8月由陈望道翻译公开出版的中文全译本马克思主义经典是？',opts:['《共产党宣言》','《阶级斗争》','《社会主义史》','《国家与革命》'],a:0,exp:'陈望道翻译的《共产党宣言》中文全译本于1920年8月出版。'}},
    {ch:'c4',title:'共产党早期组织的活动（二）：到工人中去',speak:'早期组织成员穿起工人服装、学习工人语言，力求与工人打成一片。各地创办工人刊物（上海《劳动界》、北京《劳动音》），开办劳动补习学校（邓中夏长辛店、李启汉沪西小沙渡）；1920年11月领导成立第一个工会——上海机器工会；1921年五一长辛店成立工人俱乐部，工会开始发动罢工斗争。',
      quiz:{type:'fill',q:'1920年11月，共产党早期组织领导的第一个工会—— ______ 宣告成立。',answer:'上海机器工会',exp:'1920年11月成立的上海机器工会是早期组织领导的第一个工会。'}},
    {ch:'c4',title:'共产党早期组织的活动（三）：建党讨论与青年团成立',speak:'留法勤工俭学的蔡和森在给毛泽东的信中主张“先要组织党——共产党”，强调“无产阶级专政”与严密组织纪律，意见得到毛泽东赞同。1920年8月上海社会主义青年团成立，随后北京、广州、长沙、武昌等地也建团，为党造就了一批后备力量。',
      quiz:{type:'choice',q:'最早明确提出“先要组织党——共产党”并强调“无产阶级专政”的是？',opts:['蔡和森','陈独秀','李大钊','毛泽东'],a:0,exp:'蔡和森在留法期间致信毛泽东，主张先组织共产党。'}},
    {ch:'c4',title:'中国共产党第一次全国代表大会的召开（1921）',speak:'中共一大1921年7月23日在上海法租界开幕，因暗探注意和法租界巡捕搜查，最后一天转移到嘉兴南湖游船上举行（红船）。出席代表13人代表全国50多名党员，共产国际代表马林、尼克尔斯基出席，陈独秀、李大钊未出席。大会确定党的名称为“中国共产党”，通过第一个纲领，选举陈独秀为中央局书记，宣告中共正式成立。',
      quiz:{type:'fill',q:'中共一大最后一天的会议转移到浙江嘉兴 ______ 的游船上举行，这条船后来被称为“红船”。',answer:'南湖',exp:'中共一大最后一天在嘉兴南湖游船（红船）上举行。'}},
    {ch:'c4',title:'中国共产党成立的历史特点与历史意义',speak:'中共是在特定历史条件下成立的：一方面在俄国十月革命胜利、第二国际破产之后，接受完整科学世界观的马克思主义；另一方面在半殖民地半封建中国的工人运动基础上产生，工人阶级身受三重压迫、具有坚强革命性。中共成立是开天辟地的大事变，形成坚持真理、坚守理想、践行初心、担当使命、不怕牺牲、英勇斗争、对党忠诚、不负人民的伟大建党精神，深刻改变了中华民族发展方向、中国人民前途命运、世界发展趋势格局。',
      quiz:{type:'choice',q:'下列关于中国共产党成立历史意义的表述，正确的是？',opts:['是开天辟地的大事变','是中国近代第一个资产阶级政党','标志新民主主义革命胜利','标志社会主义初级阶段开始'],a:0,exp:'中共成立是开天辟地的大事变，是中国历史上深刻的大转折。'}},

    /* ---- 第四章第三节（新增，基于教材PDF：中国革命的新局面） ---- */
    {ch:'c4',title:'中共二大与民主革命纲领的制定',speak:'1922年7月中共二大在上海举行，分析中国社会经济政治状况，揭示半殖民地半封建性质。党的最高纲领是实现社会主义、共产主义；最低纲领（现阶段纲领）是：打倒军阀、推翻国际帝国主义的压迫、统一中国为真正民主共和国。这是党第一次提出反帝反封建的民主革命纲领，并提出联合全国革命党派组成“民主主义的联合战线”。',
      quiz:{type:'fill',q:'1922年7月中共二大第一次提出了 ______ 的民主革命纲领。',answer:'反帝反封建',exp:'中共二大第一次提出反帝反封建的民主革命纲领。'}},
    {ch:'c4',title:'工农运动的发动：第一个农民协会与农民运动',speak:'在领导工人运动的同时，党也开始发动农民。1921年9月浙江萧山衙前村成立中国第一个农民协会；1922年6月彭湃到广东海丰县赤山约成立农会，次年元旦海丰总农会成立，新式农民运动蓬勃开展。',
      quiz:{type:'fill',q:'1921年9月，浙江萧山县 ______ 村成立了中国第一个农民协会。',answer:'衙前',exp:'衙前村农民协会是中国第一个农民协会。'}},
    {ch:'c4',title:'工人运动的第一个高潮',speak:'从1922年1月香港海员罢工到1923年2月京汉铁路工人罢工，党掀起中国工人运动第一个高潮。13个月中全国发生大小罢工100余次、参加者30万人以上，包括安源路矿工人罢工、开滦五矿工人罢工等。',
      quiz:{type:'choice',q:'中国工人运动第一个高潮的起点是？',opts:['1922年1月香港海员罢工','1923年2月京汉铁路罢工','1925年五卅运动','1926年北伐战争'],a:0,exp:'第一个工人运动高潮以1922年1月香港海员罢工为起点。'}},
    {ch:'c4',title:'二七惨案与工人运动转入低潮',speak:'1923年2月7日京汉铁路罢工遭反动军阀血腥镇压，造成二七惨案，工人运动暂时转入低潮。党由此认识到中国革命力量远不如帝国主义和封建势力强大，决定采取更积极步骤联合孙中山领导的国民党。',
      quiz:{type:'fill',q:'1923年2月7日，京汉铁路罢工遭血腥镇压，造成 ______ 惨案，工人运动暂时转入低潮。',answer:'二七',exp:'二七惨案后工人运动转入低潮，党转向联合国民党。'}},
    {ch:'c4',title:'中共三大与国共合作方针的确定',speak:'1923年6月中共三大在广州举行，正确估计孙中山的革命立场和国民党改革可能性，决定共产党员以个人身份加入国民党，以实现国共合作，同时规定党在政治上、思想上、组织上保持自己的独立性。',
      quiz:{type:'choice',q:'1923年6月中共三大决定共产党员以何种方式加入国民党以实现国共合作？',opts:['以个人身份加入（党内合作）','以整个组织加入','建立联合政府','保持互不往来'],a:0,exp:'中共三大决定共产党员以个人身份加入国民党，保持党的独立性。'}},
    {ch:'c4',title:'国民党一大与第一次国共合作正式形成',speak:'1924年1月中国国民党一大由孙中山主持在广州举行，宣言对三民主义作出新解释（新三民主义）：民族主义突出反帝、民权主义强调“为一般平民所共有”、民生主义概括为“平均地权”和“节制资本”（后提“耕者有其田”）。新三民主义与中共民主革命纲领基本一致，成为国共合作政治基础；大会确认联俄、联共、扶助农工三大政策，标志第一次国共合作正式形成。',
      quiz:{type:'fill',q:'1924年1月国民党一大事实上确认了 ______ 、联共、扶助农工的三大政策，标志第一次国共合作正式形成。',answer:'联俄',exp:'国民党一大确认联俄、联共、扶助农工三大政策。'}},
    {ch:'c4',title:'大革命高潮的到来：工农运动复兴与黄埔军校',speak:'国共合作实现后，以广州为中心开创革命新局面。1924年工人运动开始复兴；7月起在广州开办六届农民运动讲习所，先后由彭湃、毛泽东等主持；为造就革命武装骨干，1924年5月开办黄埔军校，第一期学生中共产党员和青年团员56人约占1/10。',
      quiz:{type:'choice',q:'1924年5月开办的哪所军校为国民革命培养了革命武装骨干力量？',opts:['黄埔军校','保定军校','云南讲武堂','抗日军政大学'],a:0,exp:'黄埔军校于1924年5月开学，培养革命武装骨干。'}},
    {ch:'c4',title:'中共四大与大革命的发展',speak:'1925年1月中共四大在上海举行，重大历史功绩是提出无产阶级在民主革命中的领导权问题和工农联盟问题，对民主革命内容作更完整规定。1925年5月第二次全国劳动大会成立中华全国总工会；在共产党人建议下，1926年初建立由叶挺指挥的国民革命军第四军独立团。',
      quiz:{type:'choice',q:'1925年1月中共四大最重大的历史功绩是提出了？',opts:['无产阶级领导权与工农联盟问题','武装夺取政权','农村包围城市','持久战理论'],a:0,exp:'中共四大提出了无产阶级领导权和工农联盟问题。'}},
    {ch:'c4',title:'五卅运动、省港大罢工与广东革命根据地统一',speak:'1925年5月英日等国军警在上海制造五卅惨案，引发五卅运动，掀起全国大革命高潮；同年6月开始的省港大罢工前后坚持16个月，是中国工人运动史上持续时间最长的政治大罢工。国共合作进行广东战争，统一巩固广东革命根据地；1925年7月1日国民政府在广州建立，将部队改编为国民革命军6个军。',
      quiz:{type:'fill',q:'1925年6月开始的 ______ 大罢工前后坚持16个月，是工人运动史上持续时间最长的政治大罢工。',answer:'省港',exp:'省港大罢工坚持16个月，是持续时间最长的政治大罢工。'}},
    {ch:'c4',title:'北伐战争与大革命胜利进军',speak:'1926年7月以推翻北洋军阀统治为目标的北伐战争开始。国民革命军在工农群众支援下采取各个击破战略，至11月基本摧毁吴佩孚、孙传芳主力，革命势力发展到长江流域和黄河流域大部分地区。由共产党直接领导的第四军独立团战功卓著，使第四军赢得“铁军”称号；收回汉口、九江英租界，上海工人举行三次武装起义。',
      quiz:{type:'choice',q:'北伐战争中，由共产党员叶挺指挥的哪支部队被誉为“铁军”？',opts:['第四军独立团','第一军','黄埔学生军','第八路军'],a:0,exp:'叶挺独立团（第四军独立团）战功卓著，第四军被誉为铁军。'}},
    {ch:'c4',title:'大革命中中国共产党的独特作用',speak:'大革命在国共合作条件下进行，中国共产党起着独特不可替代的作用：是反帝反军阀政治口号的提出者；是国共合作的倡导者和统一战线的组织者；是人民群众的主要发动者和组织者；共产党人帮助推动国民革命军建立并在军队中做政治工作，身先士卒，建立工农武装配合作战。',
      quiz:{type:'choice',q:'在大革命中，提出“反对帝国主义、反对军阀”政治口号的是？',opts:['中国共产党','中国国民党','中华革命党','无政府主义者'],a:0,exp:'反帝反军阀的政治口号正是由中国共产党提出的。'}},
    {ch:'c4',title:'大革命的失败：中山舰事件与四一二、七一五政变',speak:'孙中山1925年3月12日病逝后，国民党右派重新活跃。1926年3月蒋介石制造中山舰事件，5月提出《整理党务决议案》公开反共；1927年4月12日蒋介石在上海发动四一二反共政变，7月15日汪精卫在武汉“分共”，国共合作全面破裂，大革命最终失败。其间1927年4月中共五大在武汉举行，未能提出有效挽救措施。',
      quiz:{type:'fill',q:'1927年4月12日，蒋介石在上海发动 ______ 反共政变，大革命遭受严重挫折。',answer:'四一二',exp:'四一二政变标志大革命开始急剧逆转。'}},
    {ch:'c4',title:'大革命失败的教训与历史意义',speak:'大革命失败，客观上是反革命力量强大、资产阶级严重动摇、蒋汪集团先后叛变；主观上是中共尚处幼年、缺乏政治经验，陈独秀右倾机会主义错误在领导机关占统治地位，且难摆脱共产国际错误指导。教训表明：党必须坚持统一战线中的独立性、实行又团结又斗争，必须掌握武装、进行土地革命、加强党的建设。大革命虽败，却提高了人民觉悟、使党开始掌握部分革命武装，为土地革命战争阶段准备了条件。',
      quiz:{type:'choice',q:'大革命失败最主要的主观原因是？',opts:['党内以陈独秀为代表的右倾机会主义错误占统治地位','帝国主义武力威胁','国民党右派叛变','工人运动不够激进'],a:0,exp:'主观上是以陈独秀为代表的右倾机会主义错误在中共中央占统治地位。'}},

    /* 大纲补缺：中国劳动组合书记部 */
    {ch:'c4',title:'中国劳动组合书记部',speak:'1921年8月，中国共产党在上海成立中国劳动组合书记部，作为公开领导工人运动的专门机构，出版《劳动周刊》，并在各地设立分部。它推动各地工会建立，为第一次工人运动高潮作了组织准备。1925年5月第二次全国劳动大会后成立中华全国总工会，书记部随之撤销。',
      quiz:{type:'fill',q:'1921年8月，党在上海成立领导工人运动的专门机构 ______ 。',answer:'中国劳动组合书记部',exp:'中国劳动组合书记部是党领导工人运动的第一个专门机构，1925年后由中华全国总工会接替。'}},

    /* ============ 第五章 ============ */
    {ch:'c5',title:'土地革命战争与革命新道路的开辟',speak:'大革命失败后，党发动南昌起义等武装起义，开辟农村包围城市、武装夺取政权的革命新道路，建立农村革命根据地。',
      quiz:{type:'choice',q:'中国革命新道路的核心是？',opts:['城市中心暴动','农村包围城市、武装夺取政权','议会斗争','依附军阀'],a:1,exp:'毛泽东开辟的农村包围城市、武装夺取政权道路，是中国革命的正确道路。'}},
    {ch:'c5',title:'遵义会议与红军长征',speak:'1935年遵义会议确立毛泽东在党中央和红军的领导地位，是党历史上生死攸关的转折点。红军长征胜利保存了革命力量，打开新局面。',
      quiz:{type:'fill',q:'______ 年遵义会议是党历史上生死攸关的转折点。',answer:'1935',exp:'1935 年遵义会议确立了毛泽东的领导地位，挽救了党和红军。'}},

    /* ---- 第五章第一节（新增，基于教材PDF：中国共产党对革命新道路的探索） ---- */
    {ch:'c5',title:'国民党全国统治的建立（宁汉合流与东北易帜）',speak:'1927年七一五政变后宁汉合流，1928年2月南京国民政府改组。同年12月29日张学良宣布东北易帜、服从国民政府，北洋军阀不再作为独立政治力量存在，国民党在全国范围内建立统治。',
      quiz:{type:'choice',q:'标志北洋军阀不再作为独立政治力量、国民党在全国范围建立统治的事件是？',opts:['东北易帜','宁汉合流','皇姑屯事件','中原大战'],a:0,exp:'1928年12月29日张学良东北易帜，北洋军阀退出历史舞台，国民党全国统治建立。'}},
    {ch:'c5',title:'国民党的一党专政与军事独裁统治',speak:'国民党实行代表地主阶级、买办性大资产阶级利益的一党专政和军事独裁。1928年10月通过《训政纲领》废除议会制，建立庞大军队与中统、军统特务系统，推行保甲制度，厉行文化专制主义查禁进步书刊。',
      quiz:{type:'choice',q:'国民党用来镇压人民、反共的庞大特务系统主要是哪两个？',opts:['中统和军统','军统和汪伪','中统和青帮','复兴社和军统'],a:0,exp:'国民党建立中统、军统两大特务系统，专门反共、破坏革命运动。'}},
    {ch:'c5',title:'大革命失败后的白色恐怖与艰难环境',speak:'国民党统治下中国半殖民地半封建性质未变，全国陷入白色恐怖。据中共六大统计，1927年3月至1928年上半年被杀害的共产党员和革命群众达31万多人，其中党员2.6万人，全党党员由5.7万余人锐减到1万余人。',
      quiz:{type:'fill',q:'据中共六大时统计，1927年3月至1928年上半年被杀害的共产党员和革命群众达 ______ 万多人。',answer:'31',exp:'白色恐怖下被杀害的共产党员和革命群众达31万多人，革命力量遭受严重损失。'}},
    {ch:'c5',title:'八七会议：武装反抗与土地革命方针',speak:'1927年8月7日中共中央在汉口召开紧急会议（八七会议），确定土地革命和武装起义方针。毛泽东强调「以后要非常注意军事，须知政权是由枪杆子中取得的」，这是由大革命失败到土地革命战争兴起的历史性转变。',
      quiz:{type:'fill',q:'1927年八七会议上，毛泽东提出「政权是由 ______ 中取得的」著名论断。',answer:'枪杆子',exp:'八七会议确定武装反抗国民党反动派和土地革命方针，毛泽东提出「枪杆子里面出政权」。'}},
    {ch:'c5',title:'南昌起义：武装反抗第一枪',speak:'1927年8月1日周恩来、贺龙、叶挺、朱德、刘伯承等率领2万余人在南昌打响武装反抗国民党反动派第一枪，是党独立领导革命战争、创建人民军队和武装夺取政权的开端。',
      quiz:{type:'choice',q:'打响武装反抗国民党反动派第一枪的是哪次起义？',opts:['南昌起义','秋收起义','广州起义','百色起义'],a:0,exp:'1927年8月1日南昌起义，是党独立领导武装斗争、创建人民军队的开端。'}},
    {ch:'c5',title:'秋收起义、三湾改编与进军井冈山',speak:'1927年9月9日毛泽东领导湘赣边界秋收起义，攻打长沙受挫后转向农村。9月29日三湾改编从组织上确立党对军队的领导，是建设新型人民军队的重要开端。10月抵达井冈山，开始创建农村革命根据地。',
      quiz:{type:'choice',q:'从组织上确立党对军队的领导、建设新型人民军队重要开端的是？',opts:['三湾改编','古田会议','南昌起义','遵义会议'],a:0,exp:'三湾改编确立「党指挥枪」，是建设无产阶级领导的新型人民军队的重要开端。'}},
    {ch:'c5',title:'广州起义与各地武装起义',speak:'1927年12月11日张太雷、叶挺、叶剑英领导广州起义。从大革命失败到1928年初，党在各地先后领导近百次武装起义，保留下来的部队逐步转移到农村开展游击战争，中国革命进入土地革命战争时期。',
      quiz:{type:'fill',q:'1927年12月11日，张太雷、叶挺、叶剑英等在 ______ 领导起义，对国民党屠杀政策又一次英勇反击。',answer:'广州',exp:'广州起义是继南昌、秋收之后党领导的又一次武装起义。'}},
    {ch:'c5',title:'井冈山革命根据地的斗争与朱毛会师',speak:'1927年11月成立茶陵县工农兵政府，1928年2月井冈山根据地初步建立。4月朱德、陈毅率南昌起义保留部队与毛泽东部在井冈山会师，成立工农革命军第四军（朱毛红军），点燃工农武装割据的星星之火。',
      quiz:{type:'choice',q:'1928年4月朱德、毛泽东会师后成立的部队被称为？',opts:['朱毛红军（工农革命军第四军）','红一方面军','红二方面军','八路军'],a:0,exp:'朱德、毛泽东井冈山会师后成立工农革命军第四军，后称朱毛红军。'}},
    {ch:'c5',title:'毛泽东开辟革命新道路的理论贡献',speak:'毛泽东在《中国的红色政权为什么能够存在？》《井冈山的斗争》中论证红色政权长期存在的条件，提出工农武装割据思想；《星星之火，可以燎原》指明农村根据地是促进全国革命高潮最重要因素；《反对本本主义》提出「没有调查，没有发言权」。',
      quiz:{type:'choice',q:'毛泽东在哪篇文章中提出「没有调查，没有发言权」？',opts:['《反对本本主义》','《星星之火，可以燎原》','《井冈山的斗争》','《论持久战》'],a:0,exp:'1930年5月《反对本本主义》提出「没有调查，没有发言权」，体现实事求是精神。'}},
    {ch:'c5',title:'古田会议：思想建党、政治建军',speak:'1929年12月红四军第九次党代会（古田会议）通过毛泽东起草的决议，确立思想建党、政治建军原则，规定红军必须绝对服从党的领导。古田会议决议是党和红军建设的纲领性文献，是人民军队建设史上的重要里程碑。',
      quiz:{type:'choice',q:'确立思想建党、政治建军原则的会议是？',opts:['古田会议','遵义会议','八七会议','瓦窑堡会议'],a:0,exp:'古田会议确立思想建党、政治建军原则，解决了在农村环境中建党建军的根本问题。'}},
    {ch:'c5',title:'红军反「围剿」战争的胜利',speak:'从1930年10月到1931年7月，红一方面军在毛泽东、朱德指挥下贯彻积极防御方针，连续粉碎国民党三次「围剿」；1933年3月取得第四次反「围剿」胜利。红军游击战争成为革命的主要形式，农村根据地成为主要战略阵地。',
      quiz:{type:'choice',q:'1930年10月至1931年7月，红一方面军连续粉碎了国民党几次「围剿」？',opts:['三次','两次','四次','五次'],a:0,exp:'1930年10月至1931年7月，红一方面军连续粉碎国民党三次「围剿」。'}},
    {ch:'c5',title:'土地革命的开展与土地革命路线',speak:'1931年2月毛泽东总结土地革命经验，规定农民分得田地归个人私有。制定土地革命路线：依靠贫雇农、联合中农、限制富农、保护中小工商业者、消灭地主阶级；以乡为单位按人口平分，在原耕地基础上实行抽多补少、抽肥补瘦。',
      quiz:{type:'fill',q:'土地革命中分配土地的方法是「在原耕地基础上，实行抽多补少、______」。',answer:'抽肥补瘦',exp:'土地革命路线与分配方法调动了农民积极性，为革命坚持发展提供了根本保障。'}},

    /* ---- 第五章第二节（新增，基于教材PDF：中国革命在曲折中前进） ---- */
    {ch:'c5',title:'农村革命根据地的发展与中央革命根据地',speak:'红一方面军三次反「围剿」胜利使赣南、闽西连成一片，形成中央革命根据地，拥有21座县城、250万人口、5万平方公里土地。鄂豫皖、湘鄂西等根据地也得到发展。',
      quiz:{type:'fill',q:'三次反「围剿」胜利后形成的中央革命根据地，拥有约 ______ 万人口。',answer:'250',exp:'中央革命根据地是土地革命时期最大的一块根据地，人口约250万。'}},
    {ch:'c5',title:'中华苏维埃共和国临时中央政府成立',speak:'1931年11月中华苏维埃第一次全国代表大会在江西瑞金召开，通过《宪法大纲》等，成立中华苏维埃共和国临时中央政府，毛泽东当选主席。这是中国历史上第一个全国性的工农民主政权，是党局部执政的重要尝试。',
      quiz:{type:'choice',q:'中国历史上第一个全国性的工农民主政权是？',opts:['中华苏维埃共和国','中华人民共和国','陕甘宁边区政府','广州国民政府'],a:0,exp:'1931年11月成立的中华苏维埃共和国是党局部执政的重要尝试。'}},
    {ch:'c5',title:'土地革命战争的严重挫折：王明「左」倾教条主义',speak:'从1927年7月到1935年1月遵义会议前，「左」倾错误三次在党中央取得统治，尤以王明为代表的「左」倾教条主义为甚。1931年1月六届四中全会后王明上台，博古负总责的临时中央错误领导达4年。',
      quiz:{type:'choice',q:'使中国革命遭受严重挫折、错误领导达四年的「左」倾错误以谁为代表？',opts:['王明','陈独秀','瞿秋白','李立三'],a:0,exp:'王明「左」倾教条主义错误使革命根据地和红军遭受极其严重的损失。'}},
    {ch:'c5',title:'毛泽东正确主张遭错误批判',speak:'王明等人破坏民主集中制，对持不同意见者残酷斗争。1931年11月赣南会议指责毛泽东主张为「狭隘经验论」「富农路线」；1932年10月宁都会议剥夺其红军领导权；后又开展反罗明路线和邓毛谢古斗争。',
      quiz:{type:'choice',q:'1932年10月哪次会议剥夺了毛泽东在中央根据地红军的领导权？',opts:['宁都会议','赣南会议','遵义会议','八七会议'],a:0,exp:'宁都会议后毛泽东被调离红军领导岗位，回后方主持临时中央政府工作。'}},
    {ch:'c5',title:'第五次反「围剿」失败与战略转移',speak:'王明「左」倾教条主义使红军和根据地损失90%，国民党统治区党的力量几乎损失100%，最大恶果是第五次反「围剿」失败，红军不得不退出南方根据地实行战略转移——长征。',
      quiz:{type:'choice',q:'王明「左」倾教条主义错误的最大恶果是？',opts:['第五次反「围剿」失败、被迫长征','南昌起义失败','秋收起义受挫','古田会议推迟'],a:0,exp:'第五次反「围剿」失败迫使红军退出南方根据地，开始长征。'}},
    {ch:'c5',title:'红军开始长征与湘江战役',speak:'1934年10月中央红军主力8.6万余人开始长征。长征初期犯退却中的逃跑主义错误，强渡湘江后从8.6万人锐减到3万多人。随后黎平会议放弃到湘西北计划，改向贵州北部进军。',
      quiz:{type:'fill',q:'中央红军长征出发时约 ______ 万人，强渡湘江后锐减到3万多人。',answer:'8.6',exp:'长征初期盲目突围、湘江鏖战使中央红军由8.6万人锐减至3万余人。'}},
    {ch:'c5',title:'遵义会议：伟大历史转折',speak:'1935年1月15日至17日遵义会议召开，集中解决军事和组织问题，增选毛泽东为政治局常委，后成立由毛泽东、周恩来、王稼祥组成的三人军事小组。会议事实上确立毛泽东在党中央和红军的领导地位，是生死攸关的转折点。',
      quiz:{type:'choice',q:'遵义会议事实上确立了谁在党中央和红军的领导地位？',opts:['毛泽东','王明','博古','张国焘'],a:0,exp:'遵义会议开始确立以毛泽东为主要代表的马克思主义正确路线在党中央的领导地位。'}},
    {ch:'c5',title:'红军长征的胜利进程',speak:'遵义会议后红军四渡赤水、巧渡金沙江、强渡大渡河、飞夺泸定桥、翻越夹金山。1935年10月中央红军到达陕北吴起镇；1936年10月红一、二、四方面军在甘肃会宁、将台堡会师，三大主力长征胜利结束，行程二万五千里。',
      quiz:{type:'choice',q:'三大主力红军长征胜利结束的标志是？',opts:['1936年10月会宁、将台堡会师','1935年10月吴起镇会师','飞夺泸定桥','遵义会议'],a:0,exp:'1936年10月红一、二、四方面军在甘肃会师，三大主力长征胜利结束。'}},
    {ch:'c5',title:'长征的伟大意义',speak:'长征是历史记录上的第一次，毛泽东称「长征是宣言书，长征是宣传队，长征是播种机」。长征的胜利是中国革命转危为安的关键，宣告国民党消灭红军图谋失败，实现了从挫折走向胜利的伟大转折。',
      quiz:{type:'choice',q:'毛泽东形容「长征是宣言书，长征是宣传队，长征是播种机」，这表明长征是？',opts:['历史记录上的第一次','一次普通转移','一次游行','一次演习'],a:0,exp:'长征是历史记录上的第一次，是中国革命转危为安的关键。'}},
    {ch:'c5',title:'长征精神',speak:'长征铸就伟大长征精神：把人民和民族根本利益高于一切，坚定革命理想；不怕艰难险阻、不惜牺牲；独立自主、实事求是；顾全大局、严守纪律、紧密团结；紧紧依靠人民群众。长征精神为革命胜利提供强大精神动力。',
      quiz:{type:'fill',q:'长征精神的核心是坚定革命的理想和信念，坚信 ______ 必然胜利。',answer:'正义事业',exp:'长征精神包括坚定的理想信念、不怕牺牲、独立自主、紧密团结、依靠群众等。'}},
    {ch:'c5',title:'总结历史经验与《论反对日本帝国主义的策略》',speak:'长征到达陕北后，1935年12月毛泽东作《论反对日本帝国主义的策略》报告，阐明党的抗日民族统一战线新政策，系统说明政治策略问题，为迎接全民族抗战作准备。',
      quiz:{type:'choice',q:'1935年12月毛泽东哪篇报告阐明抗日民族统一战线新政策？',opts:['《论反对日本帝国主义的策略》','《星星之火，可以燎原》','《论持久战》','《新民主主义论》'],a:0,exp:'《论反对日本帝国主义的策略》系统阐明抗日民族统一战线的新政策。'}},
    {ch:'c5',title:'毛泽东哲学著作与马克思主义思想路线',speak:'1936年12月毛泽东写《中国革命战争的战略问题》，1937年夏在抗大讲授《实践论》《矛盾论》，从马克思主义认识论高度总结历史经验，批判主观主义尤其是教条主义，科学阐明党的马克思主义思想路线。',
      quiz:{type:'choice',q:'1937年夏毛泽东在抗日军政大学讲授的哲学著作是？',opts:['《实践论》《矛盾论》','《论持久战》','《新民主主义论》','《整顿党的作风》'],a:0,exp:'《实践论》《矛盾论》从认识论高度批判教条主义，阐明党的马克思主义思想路线。'}},

    /* 大纲补缺：官僚资本、中间党派、民族资本主义经济特点、第三党、井冈山与兴国土地法、左翼文化运动 */
    {ch:'c5',title:'四大家族与官僚资本的膨胀',speak:'1927年国民党建立统治后，蒋介石、宋子文、孔祥熙、陈果夫陈立夫四大家族凭借国家政权，通过发行公债、垄断金融（控制中央银行、中国银行、交通银行、中国农民银行）、独占工商业和对外贸易，迅速聚敛巨额财富，形成官僚资本。抗战时期官僚资本急剧膨胀，抗战胜利后又通过接收敌伪产业达到高峰，成为压迫民族工商业和全国人民的重要力量。',
      quiz:{type:'choice',q:'近代中国官僚资本主要是依靠什么形成的？',opts:['凭借国家政权垄断金融和工商业','自由市场竞争','外国直接投资','民间集资入股'],a:0,exp:'官僚资本是四大家族凭借政权力量巧取豪夺形成的，属于国家垄断资本主义性质。'}},
    {ch:'c5',title:'中国民族资本主义经济的特点',speak:'中国民族资本主义经济的特点是：在帝国主义和封建主义的夹缝中产生和发展，资金少、规模小、技术落后；主要集中于轻工业，重工业基础薄弱，部门结构和地区分布极不平衡；对外国资本主义和本国封建势力有相当依赖性，又与它们存在矛盾。这些特点决定了民族资产阶级既有革命性又有妥协性的两面性。',
      quiz:{type:'choice',q:'中国民族资本主义经济最突出的特点是？',opts:['在夹缝中发展，资金少、规模小、技术落后','重工业发达、体系完整','完全独立于外国资本','与封建势力毫无联系'],a:0,exp:'民族资本先天不足、后天畸形，这决定了民族资产阶级的两面性。'}},
    {ch:'c5',title:'中间党派及其社会基础',speak:'1927年大革命失败后，一些既不满国民党独裁统治、又不赞成共产党土地革命主张的人士组成中间党派，主要有中国国民党临时行动委员会（第三党）、中国致公党、中国民主同盟的前身等。其社会基础主要是民族资产阶级、城市小资产阶级及其知识分子。他们主张抗日民主、反对独裁，但一度幻想走“中间路线”。',
      quiz:{type:'choice',q:'中间党派的社会基础主要是？',opts:['民族资产阶级、城市小资产阶级及其知识分子','大地主大资产阶级','产业工人和贫雇农','外国在华势力'],a:0,exp:'中间党派代表民族资产阶级和上层小资产阶级利益，故又称中间势力。'}},
    {ch:'c5',title:'中国国民党临时行动委员会（第三党）',speak:'1927年11月，邓演达等在莫斯科发表《对中国及世界革命民众宣言》；1930年8月在上海正式成立中国国民党临时行动委员会，通称“第三党”，主张推翻国民党独裁统治、建立平民政权、实行耕者有其田。1931年邓演达被蒋介石杀害。1935年该党改名为中华民族解放行动委员会，1947年改称中国农工民主党。',
      quiz:{type:'fill',q:'1930年邓演达等在上海成立的“第三党”是 ______ 。',answer:'中国国民党临时行动委员会',exp:'该党即第三党，1935年改名中华民族解放行动委员会，1947年改称中国农工民主党。'}},
    {ch:'c5',title:'井冈山《土地法》与兴国《土地法》',speak:'1928年12月，毛泽东在井冈山主持制定《土地法》，规定没收一切土地归苏维埃政府所有、按人口平均分配，但存在没收一切土地而非只没收地主土地、土地归政府所有而非归农民所有等缺陷。1929年4月，毛泽东在兴国主持制定《土地法》，改为没收地主阶级土地及公共土地分给无地少地农民并归农民私有，纠正了前一土地法的原则错误，推动了土地革命深入发展。',
      quiz:{type:'choice',q:'1929年兴国《土地法》对井冈山《土地法》的重要修正是？',opts:['由“没收一切土地”改为“没收地主土地”，土地归农民私有','完全取消土地分配','实行土地一律国有','只把土地分给富农'],a:0,exp:'兴国《土地法》把“没收一切土地”改为“没收地主土地”，并确定土地归农民私有。'}},
    {ch:'c5',title:'左翼文化运动',speak:'1930年前后，党领导的文化工作者在上海先后成立中国左翼作家联盟（1930年3月）、中国社会科学家联盟、左翼戏剧家联盟等，形成左翼文化运动。鲁迅是左翼文化运动的旗手，创作了《呐喊》《彷徨》等作品；运动批判国民党文化专制、传播马克思主义，涌现茅盾《子夜》、聂耳《义勇军进行曲》等成果，有力配合了农村革命战争和抗日救亡运动。',
      quiz:{type:'choice',q:'1930年成立、以鲁迅为旗手的左翼文化团体是？',opts:['中国左翼作家联盟','创造社','文学研究会','新月社'],a:0,exp:'中国左翼作家联盟1930年3月在上海成立，鲁迅是其旗手。'}},

    /* ============ 第六章 ============ */
    {ch:'c6',title:'日本侵华与残暴统治',speak:'1931年九一八事变日本侵占东北，1937年卢沟桥事变发动全面侵华战争，实行烧杀抢掠的残暴殖民统治，制造南京大屠杀等惨案。',
      quiz:{type:'fill',q:'______ 年卢沟桥事变，日本发动全面侵华战争。',answer:'1937',exp:'1937 年七七事变（卢沟桥事变）标志全面抗战开始；1931 年九一八为局部侵华。'}},
    {ch:'c6',title:'抗日民族统一战线的建立',speak:'西安事变和平解决促成了国共第二次合作。1937年以国共合作为基础的抗日民族统一战线正式形成，实现全民族抗战。',
      quiz:{type:'choice',q:'抗日民族统一战线正式形成的标志是？',opts:['九一八事变','西安事变和平解决','国民党公布国共合作宣言','百团大战'],a:2,exp:'1937 年 9 月国民党公布国共合作宣言，抗日民族统一战线正式形成。'}},
    {ch:'c6',title:'正面战场与敌后战场',speak:'战略防御阶段正面战场组织淞沪、台儿庄等会战；共产党开辟敌后战场，开展游击战争，逐渐成为抗战的中流砥柱。',
      quiz:{type:'choice',q:'抗日战争中逐渐成为中流砥柱的是？',opts:['国民党正面战场','中国共产党领导的敌后战场','外国援华军队','地方军阀'],a:1,exp:'中国共产党开辟敌后战场、坚持全面抗战路线，成为抗战的中流砥柱。'}},
    {ch:'c6',title:'抗日战争的胜利及其意义',speak:'1945年9月2日日本投降，抗战胜利。这是近代以来中国人民第一次反侵略完全胜利，是世界反法西斯战争重要组成部分。',
      quiz:{type:'fill',q:'______ 年 9 月 2 日，日本正式签署投降书，抗日战争胜利。',answer:'1945',exp:'1945 年抗战胜利，是近代以来中国人民第一次反侵略完全胜利。'}},

    /* ---- 第六章第一节（新增，基于教材PDF：日本发动企图灭亡中国的侵略战争） ---- */
    {ch:'c6',title:'日本侵华的战略方针与东方会议',speak:'1927年日本首相田中义一主持东方会议，通过《对华政策纲要》，叫嚣“惟欲征服世界，必先征服支那”。1929年世界经济危机后，日本加紧实施既定的侵华政策。',
      quiz:{type:'choice',q:'1927年日本首相田中义一主持的哪次会议制定了侵华方针？',opts:['东方会议','巴黎和会','华盛顿会议','开罗会议'],a:0,exp:'东方会议宣示《对华政策纲要》，确立先占满蒙、再征服中国的侵略方针。'}},
    {ch:'c6',title:'九一八事变：日本独占中国东北的开始',speak:'1931年9月18日，日本关东军炸毁南满铁路柳条湖段并反诬中国军队，炮轰北大营，发动九一八事变。至1932年2月东北全境沦陷，日本变中国东北为其独占殖民地。',
      quiz:{type:'fill',q:'______ 年 9 月 18 日，日本关东军制造柳条湖事件，发动九一八事变。',answer:'1931',exp:'九一八事变是日本变中国东北为独占殖民地的起点。'}},
    {ch:'c6',title:'国民党政府的不抵抗主义与“攘外必先安内”',speak:'九一八事变后，蒋介石提出“攘外必先安内”方针，命令东北军绝对抱不抵抗主义，主力用于剿共，对日本一再妥协退让；国际联盟与英美采取姑息纵容政策。',
      quiz:{type:'choice',q:'九一八事变后，国民党政府对日本侵略采取的政策是？',opts:['坚决抵抗','不抵抗主义','联日抗苏','中立观望'],a:1,exp:'国民政府实行不抵抗主义，致使东北迅速沦陷。'}},
    {ch:'c6',title:'华北事变与华北危机',speak:'1935年日本在华北制造事端，使河北、察哈尔两省主权大部丧失，并策动华北五省两市“防共自治运动”、制造傀儡政权，华北成为日军可自由出入的真空地带。',
      quiz:{type:'fill',q:'1935年日本制造______事变，策动华北五省两市“防共自治”，华北危机加深。',answer:'华北',exp:'华北事变使华北主权大部丧失，民族危机空前严重。'}},
    {ch:'c6',title:'七七事变：日本全面侵华战争开始',speak:'1937年7月7日夜，日军在卢沟桥以北演习，借口士兵失踪要求进宛平城搜查，遭拒后炮轰县城。七七事变是日本全面侵华战争的开始，中国进入全民族抗战阶段。',
      quiz:{type:'fill',q:'______ 年 7 月 7 日卢沟桥事变，是日本全面侵华战争的开始。',answer:'1937',exp:'七七事变标志着日本全面侵华和中国全民族抗战的开始。'}},
    {ch:'c6',title:'日本在占领区的残暴殖民统治',speak:'日军在占领区实行残暴殖民统治：1937年12月南京大屠杀，平民和战俘被杀害30万人以上；推行“三光政策”、细菌战与化学战；掳掠劳工形成万人坑；强迫妇女充当日军性奴隶的“慰安妇”制度；强制推行奴化教育。',
      quiz:{type:'choice',q:'1937年12月日军占领南京后制造的大屠杀，被杀害的中国平民和战俘达？',opts:['3万人以上','30万人以上','300万人以上','3000人以上'],a:1,exp:'南京大屠杀是骇人听闻的反人类罪行，遇难者达30万人以上。'}},
    {ch:'c6',title:'日本侵华战争造成的巨大灾难',speak:'据不完全统计，战争期间中国军民伤亡超过3500万；按1937年比价，直接经济损失1000多亿美元，间接经济损失5000多亿美元，中国文化与资源遭到空前摧残。',
      quiz:{type:'fill',q:'据不完全统计，抗日战争期间中国军民伤亡人数超过 ______ 万。',answer:'3500',exp:'中国为世界反法西斯战争付出了巨大民族牺牲。'}},

    /* ---- 第六章第二节（新增，基于教材PDF：中国人民奋起抗击日本侵略者） ---- */
    {ch:'c6',title:'中国共产党率先举起武装抗日旗帜',speak:'在民族危亡关头，中国共产党率先举起武装抗日旗帜。1931年9月20日中共中央发表宣言反对日本强占东三省；1932年4月中华苏维埃临时中央政府对日宣战，并直接领导东北抗日游击战争。',
      quiz:{type:'choice',q:'九一八事变后，率先举武装抗日旗帜、发表反日宣言的是？',opts:['国民党政府','中国共产党','地方军阀','国际联盟'],a:1,exp:'中共在九一八后第三天即发表宣言，号召民族自卫战争。'}},
    {ch:'c6',title:'东北抗日联军与东北游击战争',speak:'中共满洲省委派出大批党员到抗日义勇军中工作。1933年起中共领导的抗日游击队在东北崛起，1936年后陆续改建为东北抗日联军，杨靖宇、赵一曼、赵尚志等领导军民与日军艰苦斗争。',
      quiz:{type:'fill',q:'1936年后，中国共产党领导的东北抗日游击队陆续改建为东北 ______ 军。',answer:'抗日联军',exp:'东北抗联在极端艰苦条件下长期坚持抗日游击战争。'}},
    {ch:'c6',title:'抗日救亡运动的兴起',speak:'九一八后全国兴起抗日救亡运动。1932年一·二八事变中第十九路军奋起抗日；1933年冯玉祥成立察哈尔民众抗日同盟军；同年十九路军将领发动福建事变，其代表与红军签署《反日反蒋的初步协定》。',
      quiz:{type:'choice',q:'1932年一·二八事变中，在淞沪奋起抗日的国民党部队是？',opts:['第二十九军','第十九路军','东北军','八路军'],a:1,exp:'第十九路军在一·二八事变中奋起抗日，得到中共号召支援。'}},
    {ch:'c6',title:'一二·九运动与抗日救亡新高潮',speak:'1935年12月9日，在中共地下党领导和救亡号召下，北平学生举行声势浩大的抗日游行，喊出“反对华北自治”“停止内战，一致对外”等口号。一二·九运动促进中华民族觉醒，标志抗日救亡运动新高潮到来。',
      quiz:{type:'fill',q:'______ 年 12 月 9 日，北平学生发动一二·九运动，标志抗日救亡新高潮到来。',answer:'1935',exp:'一二·九运动促进了中华民族觉醒。'}},
    {ch:'c6',title:'中共抗日民族统一战线新政策',speak:'1935年8月中共发表《八一宣言》，主张停止内战、一致抗日；12月瓦窑堡会议提出建立广泛的抗日民族统一战线，批评“左”倾关门主义，使中共掌握了政治主动权。',
      quiz:{type:'choice',q:'1935年12月，中共中央在哪次会议上提出建立抗日民族统一战线的策略任务？',opts:['遵义会议','瓦窑堡会议','洛川会议','六届六中全会'],a:1,exp:'瓦窑堡会议确立了建立抗日民族统一战线的方针。'}},
    {ch:'c6',title:'西安事变及其和平解决',speak:'1936年12月12日，张学良、杨虎城在西安实行“兵谏”扣留蒋介石，提出停止内战、一致抗日。中共中央以民族大局为重，派周恩来和平解决事变。西安事变和平解决成为时局转换枢纽，十年内战基本结束。',
      quiz:{type:'fill',q:'1936年12月12日______事变和平解决，成为时局转换的枢纽，十年内战基本结束。',answer:'西安',exp:'西安事变的和平解决促成了国共合作抗日。'}},
    {ch:'c6',title:'第二次国共合作正式形成',speak:'卢沟桥事变后，1937年8月红军改编为国民革命军第八路军（朱德、彭德怀），南方八省游击队改编为新四军（叶挺、项英）。9月22日国民党中央通讯社发表中共中央宣言，23日蒋介石谈话承认共产党合法地位，抗日民族统一战线正式形成。',
      quiz:{type:'choice',q:'1937年8月，根据国共协议，红军主力改编为哪支抗日武装？',opts:['八路军','新四军','东北抗联','黄埔学生军'],a:0,exp:'红军主力改编为八路军，南方游击队改编为新四军，第二次国共合作正式形成。'}},

    /* ---- 第六章第三节（新增，基于教材PDF：抗日战争的正面战场） ---- */
    {ch:'c6',title:'战略防御阶段的正面战场',speak:'从卢沟桥事变到1938年10月广州、武汉失守为战略防御阶段。以国民党军队为主体的正面战场组织淞沪、忻口、徐州、武汉等大会战，1938年3月李宗仁指挥台儿庄战役取得大捷。',
      quiz:{type:'fill',q:'1938年3月，李宗仁指挥的 ______ 战役取得台儿庄大捷。',answer:'台儿庄',exp:'台儿庄战役是防御阶段正面战场取得的重大胜利。'}},
    {ch:'c6',title:'爱国官兵的英勇抗战',speak:'正面战场爱国将士表现了空前抗战热情。北平南苑战斗中第二十九军副军长佟麟阁、师长赵登禹阵亡；淞沪会战中团附谢晋元率孤军据守四行仓库，被誉“八百壮士”。',
      quiz:{type:'choice',q:'淞沪会战中率孤军据守四行仓库、被誉为“八百壮士”的团附是？',opts:['佟麟阁','谢晋元','赵登禹','张自忠'],a:1,exp:'谢晋元率部死守四行仓库，振奋了全国抗战士气。'}},
    {ch:'c6',title:'国民党的片面抗战路线及其局限',speak:'国民党实行片面抗战路线，不敢放手发动民众，单纯依靠政府和正规军进行阵地防御战。除台儿庄外多数战役以退却失败告终，导致中国短时间内丧失大片国土。',
      quiz:{type:'choice',q:'国民党在抗日战争中实行的是哪条抗战路线？',opts:['全面抗战路线','片面抗战路线','人民战争路线','游击战路线'],a:1,exp:'片面抗战路线不敢发动群众，是正面战场失利的主观原因。'}},
    {ch:'c6',title:'国民参政会与高校内迁',speak:'抗战初期国民政府实行若干有利政策：1938年初改组军委设政治部聘周恩来任副部长，同年6月成立国民参政会；东部高校内迁，北大、清华、南开迁昆明组建国立西南联合大学。',
      quiz:{type:'fill',q:'抗战时期，北大、清华、南开迁往昆明合并组建为国立 ______ 大学。',answer:'西南联合',exp:'西南联大在艰苦条件下坚持教学科研，培养大批人才。'}},
    {ch:'c6',title:'战略相持阶段国民党抗战日趋消极',speak:'进入相持阶段后，日本对国民党采取以政治诱降为主、军事打击为辅的方针。1939年1月国民党五届五中全会确定“防共、限共、溶共”方针，蒋介石将“抗战到底”解释为恢复卢沟桥事变前状态，标志其逐步转为消极抗战。',
      quiz:{type:'choice',q:'1939年国民党五届五中全会确定的对共方针是？',opts:['联共抗日','防共、限共、溶共','全面合作','停止反共'],a:1,exp:'五届五中全会标志国民党政策转向消极抗战、积极反共。'}},
    {ch:'c6',title:'相持阶段的几次战役与反共摩擦',speak:'相持阶段国民党仍进行过几次较大战役：1939年攻克昆仑关、1940年枣宜会战张自忠殉国、1942年第三次长沙会战歼敌5万余、同年中国远征军入缅作战戴安澜殉国。但国民党又抽调兵力制造多次反共摩擦。',
      quiz:{type:'fill',q:'1940年5月枣宜会战中，第三十三集团军总司令 ______ 殉国。',answer:'张自忠',exp:'张自忠是抗战中牺牲的国民党最高级别将领之一。'}},
    {ch:'c6',title:'豫湘桂大溃败与国民党统治危机',speak:'1944年4月至1945年1月豫湘桂战役中，国民党军队大溃败，丢失146座城市、6000多万人口的20多万平方公里国土。大后方民生凋敝、民怨沸腾，国民党统治陷入深刻危机。',
      quiz:{type:'choice',q:'1944年国民党军队在哪一战役中遭大溃败，丢失大片国土？',opts:['台儿庄战役','豫湘桂战役','第三次长沙会战','昆仑关战役'],a:1,exp:'豫湘桂大溃败成为大后方人心变动的重要转折点。'}},

    /* ---- 第六章第四节（新增，基于教材PDF：抗日战争的中流砥柱） ---- */
    {ch:'c6',title:'全面抗战路线与洛川会议《抗日救国十大纲领》',speak:'与国民党片面抗战路线不同，中共实行全面抗战路线即人民战争路线。1937年8月洛川会议制定《抗日救国十大纲领》，强调必须实行全国军事与人民总动员，坚持统一战线中无产阶级领导权。',
      quiz:{type:'choice',q:'1937年8月，中共中央在哪次会议上制定《抗日救国十大纲领》？',opts:['瓦窑堡会议','洛川会议','遵义会议','六届六中全会'],a:1,exp:'洛川会议确立了全面抗战路线和独立自主的山地游击战方针。'}},
    {ch:'c6',title:'毛泽东《论持久战》的战略总方针',speak:'1938年5月至6月毛泽东发表《论持久战》，批驳“亡国论”“速胜论”，指出中日战争是决死战争，科学预见将经过战略防御、相持、反攻三阶段，战略相持是最关键阶段，最后胜利属于中国。',
      quiz:{type:'fill',q:'毛泽东《论持久战》科学预见抗日战争将经过战略防御、战略 ______ 、战略反攻三阶段。',answer:'相持',exp:'《论持久战》指明持久抗战、最后胜利属于中国的方针。'}},
    {ch:'c6',title:'“兵民是胜利之本”与《论持久战》的历史地位',speak:'毛泽东强调“兵民是胜利之本”，战胜日本必须进行人民战争。《论持久战》系统阐明抗战发展规律，是中国共产党领导抗战的纲领性文献，对全国抗战战略指导产生积极影响。',
      quiz:{type:'choice',q:'毛泽东在《论持久战》中提出“兵民是______之本”。',opts:['胜利','抗战','国防','战争'],a:0,exp:'“兵民是胜利之本”强调了人民战争的伟力。'}},
    {ch:'c6',title:'敌后战场的开辟与平型关大捷',speak:'1937年9月，八路军第一一五师在晋北平型关伏击日军，歼敌1000余人，取得全民族抗战以来中国军队主动寻歼敌人的第一次重大胜利，打破日军不可战胜的神话。',
      quiz:{type:'fill',q:'1937年9月，八路军第一一五师在 ______ 伏击日军，打破其不可战胜的神话。',answer:'平型关',exp:'平型关大捷是八路军出师后取得的第一个重大胜利。'}},
    {ch:'c6',title:'游击战争的战略地位与百团大战',speak:'在相持阶段，敌后游击战争成为主要抗日作战方式。1940年8月至翌年1月八路军总部在华北发动百团大战，参战部队达105个团20余万人，沉重打击了日军。',
      quiz:{type:'choice',q:'1940年8月至1941年1月，八路军在华北发动的大规模进攻战役是？',opts:['台儿庄战役','百团大战','平型关战役','豫湘桂战役'],a:1,exp:'百团大战是相持阶段八路军发动的大规模攻势作战。'}},
    {ch:'c6',title:'统一战线中的独立自主原则',speak:'中共在统一战线中坚持独立自主原则：保持思想、政治、组织上的独立性，放手发动群众、壮大人民力量，坚持对人民军队的绝对领导，对国民党又团结又斗争、以斗争求团结。',
      quiz:{type:'choice',q:'抗日民族统一战线中，中国共产党坚持的方针是？',opts:['一切经过统一战线','一切服从国民党','独立自主、又团结又斗争','放弃领导权'],a:2,exp:'独立自主原则力争中共对抗战的领导权，是引向胜利的中心一环。'}},
    {ch:'c6',title:'坚持抗战团结进步的方针与三次反共高潮',speak:'针对国民党消极抗日积极反共，1939年7月中共提出“坚持抗战到底、巩固国内团结、力求全国进步”三大口号。1939至1943年国民党顽固派发动三次反共高潮，皖南事变中9000多新四军遭包围袭击。',
      quiz:{type:'fill',q:'1941年1月，国民党顽固派制造 ______ 事变，包围袭击新四军军部。',answer:'皖南',exp:'中共以抗日大局为重，在军事上严守自卫、政治上坚决反击。'}},
    {ch:'c6',title:'巩固统一战线的策略总方针',speak:'中共制定“发展进步势力、争取中间势力、孤立顽固势力”的策略总方针，对顽固派贯彻又联合又斗争和有理、有利、有节的原则，对坚持全民族抗战到底意义重大。',
      quiz:{type:'choice',q:'巩固抗日民族统一战线的策略总方针是？',opts:['一切联合、否认斗争','发展进步势力、争取中间势力、孤立顽固势力','只斗争不联合','依靠顽固势力'],a:1,exp:'这一方针正确处理了统一战线内部的阶级关系。'}},
    {ch:'c6',title:'抗日民主根据地的“三三制”政权建设',speak:'根据地政权是抗日民族统一战线性质政权，工作人员分配实行“三三制”：共产党员、党外进步人士和中间派各占三分之一，容纳各方面代表，团结赞成抗日又赞成民主的各阶级阶层。',
      quiz:{type:'fill',q:'抗日民主根据地政权实行“三三制”，共产党员、党外进步人士和 ______ 各占三分之一。',answer:'中间派',exp:'三三制有利于团结一切抗日力量，发扬人民民主。'}},
    {ch:'c6',title:'减租减息与大生产运动',speak:'根据地停止没收地主土地，普遍实行减租减息、交租交息，联合地主抗日；为克服困难，毛泽东号召“自己动手，丰衣足食”，开展大生产运动，三五九旅把南泥湾变成“陕北江南”。',
      quiz:{type:'choice',q:'为克服根据地困难，八路军第三五九旅把哪里的荒山变成“陕北江南”？',opts:['井冈山','南泥湾','延安','狼牙山'],a:1,exp:'大生产运动为坚持抗战奠定了物质基础。'}},
    {ch:'c6',title:'延安整风运动',speak:'1941至1942年中共开展延安整风运动，内容是反对主观主义以整顿学风、反对宗派主义以整顿党风、反对党八股以整顿文风。整风是深刻的马克思主义思想教育运动，使实事求是思想路线在全党确立。',
      quiz:{type:'fill',q:'延安整风运动最主要任务是反对 ______ 以整顿学风。',answer:'主观主义',exp:'整风运动坚持理论联系实际，确立了实事求是的思想路线。'}},
    {ch:'c6',title:'新民主主义理论的系统阐明',speak:'1939至1940年毛泽东撰写《〈共产党人〉发刊词》《中国革命和中国共产党》《新民主主义论》等，系统阐明新民主主义革命理论，指出统一战线、武装斗争、党的建设是战胜敌人的三大法宝。',
      quiz:{type:'choice',q:'毛泽东指出，中国共产党战胜敌人的三个主要法宝是？',opts:['统一战线、武装斗争、党的建设','土地革命、武装斗争、根据地建设','实事求是、群众路线、独立自主','理论联系实际、密切联系群众、批评与自我批评'],a:0,exp:'三大法宝是新民主主义革命经验的高度概括。'}},
    {ch:'c6',title:'六届六中全会与“马克思主义的中国化”命题',speak:'1938年9月至11月中共扩大的六届六中全会在延安召开。毛泽东提出“马克思主义的中国化”命题，全会基本纠正王明右倾错误，进一步巩固毛泽东的领导地位，毛泽东称“六中全会是决定中国之命运的”。',
      quiz:{type:'fill',q:'在六届六中全会上，毛泽东明确提出“______的中国化”命题。',answer:'马克思主义',exp:'六届六中全会推动了马克思主义与中国实际相结合。'}},
    {ch:'c6',title:'中共七大与毛泽东思想指导地位确立',speak:'1945年4月至6月中共七大在延安举行，制定“放手发动群众，壮大人民力量，在党的领导下打败日本侵略者，解放全国人民”的政治路线，把毛泽东思想确立为党的指导思想并写入党章，形成三大作风，是“团结的大会，胜利的大会”，延安精神也在此时期形成。',
      quiz:{type:'choice',q:'哪次大会把毛泽东思想确立为党的指导思想并写入党章？',opts:['六届六中全会','中共七大','洛川会议','瓦窑堡会议'],a:1,exp:'中共七大是党走向成熟的历史里程碑，确立毛泽东思想指导地位。'}},

    /* ---- 第六章第五节（新增，基于教材PDF：抗日战争的胜利及其意义） ---- */
    {ch:'c6',title:'解放区战场全面反攻与日本投降',speak:'1945年8月9日苏联红军进入中国东北对日作战，毛泽东发表《对日寇的最后一战》，朱德发布反攻命令。8月15日日本天皇发布《终战诏书》无条件投降，9月2日签署投降书，9月3日成为抗战胜利纪念日。',
      quiz:{type:'fill',q:'______ 年 9 月 3 日是中国人民抗日战争胜利纪念日。',answer:'1945',exp:'1945年9月2日日本签署投降书，抗战取得完全胜利。'}},
    {ch:'c6',title:'台湾光复',speak:'1945年10月25日，中国政府在台湾举行受降仪式，被日本占领50年之久的台湾及澎湖列岛重归中国主权管辖，这是抗日战争取得完全胜利的重要标志。',
      quiz:{type:'fill',q:'1945年10月25日，被日本占领50年的 ______ 重归中国主权管辖。',answer:'台湾',exp:'台湾光复是抗战完全胜利的重要标志。'}},
    {ch:'c6',title:'中国战场：世界反法西斯战争的东方主战场',speak:'中国抗战从1931年即已开始，是世界反法西斯战争的重要组成部分和东方主战场。中国牵制了日本陆军主力，使苏联避免两线作战、推迟日本南进，罗斯福、崔可夫都高度评价中国的战略作用。',
      quiz:{type:'choice',q:'中国抗日战争在世界反法西斯战争中处于什么地位？',opts:['欧洲主战场','东方主战场','次要战场','无关紧要'],a:1,exp:'中国战场是东方主战场，长期牵制日军主力。'}},
    {ch:'c6',title:'世界反法西斯力量对中国的援助',speak:'中国抗战得到国际社会支持：苏联最早提供援助并派志愿航空队；美国陈纳德组建援华航空队、开辟驼峰航线；白求恩、柯棣华等国际友人来华救死扶伤，许多国家反法西斯战士直接投身中国抗战。',
      quiz:{type:'fill',q:'抗战时期，加拿大医生 ______ 不远万里来华救死扶伤，以身殉职。',answer:'白求恩',exp:'白求恩、柯棣华等国际主义战士为中国抗战作出贡献。'}},
    {ch:'c6',title:'抗日战争胜利的原因',speak:'抗战胜利的原因：以爱国主义为核心的民族精神是决定性因素；中国共产党的中流砥柱作用是关键；全民族抗战是重要法宝；同时也离不开世界爱好和平力量的同情与支持。',
      quiz:{type:'choice',q:'中国人民抗日战争胜利的决定因素是什么？',opts:['国际援助','以爱国主义为核心的民族精神','外国军队','经济实力'],a:1,exp:'民族精神是抗战胜利的决定因素，中共中流砥柱是关键。'}},
    {ch:'c6',title:'抗日战争胜利的伟大意义',speak:'抗战胜利是近代以来中国人民第一次反侵略完全胜利，彻底粉碎日本殖民奴役图谋、洗刷了屡战屡败的民族耻辱，是中华民族走向伟大复兴的历史转折点，中国国际地位显著提高。',
      quiz:{type:'fill',q:'中国人民抗日战争是近代以来中国人民反抗外敌入侵第一次取得 ______ 胜利的民族解放斗争。',answer:'完全',exp:'抗战胜利是民族复兴的历史转折点。'}},
    {ch:'c6',title:'伟大抗战精神的内涵',speak:'抗战精神包括：天下兴亡、匹夫有责的爱国情怀，视死如归、宁死不屈的民族气节，不畏强暴、血战到底的英雄气概，百折不挠、坚忍不拔的必胜信念，是弥足珍贵的精神财富。',
      quiz:{type:'choice',q:'伟大抗战精神不包括下列哪一项？',opts:['天下兴亡、匹夫有责的爱国情怀','视死如归、宁死不屈的民族气节','苟且偷生、卖国求荣','百折不挠、坚忍不拔的必胜信念'],a:2,exp:'抗战精神是中华民族的宝贵精神财富。'}},

    /* 大纲补缺：伪政权、宋庆龄与救国会、逼蒋抗日、爱国人士、精兵简政、历史决议、中国战区与远征军、联合国制宪 */
    {ch:'c6',title:'伪“满洲国”与关内伪政权',speak:'1932年3月，日本扶植溥仪在长春成立伪“满洲国”，1934年改称“满洲帝国”，以“日满亲善”名义实行殖民统治。1937年12月日本在北平扶植成立伪“中华民国临时政府”，1938年3月在南京成立伪“中华民国维新政府”；1940年3月汪精卫在南京建立伪“中华民国国民政府”。这些都是日本“以华制华”的傀儡工具。',
      quiz:{type:'fill',q:'1932年日本在中国东北扶植溥仪建立的傀儡政权是伪 ______ 。',answer:'满洲国',exp:'伪“满洲国”成立于1932年3月，是日本殖民统治东北的工具。'}},
    {ch:'c6',title:'宋庆龄与保卫中国同盟',speak:'宋庆龄始终坚持孙中山的革命立场，抗战爆发后在上海发起成立中国妇女慰劳自卫抗战将士总会；1938年在香港创建保卫中国同盟，向海外华侨和国际友人募集医药、物资支援抗日根据地，并出版《保卫中国同盟新闻通讯》。她被誉为本世纪最伟大的女性之一，是爱国民主人士的杰出代表。',
      quiz:{type:'fill',q:'1938年宋庆龄在香港创建、支援抗日根据地的组织是 ______ 。',answer:'保卫中国同盟',exp:'保卫中国同盟是宋庆龄1938年在香港创建的，主要向海外募集物资支援抗战。'}},
    {ch:'c6',title:'全国各界救国联合会与《中国人民对日作战的基本纲领》',speak:'1934年4月，中国共产党提出《中国人民对日作战的基本纲领》，经宋庆龄等1779人联名发表，主张全体武装总动员、全体人民总动员。1936年5月，沈钧儒、邹韬奋等在上海成立全国各界救国联合会，要求停止内战、一致对外，推动抗日救亡运动走向高潮。国民党于1936年11月制造“七君子事件”镇压救国会领袖。',
      quiz:{type:'choice',q:'1936年5月在上海成立的全国性抗日救亡团体是？',opts:['全国各界救国联合会','中国民权保障同盟','保卫中国同盟','中华民族解放行动委员会'],a:0,exp:'全国各界救国联合会1936年5月在上海成立，其领袖后被国民党逮捕，即“七君子事件”。'}},
    {ch:'c6',title:'从“抗日反蒋”到“逼蒋抗日”',speak:'1935年8月，中共驻共产国际代表团以中华苏维埃共和国中央政府和中共中央名义发表《为抗日救国告全国同胞书》（八一宣言），提出停止内战、一致抗日，组织全中国统一的国防政府和抗日联军。同年12月瓦窑堡会议确定抗日民族统一战线策略。1937年2月，中共中央致国民党五届三中全会电，提出停止内战、一致对外等五项要求和四项保证，标志着“逼蒋抗日”方针的确立。',
      quiz:{type:'fill',q:'1935年8月提出“停止内战，一致抗日”的文件是《 ______ 》。',answer:'为抗日救国告全国同胞书',exp:'该文件即八一宣言，标志着党的抗日民族统一战线策略的重要发展。'}},
    {ch:'c6',title:'邓玉芬、马本斋、陈嘉庚等爱国者',speak:'全民族抗战中涌现出大批爱国人士：北京密云农民邓玉芬送丈夫和五个儿子参军，全部为国捐躯；回族马本斋率冀中回民支队英勇杀敌，所部被誉为“百战百胜的回民支队”；爱国华侨陈嘉庚组织南洋华侨筹赈祖国难民总会，募集巨款并动员三千多名机工回国服务，被誉为“华侨旗帜、民族光辉”。',
      quiz:{type:'choice',q:'组织南洋华侨筹赈祖国难民总会支援抗战的爱国华侨是？',opts:['陈嘉庚','司徒美堂','蚁光炎','李清泉'],a:0,exp:'陈嘉庚领导南洋华侨筹赈祖国难民总会，是华侨支援抗战的旗帜。'}},
    {ch:'c6',title:'精兵简政',speak:'1941年11月，开明绅士李鼎铭等在陕甘宁边区第二届参议会上提出“精兵简政”提案，被中共中央采纳。其内容是精简机构、裁减冗员、提高效能、减轻人民负担。精兵简政克服了抗日根据地的物质困难，提高了工作效率和部队战斗力，是抗日根据地政权建设的重要经验，毛泽东称之为“一个极其重要的政策”。',
      quiz:{type:'fill',q:'抗战时期由李鼎铭提出、被中共中央采纳的重要政策是“ ______ ”。',answer:'精兵简政',exp:'精兵简政1941年由李鼎铭提出，是克服根据地困难的重要政策。'}},
    {ch:'c6',title:'《关于若干历史问题的决议》',speak:'1945年4月，中共六届七中全会通过《关于若干历史问题的决议》，总结建党以来特别是六届四中全会以来各次“左”右倾错误，着重批判王明“左”倾教条主义，肯定毛泽东的正确路线，对若干重大历史问题作出结论。它统一了全党思想，为中共七大的召开和毛泽东思想确立为党的指导思想奠定了基础。',
      quiz:{type:'choice',q:'1945年中共六届七中全会通过的重要文献是？',opts:['《关于若干历史问题的决议》','《关于建国以来党的若干历史问题的决议》','《论联合政府》','《新民主主义论》'],a:0,exp:'《关于若干历史问题的决议》是党第一个历史决议，为七大召开作了思想准备。'}},
    {ch:'c6',title:'中国战区与中国远征军',speak:'1942年1月，中国与美英苏等26国签署《联合国家宣言》，世界反法西斯同盟正式形成。中国战区成立，蒋介石任最高统帅，史迪威任参谋长。为保卫滇缅公路，中国组建远征军于1942年入缅作战，师长戴安澜在缅北殉国；1943年至1945年经滇西缅北反攻，收复腾冲、龙陵，打通中印公路，为世界反法西斯战争作出重大贡献。',
      quiz:{type:'fill',q:'1942年入缅协同盟军作战、师长戴安澜殉国的部队是 ______ 。',answer:'中国远征军',exp:'中国远征军1942年入缅作战，戴安澜在缅北壮烈殉国。'}},
    {ch:'c6',title:'联合国制宪会议',speak:'1945年4月至6月，联合国制宪会议在旧金山召开，中国代表团出席并在《联合国宪章》上第一个签字，成为联合国创始会员国和安理会常任理事国。这是中国人民抗日战争胜利的重要成果，中国的国际地位显著提高。同年10月24日《联合国宪章》生效，联合国正式成立。',
      quiz:{type:'choice',q:'中国成为联合国安理会常任理事国是在？',opts:['1945年旧金山联合国制宪会议','1943年开罗会议','1945年雅尔塔会议','1945年波茨坦会议'],a:0,exp:'1945年旧金山联合国制宪会议上，中国成为联合国创始会员国和安理会常任理事国。'}},

    /* ============ 第七章 ============ */
    {ch:'c7',title:'争取和平民主与解放战争的进程',speak:'抗战胜利后，共产党争取和平民主，重庆谈判签订"双十协定"。国民党发动全面内战后，解放军以自卫战争粉碎进攻并转入战略反攻。',
      quiz:{type:'choice',q:'重庆谈判签订的文件是？',opts:['《共同纲领》','"双十协定"','《论联合政府》','《停战协定》'],a:1,exp:'1945 年重庆谈判达成"双十协定"。'}},
    {ch:'c7',title:'土地改革与第二条战线',speak:'解放区开展土地改革（耕者有其田），广泛发动农民；国统区形成反蒋的第二条战线，孤立了国民党反动统治。',
      quiz:{type:'choice',q:'解放战争时期国统区的爱国民主运动被称为？',opts:['第一条战线','第二条战线','第三条道路','中间路线'],a:1,exp:'国统区反蒋的爱国民主运动形成第二条战线，配合军事斗争。'}},
    {ch:'c7',title:'共产党与民主党派的合作',speak:'共产党坚持统一战线，与各民主党派团结合作。1949年确立了中国共产党领导的多党合作和政治协商制度的基本格局。',
      quiz:{type:'choice',q:'我国的一项基本政治制度是？',opts:['多党合作和政治协商制度','两党制','一党制','三权分立'],a:0,exp:'中国共产党领导的多党合作和政治协商制度是基本政治制度。'}},
    {ch:'c7',title:'人民政协与新中国成立',speak:'1949年9月中国人民政治协商会议通过《共同纲领》，10月1日中华人民共和国成立，中国人民从此站起来了。',
      quiz:{type:'fill',q:'______ 年 10 月 1 日，中华人民共和国成立。',answer:'1949',exp:'1949 年 10 月 1 日开国大典，新中国诞生。'}},

    /* ---- 第七章第一节（新增，基于教材PDF：从争取和平民主到击退国民党的军事进攻） ---- */
    {ch:'c7',title:'战后国际国内政治形势',speak:'抗战胜利后，实现和平民主、建设新中国是人民热望。国际上帝国主义势力削弱、社会主义与民族解放力量发展；国内人民觉悟组织程度空前提高，人民军队发展到约132万人，解放区人口近1亿，中共经整风达到高度团结统一。',
      quiz:{type:'fill',q:'抗战胜利后，人民军队发展到约 ______ 万人，解放区人口近1亿。',answer:'132',exp:'战后人民力量空前壮大，为争取和平民主、打败内战提供了条件。'}},
    {ch:'c7',title:'国民党的独裁内战方针',speak:'国民党统治集团的根本目标是维持蒋介石独裁统治、继续走半殖民地半封建老路。以武力消灭共产党及其军队和解放区政权是蒋介石集团的既定方针，抗战刚胜利中国就面临内战危险。',
      quiz:{type:'choice',q:'抗战胜利后，国民党统治集团的根本目标是？',opts:['建立民主联合政府','维持蒋介石独裁统治、走半殖民地半封建老路','实行土地改革','联共抗日'],a:1,exp:'蒋介石集团企图篡夺胜利果实，继续独裁统治。'}},
    {ch:'c7',title:'美国扶蒋反共政策',speak:'控制中国是美国全球战略的重要组成部分。美国的短期目标是“阻止共产党完全控制中国”，一方面要求国民党搞形式民主以诱使或迫使共产党交出军队，另一方面大力援助国民党运兵抢占战略要点。',
      quiz:{type:'choice',q:'二战后美国对华政策的短期目标是？',opts:['支持共产党','阻止共产党完全控制中国','扶植日本','中立观望'],a:1,exp:'美国出于全球战略大力援蒋，干涉中国内政。'}},
    {ch:'c7',title:'中共争取和平民主的方针',speak:'基于真诚愿望与清醒认识，中共中央认为同国民党谈判是必要的。1945年8月25日中共中央发表《对目前时局的宣言》，提出“和平、民主、团结”口号；此前政治局扩大会议确定“蒋反我亦反，蒋停我亦停”方针。',
      quiz:{type:'fill',q:'1945年8月25日，中共中央发表《对目前时局的宣言》，提出“和平、______、团结”口号。',answer:'民主',exp:'中共真诚争取和平民主，同时做好自卫准备。'}},
    {ch:'c7',title:'重庆谈判与“双十协定”',speak:'1945年8月14日、20日、23日蒋介石三次电邀毛泽东赴重庆。为争取和平，毛泽东于8月28日偕周恩来、王若飞赴渝谈判。10月10日双方签署《政府与中共代表会谈纪要》，即“双十协定”，确认和平建国基本方针。',
      quiz:{type:'choice',q:'1945年重庆谈判中，与国民党签署“双十协定”的中国共产党代表是？',opts:['毛泽东、周恩来、王若飞','朱德、刘少奇','邓小平','陈独秀'],a:0,exp:'毛泽东亲赴重庆谈判，体现中共谋求和平的诚意。'}},
    {ch:'c7',title:'政治协商会议（旧政协）的召开',speak:'1946年1月10日，国共双方下达停战令，同一天政治协商会议在重庆开幕。出席会议的有国民党、共产党、民盟、青年党和无党派人士代表共38人，推动达成政府组织案、国民大会案、和平建国纲领、军事问题案、宪法草案案五项协议。',
      quiz:{type:'fill',q:'1946年1月10日，国共双方下达停战令，同日 ______ 会议在重庆开幕。',answer:'政治协商',exp:'政协协议有利于冲破独裁、实行民主政治。'}},
    {ch:'c7',title:'维护和破坏政协协议的较量',speak:'中共准备严格履行政协协议，同时提高警惕、做好自卫准备。国民党从来未准备履行政协协议，在六届二中全会上蒋介石命令追随者对政协协议“就其荦荦大端，妥筹补救”，最终彻底撕毁协议。',
      quiz:{type:'choice',q:'国民党六届二中全会上，蒋介石对政协协议的态度是？',opts:['坚决履行','命令追随者“妥筹补救”加以破坏','修改文字','公开支持'],a:1,exp:'国民党根本不打算履行政协协议，终将其撕毁。'}},
    {ch:'c7',title:'全面内战的爆发',speak:'1946年6月26日，国民党军以进攻中原解放区为起点挑起全面内战；同年10月11日占张家口，随后宣布包办“国民大会”。1947年3月，国民党限令中共驻南京、上海、重庆代表全部撤返，一切和平谈判之门都被关闭。',
      quiz:{type:'fill',q:'______ 年 6 月 26 日，国民党军进攻中原解放区，全面内战爆发。',answer:'1946',exp:'国民党悍然发动全面内战，和平努力未能阻止战争。'}},
    {ch:'c7',title:'全面内战爆发时的力量对比',speak:'全面内战爆发时，国民党拥有约430万军队，控制全国76%面积、3.39亿人口和几乎所有大城市；美国还为其训练装备50万军队。解放军总兵力仅约127万，解放区人口1.36亿、面积仅占24%，且被分割包围、无外援。',
      quiz:{type:'choice',q:'全面内战爆发时，国民党军队总兵力约为多少？',opts:['约127万','约430万','约373万','约100万'],a:1,exp:'国民党在数量和装备上占优势，但战争性质决定人心向背。'}},
    {ch:'c7',title:'以革命战争反对反革命战争',speak:'毛泽东指出，必须打败蒋介石，也能够打败蒋介石。蒋介石军事优势和美国援助只是临时因素，而其战争的反人民性质、人心的向背才是经常起作用的因素。政治上建立最广泛的人民民主统一战线，军事上集中优势兵力、各个歼灭敌人。',
      quiz:{type:'choice',q:'毛泽东认为能够打败蒋介石的“经常起作用的因素”是？',opts:['美国的援助','蒋介石军事力量的优势','战争的反人民性质与人心的向背','国际干涉'],a:2,exp:'人心的向背是战争胜负的政治基础。'}},
    {ch:'c7',title:'国民党军队的重点进攻',speak:'1946年6月至1947年6月，人民军队处于战略防御阶段，战争主要在解放区进行。国民党军被迫放弃全面进攻，改为对陕北、山东两解放区的重点进攻；解放军经内线作战打退重点进攻并开始局部反攻。',
      quiz:{type:'fill',q:'1947年3月至6月，国民党军改为对 ______、山东两解放区的重点进攻。',answer:'陕北',exp:'解放军在内线作战中打退重点进攻，战局粉碎了速战速决计划。'}},

    /* ---- 第七章第二节（新增，基于教材PDF：全国解放战争的发展和第二条战线的形成） ---- */
    {ch:'c7',title:'人民解放军转入战略进攻',speak:'经过一年作战，1947年7月国民党军由430万降至373万，解放军由127万增至195万。中共中央当机立断转入全国性反攻。1947年6月底，刘伯承、邓小平率晋冀鲁豫野战军主力千里跃进大别山；陈毅、粟裕挺进苏鲁豫皖，陈赓、谢富治挺进豫西，三路大军揭开战略进攻序幕。',
      quiz:{type:'fill',q:'1947年6月底，刘伯承、邓小平率领晋冀鲁豫野战军主力千里跃进 ______ 山。',answer:'大别',exp:'三路大军相互策应，将战争引向国统区，揭开战略进攻序幕。'}},
    {ch:'c7',title:'“打倒蒋介石，解放全中国”口号',speak:'1947年10月10日，中国人民解放军总部发表宣言，提出“打倒蒋介石，解放全中国”的口号，极大鼓舞了全军指战员和全国人民的斗志。',
      quiz:{type:'choice',q:'1947年10月10日解放军总部宣言提出的口号是？',opts:['和平、民主、团结','打倒蒋介石，解放全中国','停止内战，一致对外','反对华北自治'],a:1,exp:'这一口号成为解放战争后期的行动号召。'}},
    {ch:'c7',title:'十二月会议（杨家沟会议）',speak:'1947年12月，中共中央在陕北米脂县杨家沟召开会议，制定夺取全国胜利的行动纲领。毛泽东指出，中国革命已发展到历史转折点，即蒋介石20年反革命统治由发展到消灭的转折点，也是100多年来帝国主义在华统治由发展到消灭的转折点。',
      quiz:{type:'fill',q:'1947年12月，中共中央在陕北米脂县 ______ 召开会议，制定夺取全国胜利的行动纲领。',answer:'杨家沟',exp:'十二月会议为夺取全国胜利作了思想与政策准备。'}},
    {ch:'c7',title:'土地改革：从“五四指示”到《中国土地法大纲》',speak:'1946年5月4日中共中央发布《关于土地问题的指示》（五四指示）。为推动土改深入，1947年7月至9月党在西柏坡召开全国土地会议，制定《中国土地法大纲》，明确规定“废除封建性及半封建性剥削的土地制度，实行耕者有其田的土地制度”。',
      quiz:{type:'choice',q:'1947年全国土地会议制定、明确“耕者有其田”的纲领性文件是？',opts:['《五四指示》','《中国土地法大纲》','《共同纲领》','《论联合政府》'],a:1,exp:'《中国土地法大纲》是一个彻底反封建的土地革命纲领。'}},
    {ch:'c7',title:'土地改革运动的热潮与意义',speak:'全国土地会议后，解放区迅速掀起土改热潮。到1948年秋，1亿人口的解放区消灭了封建生产关系，广大农民政治觉悟和组织程度空前提高，踊跃参军、送粮、支前，为打败蒋介石、建立新中国奠定了深厚的群众基础。',
      quiz:{type:'fill',q:'到1948年秋，约 ______ 亿人口的解放区通过土改消灭了封建生产关系。',answer:'1',exp:'土地改革从根本上摧毁封建制度根基，赢得农民拥护。'}},
    {ch:'c7',title:'国民党统治区的政治经济危机',speak:'国民党政府专制独裁、官员贪污腐败，接收变成“劫收”，迅速丧失民心。为筹措内战经费，它无限制发行纸币：1948年8月法币发行额比1937年增发47万多倍，物价暴涨725万多倍，恶性通胀实质是对国统区人民的普遍掠夺。',
      quiz:{type:'choice',q:'解放战争时期国民党政府滥发纸币造成的后果是？',opts:['物价稳定','恶性通货膨胀、民不聊生','经济繁荣','财政盈余'],a:1,exp:'恶性通胀使国统区陷入严重经济危机。'}},
    {ch:'c7',title:'国统区学生运动的高涨',speak:'国统区以学生运动为先导的人民民主运动迅速发展：1945年底昆明“一二·一”运动；1946年12月北平“抗暴运动”（一二三〇运动）扩展到14省26市；1947年5月20日南京、北平爆发“五二〇”反饥饿反内战运动，扩展到60多城市。',
      quiz:{type:'fill',q:'1947年5月20日，南京、北平爆发“______”反饥饿反内战运动。',answer:'五二〇',exp:'学生运动的高涨促进了整个人民民主运动的高涨。'}},
    {ch:'c7',title:'第二条战线的形成',speak:'在全面内战爆发前，1946年6月23日上海人民团体联合会请愿团在南京下关遭暴徒围殴（马叙伦、雷洁琼等受伤）。1947年全国20多城市120万工人罢工，农村民变扩展到300多县。国统区爱国民主运动形成配合解放战争的第二条战线，国民党政府处在全民包围中。',
      quiz:{type:'choice',q:'配合人民解放军军事斗争、在国统区形成的“第二条战线”是指？',opts:['国民党军队的正面进攻','国统区的爱国民主运动','国外援助','农村游击战'],a:1,exp:'第二条战线使国民党在政治战线也打了败仗。'}},

    /* ---- 第七章第三节（新增，基于教材PDF：中国共产党与民主党派的团结合作） ---- */
    {ch:'c7',title:'各民主党派的历史发展',speak:'中国的民主党派少数成立于大革命和土地革命时期，多数成立于抗日战争和解放战争时期，主要有民革、民盟、民建、民进、农工党、致公党、九三学社、台盟。如民革1948年1月1日在香港成立（李济深为主席），九三学社1946年5月4日在重庆正式成立。',
      quiz:{type:'choice',q:'下列哪一民主党派于1948年1月1日在香港正式成立？',opts:['中国民主同盟','中国国民党革命委员会（民革）','中国民主建国会','九三学社'],a:1,exp:'民革由国民党民主派和其他爱国民主人士联合组成。'}},
    {ch:'c7',title:'民主党派的社会基础与性质',speak:'各民主党派形成时的社会基础，主要是民族资产阶级、城市小资产阶级以及同这些阶级相联系的知识分子和其他爱国分子。它们是这些阶级阶层在反帝爱国和争取民主共同要求基础上的联合，是阶级联盟性质的政党。',
      quiz:{type:'choice',q:'中国各民主党派的社会基础主要是？',opts:['大地主大资产阶级','民族资产阶级、城市小资产阶级及联系的知识分子和其他爱国分子','买办资产阶级','农民阶级'],a:1,exp:'民主党派是阶级联盟性质的政党，具有爱国民主的进步性。'}},
    {ch:'c7',title:'民主党派的政治态度',speak:'抗战胜利后民主党派政纲不尽相同，但都主张爱国、反对卖国，主张民主、反对独裁，同中共新民主主义革命政纲基本一致。它们大多从成立起就同中共建立合作关系，作为“第三方面”同中共一起反对国民党内战独裁、为和平民主奔走。',
      quiz:{type:'fill',q:'抗战胜利后，民主党派大多作为“第 ______ 方面”，同中共合作反对国民党内战独裁。',answer:'三',exp:'民主党派在政协会议和爱国民主运动中与中共密切合作。'}},
    {ch:'c7',title:'第三条道路（中间路线）的幻灭',speak:'战后某些民主党派领导人鼓吹“中间路线”，主张走英美式民主、改良资本主义的和平道路，实质是旧民主主义方案。但中国面临两种命运尖锐斗争，客观形势决定没有走中间路线的余地；青年党、民社党跟随国民党，民盟大多数靠近共产党。',
      quiz:{type:'choice',q:'抗战胜利后某些人鼓吹的“中间路线”（第三条道路）在中国的结局是？',opts:['成功建立资产阶级共和国','行不通、归于幻灭','成为执政路线','被中共采纳'],a:1,exp:'资产阶级共和国方案在中国行不通。'}},
    {ch:'c7',title:'国民党对民主党派的迫害',speak:'国民党当局不仅仇视共产党，也敌视民主党派。继李公朴、闻一多在昆明遭暗杀后，1947年5月诬蔑民盟等“受中共之命”，10月宣布民盟“为非法团体”并严加取缔，11月民盟总部被迫宣布解散，和平改良的最后幻想破灭。',
      quiz:{type:'choice',q:'1947年10月，国民党当局宣布哪一组织“为非法团体”并严加取缔？',opts:['中国国民党','民主同盟（民盟）','青年党','中国共产党'],a:1,exp:'国民党的迫害使民主党派彻底放弃对国民党的幻想。'}},
    {ch:'c7',title:'民盟一届三中全会',speak:'1948年1月，民盟领导人沈钧儒等在香港召开民盟一届三中全会，宣布不接受解散民盟的任何决定，恢复民盟总部。会议明确指出独立的中间路线不符合中国现实环境、“行不通”，民盟必须站在人民、民主、革命的立场，与中共携手合作。',
      quiz:{type:'fill',q:'1948年1月，民盟一届三中全会明确宣告独立的中间路线“______”。',answer:'行不通',exp:'民盟转向与中共合作，标志民主党派政治立场的根本变化。'}},
    {ch:'c7',title:'“五一”口号与协商建国序幕',speak:'1948年4月30日，中共中央在纪念五一国际劳动节口号中提出：“各民主党派、各人民团体、各社会贤达迅速召开政治协商会议，讨论并实现召集人民代表大会，成立民主联合政府。”这一号召得到热烈响应，揭开协商建国序幕，奠定多党合作和政治协商制度的基础。',
      quiz:{type:'choice',q:'1948年“五一”口号提出的重大主张是？',opts:['召开政治协商会议、成立民主联合政府','实行君主立宪','武装夺取政权','停止一切谈判'],a:0,exp:'“五一”口号得到各民主党派响应，开启协商建国进程。'}},
    {ch:'c7',title:'多党合作和政治协商格局的形成',speak:'1949年1月22日，李济深、沈钧儒等55位民主党派领导人和无党派民主人士联合发表《对时局的意见》，一致认定中共主张“符合于全国人民大众的要求”，公开表示愿在中共领导下共策进行。这标志着中国共产党领导的多党合作政治格局形成。',
      quiz:{type:'fill',q:'1949年1月22日，李济深、沈钧儒等55人发表《对时局的意见》，公开接受 ______ 的领导。',answer:'中国共产党',exp:'民主党派公开自愿接受中共领导，多党合作格局由此形成。'}},

    /* ---- 第七章第四节（新增，基于教材PDF：建立人民民主专政的新中国） ---- */
    {ch:'c7',title:'辽沈、淮海、平津三大战役',speak:'1948年秋战略决战时机成熟。人民解放军先后发动三大战役：辽沈战役（1948.9.12—11.2，歼敌47.2万）、淮海战役（1948.11.6—1949.1.10，歼敌55.5万，总前委邓小平为书记）、平津战役（1948.11.29—1949.1.31，歼敌52万余）。历时4个月零19天，共歼敌154万余，国民党主要军事力量基本被摧毁。',
      quiz:{type:'choice',q:'淮海战役总前委的书记是？',opts:['刘伯承','邓小平','陈毅','粟裕'],a:1,exp:'三大战役是人民战争的伟大胜利，基本摧毁国民党反动统治的主要军事力量。'}},
    {ch:'c7',title:'人民解放军向全国进军与南京解放',speak:'1949年元旦蒋介石发表“求和”声明。1月14日毛泽东提出八项条件。由于国民党拒绝在《国内和平协定》上签字，4月21日毛泽东、朱德发布《向全国进军的命令》。4月23日解放军占领南京，宣告延续22年的国民党反动统治覆灭。',
      quiz:{type:'fill',q:'______ 年 4 月 23 日，人民解放军占领南京，国民党反动统治覆灭。',answer:'1949',exp:'渡江战役摧毁长江防线，国民党政权土崩瓦解。'}},
    {ch:'c7',title:'中共七届二中全会与“两个务必”',speak:'1949年3月中共七届二中全会召开，规定全国胜利后在政治、经济、外交方面的基本政策，指出中国由农业国转工业国、由新民主主义社会转社会主义社会的发展方向。毛泽东提出“两个务必”：务必保持谦虚谨慎不骄不躁、务必保持艰苦奋斗的作风，并警惕“糖衣炮弹”攻击。',
      quiz:{type:'choice',q:'毛泽东在七届二中全会上提出的“两个务必”不包括下列哪一项？',opts:['务必保持谦虚谨慎不骄不躁的作风','务必保持艰苦奋斗的作风','务必争取外援','警惕糖衣炮弹攻击'],a:2,exp:'七届二中全会为执政作了重要准备，提出“进京赶考”的清醒认识。'}},
    {ch:'c7',title:'毛泽东《论人民民主专政》',speak:'1949年6月30日，毛泽东发表《论人民民主专政》，明确指出人民民主专政需要工人阶级的领导；其基础是工人阶级、农民阶级和城市小资产阶级的联盟，主要是工人和农民的联盟；民族资产阶级不能充当革命领导者，也不应在国家政权中占主要地位。',
      quiz:{type:'fill',q:'《论人民民主专政》指出，人民民主专政的领导阶级是 ______ 阶级。',answer:'工人',exp:'该文与七届二中全会决议构成《共同纲领》的基础。'}},
    {ch:'c7',title:'人民政协会议的召开与《共同纲领》',speak:'1949年9月21日，中国人民政治协商会议第一届全体会议在北平开幕，代表662人。会议通过《共同纲领》，它起临时宪法作用；选举毛泽东为中央人民政府主席；决定北平改名北京、采用公元纪年、以《义勇军进行曲》为代国歌、五星红旗为国旗。毛泽东宣告“中国人从此站立起来了”。',
      quiz:{type:'choice',q:'1949年政协第一届全体会议通过的、在一个时期起临时宪法作用的文件是？',opts:['《中华人民共和国宪法》','《共同纲领》','《论联合政府》','《五四指示》'],a:1,exp:'《共同纲领》是新中国成立初期的根本大法性文件。'}},
    {ch:'c7',title:'中国革命胜利的原因',speak:'中国革命发生和胜利不是偶然的，有深刻社会根源和雄厚群众基础：帝国主义、封建主义、官僚资本主义的残酷压迫使人民走上斗争道路；工人、农民、城市小资产阶级是主要力量；民族资产阶级逐步靠拢；从根本上说，是由于有了中国共产党的领导。',
      quiz:{type:'choice',q:'中国新民主主义革命能够走向胜利，从根本上说是因为？',opts:['国际援助','有了中国共产党的领导','资产阶级领导','没有敌人'],a:1,exp:'没有共产党就没有新中国，是历史经验的科学结论。'}},
    {ch:'c7',title:'中国革命胜利的伟大意义',speak:'中国革命的胜利，结束了百余年来中华民族遭受资本-帝国主义侵略和各族人民受压迫剥削的历史，结束了国家战乱频仍、四分五裂的局面，实现了民族独立和人民解放；为实现由新民主主义到社会主义的转变扫清障碍，并极大改变了世界政治格局。',
      quiz:{type:'fill',q:'中国革命的胜利实现了 ______ 独立和人民解放。',answer:'民族',exp:'革命胜利为实现国家富强、人民幸福开辟了广阔道路。'}},
    {ch:'c7',title:'中国革命胜利的基本经验（三大法宝）',speak:'中国共产党在革命中积累了丰富经验。毛泽东指出：“统一战线，武装斗争，党的建设，是中国共产党在中国革命中战胜敌人的三个法宝。”总结到一点，就是工人阶级（经过共产党）领导的以工农联盟为基础的人民民主专政。',
      quiz:{type:'choice',q:'毛泽东在总结中国革命经验时指出，战胜敌人的三个主要法宝是？',opts:['统一战线、武装斗争、党的建设','土地、劳力、资本','民主、自由、平等','农业、工业、国防'],a:0,exp:'三大法宝是新民主主义革命经验的高度概括。'}},

    /* 大纲补缺：三种建国方案、向北发展向南防御、校场口与下关惨案、三大经济纲领、总路线、土改总路线、二二八与三区革命、将革命进行到底与北平谈判、两个联盟 */
    {ch:'c7',title:'抗战胜利后的三种建国方案与两个中国之命运',speak:'抗战胜利后，中国面临三种建国方案：一是地主买办资产阶级的方案，坚持国民党一党专政和独裁统治；二是民族资产阶级的方案，主张建立资产阶级共和国；三是工人阶级及其政党的方案，建立人民民主专政的共和国。两个中国之命运的较量，实质是中国走什么道路的问题。历史证明资产阶级共和国方案在中国行不通，人民共和国是中国人民的历史性选择。',
      quiz:{type:'choice',q:'抗战胜利后三种建国方案中，被历史证明行不通的是？',opts:['资产阶级共和国方案','人民民主专政方案','新民主主义共和国方案','工人阶级领导的人民共和国方案'],a:0,exp:'资产阶级共和国方案在中国行不通，人民共和国是历史的选择、人民的选择。'}},
    {ch:'c7',title:'“向北发展，向南防御”战略方针',speak:'1945年9月，中共中央确定“向北发展，向南防御”的战略方针：调集大批干部和部队进军东北，争取控制东北；同时在南方作出必要让步，收缩防线。为此成立以彭真为书记的中共中央东北局，先后调派11万部队和2万名干部进入东北，为建立巩固的东北根据地、夺取解放战争胜利创造了重要条件。',
      quiz:{type:'fill',q:'1945年9月中共中央确定的战略方针是“ ______ ，向南防御”。',answer:'向北发展',exp:'“向北发展，向南防御”的核心是争取东北，为解放战争准备战略基地。'}},
    {ch:'c7',title:'校场口惨案与下关惨案',speak:'1946年2月10日，重庆各界在较场口举行庆祝政协成功大会，国民党特务暴徒捣乱会场、打伤郭沫若、李公朴等，制造校场口惨案。同年6月23日，上海人民团体联合会推举马叙伦等赴南京请愿要求停止内战，到达下关车站时遭国民党特务殴打，制造下关惨案。两案暴露了国民党坚持独裁内战的本质，深刻地教育了全国人民。',
      quiz:{type:'choice',q:'1946年2月在重庆发生的、暴露国民党破坏政协协议的惨案是？',opts:['校场口惨案','下关惨案','一二·一惨案','五二〇惨案'],a:0,exp:'校场口惨案发生于1946年2月重庆较场口，暴露了国民党假和平真内战的本质。'}},
    {ch:'c7',title:'新民主主义三大经济纲领',speak:'1947年12月，毛泽东在十二月会议上作《目前形势和我们的任务》报告，提出新民主主义三大经济纲领：没收封建阶级的土地归农民所有；没收蒋介石、宋子文、孔祥熙、陈立夫为首的垄断资本归新民主主义的国家所有；保护民族工商业。这是新民主主义革命经济纲领的完整表述。',
      quiz:{type:'choice',q:'下列不属于新民主主义三大经济纲领的是？',opts:['没收一般民族资本归国家所有','没收封建阶级土地归农民所有','没收官僚垄断资本归国家所有','保护民族工商业'],a:0,exp:'三大经济纲领是“两没收一保护”，保护民族工商业是重要内容，不会没收一般民族资本。'}},
    {ch:'c7',title:'新民主主义革命总路线',speak:'1948年4月，毛泽东在《在晋绥干部会议上的讲话》中完整表述了新民主主义革命总路线：无产阶级领导的，人民大众的，反对帝国主义、封建主义和官僚资本主义的革命。它明确规定了革命的领导力量、革命动力、革命对象和革命性质，是党在民主革命时期的总政策。',
      quiz:{type:'fill',q:'新民主主义革命总路线的领导力量是 ______ 。',answer:'无产阶级',exp:'新民主主义革命由无产阶级领导，这是新旧民主主义革命的根本区别。'}},
    {ch:'c7',title:'土地改革的总路线',speak:'1948年4月，毛泽东提出土地改革的总路线：依靠贫农，团结中农，有步骤地、有分别地消灭封建剥削制度，发展农业生产。这条总路线纠正了土改中“左”的偏差，保证了土地改革运动的健康发展，为解放战争胜利提供了可靠的群众基础和物质保障。',
      quiz:{type:'choice',q:'土地改革总路线规定的阶级政策是？',opts:['依靠贫农，团结中农','依靠中农，团结贫农','依靠富农，中立贫农','只依靠雇农'],a:0,exp:'土地改革总路线的阶级政策是依靠贫农、团结中农，有步骤有分别地消灭封建剥削制度。'}},
    {ch:'c7',title:'台湾人民二二八起义与“三区革命”',speak:'1947年2月28日，台湾人民因国民党专卖局缉私人员殴打烟贩、枪杀市民而举行起义，反抗国民党暴政，遭到残酷镇压，史称二二八起义。1944年秋，新疆伊犁、塔城、阿勒泰三区人民发动反对国民党统治的“三区革命”，1945年成立三区革命政府，1949年接受中国共产党领导。1947年5月1日，内蒙古自治区政府成立，是我国第一个省级民族自治地方。',
      quiz:{type:'fill',q:'1947年台湾人民反抗国民党暴政的武装起义是 ______ 。',answer:'二二八起义',exp:'二二八起义是台湾人民反对国民党独裁统治的正义斗争。'}},
    {ch:'c7',title:'《将革命进行到底》与国共北平谈判',speak:'1948年12月30日，毛泽东发表《将革命进行到底》新年献词，针对美蒋“划江而治”的图谋，号召坚决彻底消灭一切反动势力。1949年4月，国共双方在北平举行和平谈判，达成《国内和平协定（最后修正案）》，国民党政府拒绝签字，和谈破裂，人民解放军随即发起渡江战役。',
      quiz:{type:'choice',q:'1949年4月国共北平谈判达成的文件是？',opts:['《国内和平协定（最后修正案）》','《双十协定》','《共同纲领》','《停战协定》'],a:0,exp:'北平谈判达成《国内和平协定（最后修正案）》，被国民党政府拒绝，和谈破裂。'}},
    {ch:'c7',title:'中国革命统一战线中的两个联盟',speak:'中国革命统一战线包含两个联盟：一是工人阶级同农民阶级、广大知识分子及其他劳动者的联盟，主要是工农联盟，这是统一战线的基础；二是工人阶级同非劳动人民（主要是民族资产阶级和部分大资产阶级）的联盟。两个联盟相辅相成，必须坚持以第一个联盟为基础，才能争取和团结第二个联盟。',
      quiz:{type:'choice',q:'中国革命统一战线的基础是？',opts:['工人阶级同农民阶级的联盟（工农联盟）','同民族资产阶级的联盟','同大资产阶级的联盟','同国际反帝力量的联盟'],a:0,exp:'两个联盟中，工农联盟是基础，是统一战线的主体和支柱。'}},

    /* ============ 第八章 ============ */
    {ch:'c8',title:'中华人民共和国的成立与政权巩固',speak:'新中国成立实现了民族独立和人民解放。随即抗美援朝、土地改革、镇压反革命，巩固了新生人民政权。',
      quiz:{type:'choice',q:'下列哪一举措巩固了新中国政权？',opts:['抗美援朝','全面私有化','取消土改','闭关锁国'],a:0,exp:'抗美援朝、土地改革、镇压反革命巩固了新生人民政权。'}},
    {ch:'c8',title:'过渡时期总路线与社会主义改造',speak:'1953年党提出"一化三改"的过渡时期总路线，到1956年基本完成对农业、手工业、资本主义工商业的社会主义改造。',
      quiz:{type:'fill',q:'1953 年党提出" ______ 三改"的过渡时期总路线。',answer:'一化',exp:'"一化三改"：工业化 + 对农业、手工业、资本主义工商业的社会主义改造。'}},
    {ch:'c8',title:'社会主义基本制度的确立',speak:'三大改造完成，社会主义经济制度确立；人民代表大会制度等政治制度建立，中国进入社会主义初级阶段。',
      quiz:{type:'choice',q:'我国确立社会主义基本制度是在？',opts:['1949 年','1956 年三大改造基本完成后','1978 年','1992 年'],a:1,exp:'1956 年三大改造基本完成，社会主义基本制度确立。'}},
    {ch:'c8',title:'全面建设社会主义的探索与曲折',speak:'1956年后党探索适合国情的建设道路，取得成就，但也经历"大跃进"和"文化大革命"的曲折，留下深刻教训。',
      quiz:{type:'choice',q:'下列属于探索中的曲折的是？',opts:['"一五"计划成就','"大跃进"和"文化大革命"','抗美援朝胜利','三大改造'],a:1,exp:'"大跃进""文革"是探索中的严重曲折，应引为教训。'}},

    /* ---- 第八章第一节（新增，基于教材PDF：中华人民共和国的成立和新生人民政权的巩固） ---- */
    {ch:'c8',title:'开国大典与中华人民共和国成立',speak:'1949年10月1日下午，首都北京30万军民在天安门广场举行开国大典。毛泽东庄严宣告“中华人民共和国中央人民政府今天成立了”，升起五星红旗，54门礼炮齐鸣28响象征党领导人民奋斗28年。10月1日成为中华人民共和国国庆日。',
      quiz:{type:'fill',q:'______ 年 10 月 1 日，开国大典在北京天安门广场举行，中华人民共和国成立。',answer:'1949',exp:'开国大典宣告新中国诞生，中国历史翻开新纪元。'}},
    {ch:'c8',title:'新中国成立的伟大历史意义',speak:'新中国的成立，彻底结束了旧中国半殖民地半封建社会的历史，彻底结束了极少数剥削者统治广大劳动人民的历史，彻底结束了旧中国一盘散沙的局面，彻底废除了列强的不平等条约和一切特权。中国人民从此站起来，成为国家、社会和自己命运的主人。',
      quiz:{type:'choice',q:'下列哪一项是新中国成立的历史意义？',opts:['中国从此陷入分裂','彻底结束了半殖民地半封建社会、中国人民站起来','资本主义制度确立','殖民统治开始'],a:1,exp:'新中国成立实现了民族独立和人民解放，是伟大的历史性胜利。'}},
    {ch:'c8',title:'新中国成立初期的四大考验',speak:'新中国成立伊始面临四大考验：能不能保卫胜利成果、巩固新生政权；能不能战胜严重经济困难、恢复国民经济；能不能巩固民族独立、维护国家主权安全；能不能经受住全国执政的新考验、保持优良作风。',
      quiz:{type:'fill',q:'新中国成立后，中国共产党面临四大考验，其中之一是能不能巩固 ______、维护国家主权和安全。',answer:'民族独立',exp:'面对帝国主义的孤立封锁，新中国把巩固独立与安全摆在突出位置。'}},
    {ch:'c8',title:'完成民主革命遗留任务',speak:'人民政府追剿残余敌人、基本完成大陆统一，摧毁旧政权、召开各界人民代表会议；继续废除封建土地制度，约3亿农民无偿获得约7亿亩土地；制定《婚姻法》废除封建婚姻制度；开展镇压反革命运动，基本肃清国民党遗留反动势力。',
      quiz:{type:'choice',q:'新中国成立初期，约多少无地少地农民在土改中无偿获得土地？',opts:['约3000万','约3亿','约300万','约30亿'],a:1,exp:'土地改革使占人口绝大多数的农民翻了身、获解放。'}},
    {ch:'c8',title:'独立自主的外交方针',speak:'基于二战后两极格局，毛泽东提出“另起炉灶”“打扫干净屋子再请客”“一边倒”的外交方针，从根本上改变旧中国“跪着办外交”的局面。新中国同苏联订立《中苏友好同盟互助条约》，收回外国兵营、海关治权等特权。',
      quiz:{type:'choice',q:'新中国成立初期，毛泽东提出的三大外交方针不包括？',opts:['另起炉灶','打扫干净屋子再请客','一边倒','闭关锁国'],a:3,exp:'三大方针是另起炉灶、打扫干净屋子再请客、一边倒。'}},
    {ch:'c8',title:'抗美援朝 保家卫国',speak:'1950年10月，应朝鲜党和政府请求，中共中央毅然作出抗美援朝、保家卫国的历史性决策，组建以彭德怀为司令员兼政委的中国人民志愿军。19日志愿军跨过鸭绿江。1953年7月27日，美国被迫在停战协定上签字，打破了美军不可战胜的神话。',
      quiz:{type:'fill',q:'______ 年 10 月，中国人民志愿军在彭德怀率领下跨过鸭绿江，抗美援朝、保家卫国。',answer:'1950',exp:'抗美援朝战争捍卫了新中国安全，打出了国威军威。'}},
    {ch:'c8',title:'伟大抗美援朝精神',speak:'在抗美援朝战争中，志愿军始终发扬祖国和人民利益高于一切的爱国主义精神、革命英雄主义精神、革命乐观主义精神、革命忠诚精神和国际主义精神，涌现杨根思、黄继光、邱少云、罗盛教等英雄，被祖国人民称为“最可爱的人”。',
      quiz:{type:'choice',q:'抗美援朝战争中，用胸膛堵住枪眼为战友开道的特级英雄是？',opts:['邱少云','黄继光','杨根思','罗盛教'],a:1,exp:'志愿军将士以“钢少气多”力克“钢多气少”，锻造伟大抗美援朝精神。'}},
    {ch:'c8',title:'恢复国民经济',speak:'新中国成立后全面没收官僚资本归国家所有，确立国营经济领导地位；组织同投机资本的“银元之战”“米棉之战”，到1950年3月物价基本稳定。到1952年底，国民经济全面恢复，工农业总产值超过1936年最高水平20%。',
      quiz:{type:'fill',q:'新中国成立初期，人民政府同投机资本进行“银元之战”和“______ 之战”，稳定了物价。',answer:'米棉',exp:'到1952年底国民经济得到全面恢复，为社会主义改造创造了条件。'}},
    {ch:'c8',title:'教育科学文化卫生除旧布新',speak:'党和政府确立马克思主义在全国的指导地位，1951至1953年出版《毛泽东选集》；对旧教育文化事业改革，1951年底起高校院系调整；成立中国科学院；提出卫生工作“面向工农兵、预防为主、团结中西医”方针，开展爱国卫生运动。',
      quiz:{type:'choice',q:'新中国成立初期，党和政府为发展科研成立了哪一机构作为全国科研中心？',opts:['中国社会科学院','中国科学院','国家科委','中国科协'],a:1,exp:'中科院的成立推动形成了较完整的科研体系。'}},
    {ch:'c8',title:'加强执政党的建设',speak:'执政条件下，中共中央高度重视自身建设，成立中央及各级党的纪律检查委员会；1950至1951年开展整风整党；1951年底至1952年开展反贪污、反浪费、反官僚主义的“三反”运动，处决大贪污犯刘青山、张子善，并开展“五反”运动。',
      quiz:{type:'choice',q:'1951年底至1952年，“三反”运动的内容是？',opts:['反贪污、反浪费、反官僚主义','反行贿、反偷税漏税、反盗窃','反主观、反宗派、反官僚主义','反保守、反冒进'],a:0,exp:'“三反”针对党政机关内部的腐败与作风问题，处决刘青山、张子善。'}},

    /* ---- 第八章第二节（新增，基于教材PDF：党在过渡时期的总路线及其实施） ---- */
    {ch:'c8',title:'过渡时期总路线的提出',speak:'1952年底起中共中央酝酿、1953年正式提出过渡时期总路线：“在一个相当长的时期内，逐步实现国家的社会主义工业化，并逐步实现国家对农业、手工业、资本主义工商业的社会主义改造。”其内容概括为“一化三改”，又称“一体两翼”。',
      quiz:{type:'fill',q:'过渡时期总路线概括为“一化三改”，其中“一化”指国家的社会主义 ______。',answer:'工业化',exp:'“一化”是主体，“三改”是两翼，二者相辅相成。'}},
    {ch:'c8',title:'总路线反映了历史必然性',speak:'总路线符合新中国社会发展实际：社会主义工业化是国家独立富强的首要条件；民族资本主义经济弱小、难以成为工业起飞基础；个体农业的分散经营限制生产力发展，必须走合作化道路；当时只有苏联能援助中国，促使中国选择社会主义。',
      quiz:{type:'choice',q:'提出过渡时期总路线的历史必然性在于？',opts:['资本主义已经很发达','实现工业化、改造私有制是独立富强的必由之路','国际资本大力援助','农业已高度集体化'],a:1,exp:'总路线体现了变革生产关系与发展生产力的统一。'}},
    {ch:'c8',title:'“一五”计划的制定与实施',speak:'为完成工业化主体任务，我国从1951年着手编制第一个五年计划，1953年起有计划的经济建设全面展开。以苏联援助的156项工程为中心，鞍钢大型轧钢厂、无缝钢管厂、七号炼铁炉等于1953年12月开工，工业生产能力大幅前进。',
      quiz:{type:'fill',q:'从 ______ 年起，以苏联援助的156项工程为中心的“一五”计划建设全面展开。',answer:'1953',exp:'“一五”计划集中力量发展重工业，奠定独立工业体系基础。'}},
    {ch:'c8',title:'农业合作化道路',speak:'农业社会主义改造循序渐进：从临时互助组、常年互助组，到土地入股的统一经营初级社，再到土地集体所有的完全社会主义高级社。1953年10月起实行粮食统购统销，1955年7月后形成高潮，1956年底基本完成，96.3%农户加入合作社。',
      quiz:{type:'choice',q:'到1956年底，全国加入农业生产合作社的农户约占？',opts:['50%','70%','高级社达87.8%、合计约96.3%','100%'],a:2,exp:'农业合作化使农村实现从分散个体劳动向集体所有、集体经营的历史性转变。'}},
    {ch:'c8',title:'手工业合作化',speak:'手工业合作化采取积极引导、稳步前进方针，组织形式由手工业生产小组、供销合作社到生产合作社，从供销入手、由小到大、由低到高。农业合作化迅猛发展带动了手工业步伐，1956年底参加合作社人员占全体手工业人员的91.7%，基本完成。',
      quiz:{type:'fill',q:'到1956年底，参加合作社的手工业人员已占全体手工业人员的约 ______%。',answer:'91.7',exp:'手工业合作化与农业、工商业改造同步推进。'}},
    {ch:'c8',title:'资本主义工商业的国家资本主义改造',speak:'对资本主义工商业采取利用、限制、改造方针，通过国家资本主义逐步过渡。初级形式（加工订货、经销代销）实行“四马分肥”；高级形式是个别企业乃至全行业公私合营，利润分配仍“四马分肥”，企业具社会主义性质。',
      quiz:{type:'choice',q:'资本主义工商业改造初级形式下，企业利润分配实行？',opts:['按需分配','四马分肥','定股定息','平均主义'],a:1,exp:'“四马分肥”使资本家剥削受到一定限制。'}},
    {ch:'c8',title:'和平赎买政策的实现',speak:'对资产阶级实行赎买是马克思、恩格斯的设想，中国共产党成功付诸实践。全行业公私合营时核定的私股共24.1864亿元，国家每年发5%定息（定股定息），资本家先后共获32.5亿元，超过原有资产。这是中共的独创性经验。',
      quiz:{type:'fill',q:'全行业公私合营后，国家对资本家原有生产资料实行定股 ______（年息5%）。',answer:'定息',exp:'和平赎买丰富了马克思主义科学社会主义理论。'}},
    {ch:'c8',title:'社会主义改造的成就与缺点',speak:'社会主义改造创造了一系列适合中国特点的由初级到高级逐步过渡的形式，在经济发展、社会稳定、人民群众拥护下完成，成就是伟大的。但后期存在要求过急、工作过粗、改变过快、形式过于简单划一等缺点。',
      quiz:{type:'choice',q:'关于社会主义改造，下列说法正确的是？',opts:['完全失败','在经济稳定发展、人民拥护下完成，成就伟大但也有后期过急过粗等缺点','没有任何缺点','未进行任何改造'],a:1,exp:'改造取得了伟大成就，但也留下了值得总结的经验教训。'}},

    /* ---- 第八章第三节（新增，基于教材PDF：初步确立社会主义基本制度） ---- */
    {ch:'c8',title:'社会主义经济制度的建立',speak:'随着社会主义改造完成，以生产资料公有制、按劳分配和计划经济体制为特征的社会主义经济制度建立起来。到1956年，国营、合作社和公私合营经济合计占国民收入92.9%，生产资料公有制占绝对优势，这是中国进入社会主义社会最主要的标志。',
      quiz:{type:'fill',q:'到1956年，社会主义性质的国营、合作社和公私合营经济合计已占国民收入的约 ______%。',answer:'92.9',exp:'生产资料公有制占绝对优势，标志着社会主义经济制度建立。'}},
    {ch:'c8',title:'按劳分配与计划经济体制',speak:'各尽所能、按劳分配是社会主义原则，1956年国务院通过工资改革决定，建立较统一合理的工资制度。建国后我国逐步形成高度集中的计划经济体制，1954年宪法以根本大法形式规定国家用经济计划指导国民经济发展，计划经济体制成为法定体制。',
      quiz:{type:'choice',q:'我国计划经济体制在哪部法律中被确立为法定经济体制？',opts:['《共同纲领》','1954年宪法','1975年宪法','1982年宪法'],a:1,exp:'1954年宪法规定国家用经济计划指导国民经济的发展和改造。'}},
    {ch:'c8',title:'一届全国人大与1954年宪法',speak:'1954年9月，第一届全国人民代表大会第一次会议在北京召开，通过了《中华人民共和国宪法》。这是我国第一部社会主义类型的宪法，体现人民民主和社会主义原则，规定“一切权力属于人民”，国家机构实行民主集中制，以国家根本法的形式确认了中国共产党领导人民进行社会主义建设的成果。大会选举毛泽东为中华人民共和国主席。',
      quiz:{type:'choice',q:'1954年第一届全国人大一次会议通过的宪法是？',opts:['资本主义类型宪法','社会主义类型的宪法','临时宪法','封建性质宪法'],a:1,exp:'1954年宪法确立人民民主和社会主义原则，是新中国第一部社会主义类型宪法。'}},
    {ch:'c8',title:'人民代表大会制度的确立',speak:'1954年一届人大确立了人民代表大会制度这一根本政治制度：全国人民代表大会是最高国家权力机关，国务院即中央人民政府是最高国家行政机关。这标志着人民管理国家有了最好的组织形式，一切权力属于人民的原则得以实现。',
      quiz:{type:'fill',q:'人民代表大会制度是我国的根本 ______ 制度。',answer:'政治',exp:'人民代表大会制度是实现社会主义民主的基本形式。'}},
    {ch:'c8',title:'多党合作和政治协商制度的发展',speak:'一届人大召开后，政协不再代行全国人大职权。1954年12月政协二届一次会议通过章程，明确人民政协作为团结各族各界的人民民主统一战线组织继续存在，成为中共领导的多党合作和政治协商的重要机构，是我国基本政治制度。',
      quiz:{type:'choice',q:'一届人大后，人民政协的性质变为？',opts:['最高国家权力机关','爱国统一战线的组织、多党合作的重要机构','行政机关','司法机关'],a:1,exp:'政协成为发扬社会主义民主的重要形式。'}},
    {ch:'c8',title:'民族区域自治制度的建立',speak:'民族区域自治是解决我国民族问题的基本政策。《共同纲领》确定实行该制度，1954年宪法将其规范为自治区、自治州、自治县三级。继1947年内蒙古成立后，新疆、广西、宁夏、西藏等自治区先后成立，体现民族平等与团结。',
      quiz:{type:'fill',q:'继1947年内蒙古自治区成立后，西藏自治区于 ______ 年 9 月成立。',answer:'1965',exp:'民族区域自治保障了各少数民族行使自治权，巩固了国家统一。'}},
    {ch:'c8',title:'基层社会管理体系的探索',speak:'建国伊始，农村保甲制度被取缔，农民协会逐步被互助组、合作社取代。1954年12月，一届全国人大常委会通过《城市居民委员会组织条例》，以法律形式确认居委会的名称、性质和组织结构，促进城市居民自治组织的统一规范建立。',
      quiz:{type:'choice',q:'1954年，我国以法律形式规范建立的基层群众自治组织是？',opts:['村民委员会','城市居民委员会','生产大队','人民公社'],a:1,exp:'居委会的建立是基层社会管理体系探索的重要一环。'}},
    {ch:'c8',title:'社会主义基本制度确立的伟大意义',speak:'社会主义基本制度的确立，是中华民族有史以来最为广泛而深刻的社会变革，为当代中国一切发展进步奠定了根本政治前提和制度基础，实现了中华民族由不断衰落到根本扭转命运、持续走向繁荣富强的伟大飞跃。',
      quiz:{type:'choice',q:'社会主义基本制度的确立为当代中国一切发展进步奠定了？',opts:['殖民统治基础','根本政治前提和制度基础','封建制度基础','对外依附基础'],a:1,exp:'只有社会主义才能救中国、才能发展中国。'}},

    /* ---- 第八章第四节（新增，基于教材PDF：全面建设社会主义的良好开端） ---- */
    {ch:'c8',title:'马克思主义同中国实际“第二次结合”',speak:'1956年社会主义改造基本完成，中国进入全面建设社会主义阶段。苏共二十大暴露苏联建设缺点后，毛泽东提出把马克思列宁主义基本原理同中国具体实际“第二次结合”，找出在中国怎样建设社会主义的道路，为探索适合国情的道路提供指导原则。',
      quiz:{type:'fill',q:'1956年，毛泽东提出要把马列主义基本原理同中国具体实际实行“第 ______ 次结合”。',answer:'二',exp:'“第二次结合”是探索中国社会主义建设道路的指导原则。'}},
    {ch:'c8',title:'《论十大关系》',speak:'1956年4月25日，毛泽东在中央政治局扩大会议作《论十大关系》讲话，围绕“调动一切积极因素为社会主义服务”的基本方针，论述重轻农、沿海内地、经济建设国防、国家集体个人、中央地方等经济关系，以及汉族和少数民族、党和非党等政治关系，并提出“长期共存、互相监督”方针。',
      quiz:{type:'choice',q:'毛泽东《论十大关系》提出的基本方针是？',opts:['以阶级斗争为纲','调动一切积极因素为社会主义服务','打倒一切','闭关锁国'],a:1,exp:'《论十大关系》是探索适合中国国情建设道路的重要标志，为八大作理论准备。'}},
    {ch:'c8',title:'“双百”方针与“向现代科学进军”',speak:'1956年1月知识分子问题会议上，周恩来宣布知识分子“已经是工人阶级的一部分”，号召“向现代科学进军”，编制1956—1967科技发展规划。同年党中央确定“百花齐放、百家争鸣”为发展科学文化事业的方针。',
      quiz:{type:'choice',q:'1956年党中央确定的发展科学文化事业的指导方针是？',opts:['百花齐放、百家争鸣','一家独鸣','全盘苏化','文化专制'],a:0,exp:'“双百”方针推动了文学艺术和思想文化事业的繁荣。'}},
    {ch:'c8',title:'中共八大路线的制定',speak:'1956年9月中共八大正确分析国内形势和主要矛盾变化，指出国内主要矛盾已是人民对经济文化迅速发展的需要同当前经济文化不能满足需要的状况之间的矛盾，主要任务是集中力量发展社会生产力。大会坚持综合平衡中稳步前进方针，肯定“三个主体、三个补充”。',
      quiz:{type:'fill',q:'中共八大指出，党和人民的主要任务是集中力量发展 ______。',answer:'社会生产力',exp:'八大提出集中力量发展生产力，是探索的良好开端。'}},
    {ch:'c8',title:'社会主义建设热情高涨',speak:'八大后全国迅速掀起社会主义建设高潮，工厂技术革新成风、农村兴修水利成效显著，“每一秒钟都为创造社会主义社会而劳动”成为建设者的生活节奏。新中国第一个五年计划提前完成，第二个五年计划顺利推进。',
      quiz:{type:'choice',q:'中共八大后，被提前完成的是？',opts:['第一个五年计划','三五计划','四五计划','十一五规划'],a:0,exp:'人民群众建设社会主义的热情高涨，推动了“一五”计划提前完成。'}},
    {ch:'c8',title:'《关于正确处理人民内部矛盾的问题》',speak:'1957年2月，毛泽东在最高国务会议发表《关于正确处理人民内部矛盾的问题》讲话，指出社会主义社会仍存在矛盾，基本矛盾仍是生产力与生产关系、经济基础与上层建筑的矛盾；存在敌我矛盾和人民内部矛盾两类，后者用民主的、说服教育的方法解决。',
      quiz:{type:'choice',q:'毛泽东在《关于正确处理人民内部矛盾的问题》中把社会主义社会矛盾分为？',opts:['只有敌我矛盾','敌我矛盾和人民内部矛盾两类','只有经济矛盾','只有思想矛盾'],a:1,exp:'这一理论丰富发展了科学社会主义，为后来的改革奠定理论基础。'}},
    {ch:'c8',title:'整风运动与反右派斗争',speak:'1957年4月中共中央发出整风指示，反对官僚主义、宗派主义、主观主义，采取开门整风形式听取意见。但在整风中极少数人进攻新制度，党中央组织反击。反右斗争完全必要，却因对形势估计过重而严重扩大化，留下深刻教训。',
      quiz:{type:'fill',q:'1957年整风运动反对官僚主义、宗派主义和 ______ 主义。',answer:'主观',exp:'反右派斗争被严重扩大化，是值得记取的深刻教训。'}},

    /* ---- 第八章第五节（新增，基于教材PDF：社会主义道路的艰辛探索和曲折发展） ---- */
    {ch:'c8',title:'“大跃进”和人民公社化运动',speak:'1958年5月八大二次会议通过“鼓足干劲、力争上游、多快好省地建设社会主义”总路线。会后“大跃进”全面展开，农业“以粮为纲”、工业“以钢为纲”刮起浮夸风；8月中央决议建立人民公社，其“一大二公”实为“一平二调”的“共产风”。',
      quiz:{type:'choice',q:'1958年人民公社化运动中，“一大二公”实际搞的是？',opts:['按劳分配','一平二调的共产风','包产到户','自由市场'],a:1,exp:'“大跃进”和人民公社化忽视了客观经济规律，造成严重的“左”倾错误。'}},
    {ch:'c8',title:'初步纠正“左”倾错误的努力',speak:'从1958年11月第一次郑州会议到1959年7月庐山会议前期，党中央整顿人民公社、调整高指标，初步遏制“共产风”、浮夸风。毛泽东等认识到生产关系要适合生产力性质、要利用价值规律、以农轻重为序综合平衡，使形势有所好转。',
      quiz:{type:'fill',q:'1958年11月起，党中央通过第一次 ______ 会议等努力，初步纠正“左”倾错误。',answer:'郑州',exp:'纠“左”在一定范围内取得成效，但未能根本解决问题。'}},
    {ch:'c8',title:'国民经济调整与“八字方针”',speak:'面对严重困难，1960年11月中央发出农村政策紧急指示信；1961年1月八届九中全会决定对国民经济实行“调整、巩固、充实、提高”的八字方针，国民经济转入调整轨道。毛泽东号召大兴调查研究，起草“农业六十条”纠正平均主义。',
      quiz:{type:'choice',q:'1961年八届九中全会确定的国民经济调整方针是？',opts:['调整、巩固、充实、提高','以钢为纲','大干快上','闭关自守'],a:0,exp:'八字方针使国民经济逐步恢复，到1965年调整任务全面完成。'}},
    {ch:'c8',title:'七千人大会',speak:'1962年一二月间，扩大的中共中央工作会议（七千人大会）在北京召开。刘少奇代表中央总结“大跃进”以来经验教训，毛泽东阐述民主集中制的极端重要性并带头自我批评，强调对社会主义建设规律还认识不足。会议统一全党认识，对战胜困难起了重要作用。',
      quiz:{type:'fill',q:'______ 年一二月间召开的七千人大会，初步总结了“大跃进”的经验教训。',answer:'1962',exp:'七千人大会发扬了党内民主和自我批评精神。'}},
    {ch:'c8',title:'“四个现代化”战略目标的提出',speak:'1964年底，周恩来在三届全国人大一次会议上郑重提出实现“四个现代化”的历史任务：把我国建设成具有现代农业、现代工业、现代国防和现代科学技术的社会主义强国，并确定了分两步走的战略构想。从此“四个现代化”成为共同奋斗目标。',
      quiz:{type:'choice',q:'1964年三届全国人大上提出的历史任务是实现？',opts:['两个务必','四个现代化','一国两制','三个代表'],a:1,exp:'“四个现代化”凝聚和团结了全国各族人民不懈奋斗。'}},
    {ch:'c8',title:'“文化大革命”的发动',speak:'1966年5月中央政治局扩大会议通过“五一六通知”，8月八届十一中全会通过“十六条”，标志“文化大革命”全面发动。运动先表现为红卫兵运动，随后进入“全面夺权”“打倒一切”的混乱局面；谭震林等老帅的“二月逆流”受压制。',
      quiz:{type:'fill',q:'1966年5月，中共中央政治局扩大会议通过发动“文化大革命”的“______ 通知”（五一六通知）。',answer:'五一六',exp:'“文革”是一场由领导者错误发动、被反革命集团利用的内乱。'}},
    {ch:'c8',title:'林彪集团与“四人帮”',speak:'1969年九大使“文革”理论实践系统化；1970至1971年林彪反革命集团阴谋夺权策动政变，客观上宣告其失败。此后江青与王洪文、张春桥、姚文元结成“四人帮”企图篡权。1975年邓小平在毛泽东、周恩来支持下主持整顿，形势明显好转。',
      quiz:{type:'choice',q:'1975年，在毛泽东、周恩来支持下全面主持中央日常工作、大刀阔斧整顿的是？',opts:['华国锋','邓小平','林彪','江青'],a:1,exp:'邓小平后来说“拨乱反正在一九七五年就开始了”。'}},
    {ch:'c8',title:'“文化大革命”的结束',speak:'1976年周恩来、朱德、毛泽东先后逝世。10月6日，华国锋、叶剑英等代表中央政治局对“四人帮”实行隔离审查；10月14日党中央公布粉碎“四人帮”消息。粉碎“四人帮”结束了“文化大革命”，社会秩序得以恢复。',
      quiz:{type:'fill',q:'______ 年 10 月，党中央粉碎“四人帮”，结束了“文化大革命”。',answer:'1976',exp:'粉碎“四人帮”使党和国家工作重新走上健康发展轨道。'}},
    {ch:'c8',title:'“文化大革命”的历史教训',speak:'《关于建国以来党的若干历史问题的决议》指出，“文革”是一场由领导者错误发动、被反革命集团利用、给党国家和人民带来严重灾难的内乱。教训包括：科学对待马列、正确认识主要矛盾、改革完善领导制度、发展民主法制、加强执政党建设。',
      quiz:{type:'choice',q:'《历史决议》认为“文化大革命”的性质是？',opts:['成功的群众运动','由领导者错误发动、被反革命集团利用的内乱','经济改革','外交胜利'],a:1,exp:'历史悲剧决不允许重演，必须健全民主与法制。'}},
    {ch:'c8',title:'全面建设社会主义的成就',speak:'在艰辛探索中，我国建立起独立的比较完整的工业体系和国民经济体系；取得“两弹一星”等尖端成就（原子弹1964、氢弹1967、东方红一号卫星1970）；涌现大庆精神、焦裕禄、红旗渠、雷锋精神；1971年恢复联合国合法席位，1972年尼克松访华打开中美关系大门。',
      quiz:{type:'choice',q:'下列成就中属于全面建设社会主义时期取得的是？',opts:['第一颗原子弹爆炸成功（1964）','香港回归','加入WTO','北京奥运会'],a:0,exp:'“两弹一星”等重大成就增强了综合国力与国际地位。'}},

    /* 大纲补缺：土地改革法、七届三中全会、农业合作化问题、新民主主义社会性质、社会主义教育运动、社会主义发展阶段 */
    {ch:'c8',title:'《中华人民共和国土地改革法》',speak:'1950年6月，中央人民政府颁布《中华人民共和国土地改革法》，规定废除地主阶级封建剥削的土地所有制，实行农民的土地所有制；保存富农经济，保护中农和小土地出租者。到1952年底，除部分少数民族地区外全国土地改革基本完成，3亿多无地少地农民分得土地，彻底废除了封建剥削制度，巩固了工农联盟。',
      quiz:{type:'fill',q:'1950年6月颁布、废除封建土地所有制的法律是《 ______ 》。',answer:'中华人民共和国土地改革法',exp:'《土地改革法》1950年6月颁布，1952年底全国土改基本完成。'}},
    {ch:'c8',title:'中共七届三中全会',speak:'1950年6月，中共七届三中全会在北京召开，毛泽东作《为争取国家财政经济状况的基本好转而斗争》的报告，提出用三年左右时间实现财政经济状况根本好转的三个条件：土地改革的完成、现有工商业的合理调整、国家机构所需经费的大量节减。会议还强调不要四面出击、团结大多数，是建国初期各项工作的总方针。',
      quiz:{type:'choice',q:'七届三中全会提出争取财政经济状况根本好转的三个条件不包括？',opts:['在全国开展大规模社会主义改造','土地改革的完成','现有工商业的合理调整','国家机构所需经费的大量节减'],a:0,exp:'三个条件是土改完成、工商业合理调整、经费大量节减；大规模改造到1953年后才开始。'}},
    {ch:'c8',title:'新民主主义社会的特点与性质',speak:'新中国成立后建立的是新民主主义社会，属于过渡性质的社会。经济上五种经济成分并存：国营经济、合作社经济、个体经济、私人资本主义经济、国家资本主义经济，其中国营经济居领导地位。政治上实行工人阶级领导的、以工农联盟为基础的人民民主专政。主要矛盾是工人阶级同资产阶级的矛盾、社会主义道路同资本主义道路的矛盾。',
      quiz:{type:'choice',q:'新民主主义社会的主要矛盾是？',opts:['工人阶级同资产阶级、社会主义道路同资本主义道路的矛盾','地主阶级同农民阶级的矛盾','帝国主义同中华民族的矛盾','生产力同生产关系的矛盾'],a:0,exp:'新民主主义社会是过渡性质的社会，主要矛盾是工人阶级同资产阶级、社会主义同资本主义两条道路的矛盾。'}},
    {ch:'c8',title:'《关于农业合作化问题》',speak:'1955年7月，毛泽东发表《关于农业合作化问题》的报告，批评“小脚女人”式的右倾保守思想，强调农业合作化必须坚持自愿互利、典型示范、国家帮助，依靠贫下中农，加快合作化进程。此后全国出现农业合作化高潮，到1956年底基本完成。报告推动了改造进程，也助长了要求过急、工作过粗的偏差。',
      quiz:{type:'fill',q:'1955年毛泽东推动农业合作化加速的报告是《 ______ 》。',answer:'关于农业合作化问题',exp:'该报告批评“小脚女人”，推动了农业合作化高潮，也带来要求过急的偏差。'}},
    {ch:'c8',title:'社会主义教育运动',speak:'1963年至1966年，党在部分农村和少数城市基层开展社会主义教育运动。运动最初以清账目、清仓库、清财物、清工分为内容，后发展为清政治、清经济、清组织、清思想，即“四清”运动，并提出运动的重点是整“党内走资本主义道路的当权派”。运动对改进干部作风起了一定作用，但也存在打击面过宽、混淆两类矛盾等问题。',
      quiz:{type:'choice',q:'1963—1966年城乡开展的“四清”运动又称？',opts:['社会主义教育运动','整风运动','反右派斗争','“大跃进”运动'],a:0,exp:'“四清”运动即社会主义教育运动，后期提出重点是整“走资派”，存在扩大化问题。'}},
    {ch:'c8',title:'毛泽东关于社会主义发展阶段的思考',speak:'毛泽东对社会主义发展阶段作了可贵探索：1956年前后提出社会主义可能分为“不发达”和“比较发达”两个阶段；1959年底至1960年初读苏联《政治经济学教科书》时进一步提出，社会主义可分为“不发达的社会主义”和“比较发达的社会主义”两个阶段，后一阶段可能比前一阶段需要更长时间。这一思想是社会主义初级阶段理论的重要思想来源。',
      quiz:{type:'choice',q:'毛泽东提出社会主义可能分为哪两个阶段？',opts:['不发达的社会主义和比较发达的社会主义','社会主义和共产主义','初级阶段和高级阶段','新民主主义和社会主义'],a:0,exp:'“不发达”与“比较发达”两个阶段的设想，是社会主义初级阶段理论的重要思想来源。'}},

    /* ============ 第九章 ============ */
    {ch:'c9',title:'历史性的伟大转折与改革开放起步',speak:'1978年党的十一届三中全会实现伟大转折，把工作中心转移到经济建设，作出改革开放决策，成功开创中国特色社会主义。',
      quiz:{type:'fill',q:'以 ______ 年党的十一届三中全会为标志，中国进入改革开放新时期。',answer:'1978',exp:'1978 年十一届三中全会开启改革开放，开创中国特色社会主义。'}},
    {ch:'c9',title:'改革开放全面展开与中国特色社会主义',speak:'改革开放全面展开，十三大提出社会主义初级阶段理论，邓小平南方谈话推动改革深化，中国特色社会主义充满活力。',
      quiz:{type:'choice',q:'系统阐述社会主义初级阶段理论的会议是？',opts:['党的十二大','党的十三大','党的十五大','党的十七大'],a:1,exp:'党的十三大系统阐述社会主义初级阶段理论与基本路线。'}},
    {ch:'c9',title:'把中国特色社会主义推向21世纪',speak:'十三届四中全会后，党确立社会主义市场经济体制改革目标，香港、澳门回归祖国，把中国特色社会主义全面推向21世纪。',
      quiz:{type:'choice',q:'下列哪一项不属于这一时期的重大成就？',opts:['社会主义市场经济体制改革目标确立','香港、澳门回归祖国','全面建成小康社会','"三个代表"重要思想形成'],a:2,exp:'"全面建成小康社会"主要在 21 世纪后推进，不属当时。'}},
    {ch:'c9',title:'全面建设小康社会与新形势下的发展',speak:'十六大提出全面建设小康社会，完善社会主义市场经济体制，推进"一国两制"实践与党的建设新的伟大工程。',
      quiz:{type:'fill',q:'党的 ______ 大提出全面建设小康社会的宏伟目标。',answer:'十六',exp:'党的十六大提出全面建设小康社会的目标。'}},

    /* ---------- 第九章第一节 历史性的伟大转折和改革开放的起步 ---------- */
    {ch:'c9',title:'在徘徊中前进和“两个凡是”',speak:'粉碎“四人帮”后，党中央清查帮派体系、平反冤假错案、恢复党和国家正常秩序。但当时提出并推行“两个凡是”，即凡是毛主席作出的决策都坚决维护、凡是毛主席的指示都始终不渝地遵循，理论上违背马克思主义基本原理和实事求是的思想路线，实践上给坚持真理、修正错误造成障碍，党和国家工作出现徘徊中前进的局面。',
      quiz:{type:'choice',q:'“两个凡是”的实质是？',opts:['坚持实事求是','继续维护“左”的错误、阻碍拨乱反正','主张改革开放','否定党的领导'],a:1,exp:'“两个凡是”使拨乱反正难以推进，成为思想解放的主要障碍。'}},
    {ch:'c9',title:'邓小平复出与科教领域的拨乱反正',speak:'1977年4月邓小平致信党中央，提出必须世世代代用准确的完整的毛泽东思想指导全党全军全国人民。7月十届三中全会恢复其一切职务。复出后他主动要求分管科学教育，批判“两个估计”，强调“科学技术是生产力”，扭转对知识分子的“左”的政策；1977年底恢复高校统一招生考试，570万人参加高考；1978年3月全国科学大会召开，迎来科学的春天。',
      quiz:{type:'fill',q:'1977年底恢复高等学校统一招生考试，全国有 ______ 万人参加高考。',answer:'570',exp:'恢复高考改变了千万青年的命运，为现代化建设培养了大批人才。'}},
    {ch:'c9',title:'真理标准问题大讨论',speak:'1978年5月10日中央党校《理论动态》刊登《实践是检验真理的唯一标准》，次日《光明日报》以特约评论员名义公开发表，新华社向全国转发。文章提出社会实践是检验真理的唯一标准，不能拿现成公式去限制、宰割无限丰富的实践。邓小平给予有力支持，号召拨乱反正、打破精神枷锁。这场马克思主义思想解放运动成为正本清源、拨乱反正和改革开放的思想先导。',
      quiz:{type:'choice',q:'1978年5月《光明日报》公开发表的文章是？',opts:['《实践是检验真理的唯一标准》','《解放思想，实事求是，团结一致向前看》','《论十大关系》','《坚持四项基本原则》'],a:0,exp:'这篇评论员文章引发了全国性的真理标准问题大讨论。'}},
    {ch:'c9',title:'1978年中央工作会议',speak:'1978年11月10日至12月15日中央工作会议在北京召开。会议原定讨论经济工作，因邓小平提出工作重点转移的建议而首先讨论转移问题。与会者认为不解决指导思想问题就不可能真正实现转移。11月25日中央政治局作出为天安门事件等重大错案平反的决定。12月13日邓小平作《解放思想，实事求是，团结一致向前看》的讲话，成为随后全会的主题报告。',
      quiz:{type:'fill',q:'1978年12月13日，邓小平在中央工作会议闭幕会上作《______，实事求是，团结一致向前看》的讲话。',answer:'解放思想',exp:'这篇讲话是开辟新时期新道路的宣言书。'}},
    {ch:'c9',title:'党的十一届三中全会实现伟大转折',speak:'1978年12月18日至22日十一届三中全会在北京召开。全会彻底否定“两个凡是”，停止使用“以阶级斗争为纲”的口号，决定从1979年1月起把全党工作重心转移到社会主义现代化建设上来，提出改革开放的任务，强调民主制度化、法律化，增选中央领导机构成员并恢复成立中央纪委。全会重新确立马克思主义思想路线、政治路线、组织路线，实现新中国成立以来党的历史上具有深远意义的伟大转折。',
      quiz:{type:'choice',q:'党的十一届三中全会决定从1979年1月起把全党工作重心转移到？',opts:['阶级斗争','社会主义现代化建设','政治运动','文化革命'],a:1,exp:'全会开启了改革开放和社会主义现代化建设新时期。'}},
    {ch:'c9',title:'大规模平反冤假错案与调整社会关系',speak:'三中全会后，党和国家按照实事求是、有错必纠的原则加快平反步伐。1980年2月十一届五中全会为刘少奇彻底平反。到1982年底，全国共纠正300多万名干部的冤假错案，47万多名党员恢复党籍。中央还改正错划右派分子的案件，摘掉地主富农分子帽子，为国民党投诚起义人员落实政策，支持各民主党派恢复活动，重申侨务政策。',
      quiz:{type:'fill',q:'1980年2月，党的十一届五中全会为 ______ 彻底平反。',answer:'刘少奇',exp:'平反冤假错案调动了社会各阶层的积极性，为改革开放奠定社会基础。'}},
    {ch:'c9',title:'坚持四项基本原则',speak:'拨乱反正中，社会上出现否定党的领导、否定社会主义制度、否定毛泽东思想的错误思潮。1979年3月30日邓小平在理论工作务虚会上发表《坚持四项基本原则》的讲话，指出坚持社会主义道路、坚持人民民主专政、坚持共产党的领导、坚持马列主义毛泽东思想是实现四个现代化的根本前提，并提出走出一条中国式的现代化道路。',
      quiz:{type:'choice',q:'下列不属于四项基本原则的是？',opts:['坚持社会主义道路','坚持人民民主专政','坚持共产党的领导','坚持多党轮流执政'],a:3,exp:'四项基本原则是立国之本，保证了改革开放的社会主义方向。'}},
    {ch:'c9',title:'《关于建国以来党的若干历史问题的决议》',speak:'1979年11月起在邓小平主持下起草《决议》，邓小平提出三条指导原则：确立毛泽东的历史地位、坚持和发展毛泽东思想是最核心的一条；对建国30年大事实事求是分析；总结宜粗不宜细。1981年6月十一届六中全会通过《决议》，彻底否定“文化大革命”，指出毛泽东功绩是第一位的、错误是第二位的，概括毛泽东思想活的灵魂是实事求是、群众路线、独立自主，并明确新时期主要矛盾。这标志着党在指导思想上拨乱反正的胜利完成，是党的第二个历史决议。',
      quiz:{type:'fill',q:'1981年6月党的十一届六中全会通过历史决议，标志着党在 ______ 上的拨乱反正胜利完成。',answer:'指导思想',exp:'决议正确解决了评价毛泽东和确立现代化建设道路两个重大历史课题。'}},
    {ch:'c9',title:'国民经济“调整、改革、整顿、提高”方针',speak:'针对1977至1978年国民经济比例失调，1979年4月中央工作会议提出对国民经济实行“调整、改革、整顿、提高”的方针。邓小平强调中国实现四个现代化有两个重要特点必须看到：一个是底子薄，一个是人口多、耕地少。经过两年努力，主要比例关系趋于合理，1981年12月五届全国人大四次会议宣布调整任务胜利完成。',
      quiz:{type:'choice',q:'1979年4月中央工作会议提出的国民经济方针是？',opts:['调整、改革、整顿、提高','多快好省','抓革命促生产','以钢为纲'],a:0,exp:'八字方针纠正了此前经济工作中的失误。'}},
    {ch:'c9',title:'农村改革率先突破与家庭联产承包责任制',speak:'1978年全国还有2.5亿人口温饱问题没有解决。安徽遭遇严重旱灾后把部分土地借给农民谁种谁收，凤阳县梨园公社小岗生产队18户农民创造包干到户，即“保证国家的，留足集体的，剩下都是自己的”。1980年5月邓小平肯定包产到户，9月中央印发文件肯定在生产队领导下实行包产到户，1982年一号文件明确各种责任制都是社会主义集体经济的生产责任制，家庭联产承包责任制迅速推广。',
      quiz:{type:'fill',q:'1978年，安徽凤阳县小岗生产队18户农民创造了 ______ 到户的做法。',answer:'包干',exp:'农村改革是中国农民的伟大创造，首先在农村取得突破不是偶然的。'}},
    {ch:'c9',title:'城市经济体制改革起步',speak:'1979年5月首都钢铁公司等8家大型企业开始扩大企业自主权试点，到1980年6月增至6600个，在传统计划经济体制上打开一个缺口。城市改革逐步推向经济责任制，1981年春在山东企业试行后推广到全国3.6万个工业企业。商业流通体制改革展开，放宽农副产品购销政策。所有制结构改革开始进行，为解决知青返城就业压力，支持城镇集体经济和个体经济发展，“个体户”应运而生。',
      quiz:{type:'choice',q:'城市经济体制改革最初以什么为主要内容？',opts:['扩大企业自主权','全面私有化','价格闯关','住房制度改革'],a:0,exp:'扩大企业自主权增强了企业的自主经营意识和市场意识。'}},
    {ch:'c9',title:'对外开放起步与兴办经济特区',speak:'1979年中国国际信托投资公司成立，1980年我国恢复在世界银行、国际货币基金组织的代表权，同年《中外合资经营企业法》出台。兴办经济特区是伟大创举：1979年1月广东提出在蛇口一带设立工业区，4月习仲勋提出允许在深圳、珠海、汕头举办出口加工区，邓小平明确说“还是叫特区好”。1980年8月五届全国人大常委会批准在深圳、珠海、汕头、厦门设置经济特区。',
      quiz:{type:'choice',q:'1980年批准设置的经济特区不包括？',opts:['深圳','珠海','汕头','上海浦东'],a:3,exp:'浦东是1990年才开发开放的，不属于首批经济特区。'}},
    {ch:'c9',title:'政治体制改革的启动',speak:'三中全会后，以改革党和国家领导制度、使民主制度化法律化为主要内容的政治体制改革起步。1979年7月五届全国人大二次会议通过地方组织法、选举法、刑法、刑事诉讼法等七部法律。多党合作和政治协商制度恢复发展，邓小平强调“长期共存，互相监督”是长期不变的方针。1980年2月恢复设立中央书记处，8月邓小平作《党和国家领导制度的改革》讲话。1982年机构改革，国务院部委由100个调整为61个。',
      quiz:{type:'fill',q:'1980年8月邓小平作《党和国家领导制度的改革》讲话，指出领导制度、组织制度问题更带有根本性、全局性、______和长期性。',answer:'稳定性',exp:'这一讲话为党和国家领导制度改革明确了基本指导思想。'}},

    /* ---------- 第九章第二节 改革开放和社会主义现代化建设新局面 ---------- */
    {ch:'c9',title:'党的十二大与“建设有中国特色的社会主义”命题',speak:'1982年9月党的十二大在北京举行。邓小平在开幕词中提出“把马克思主义的普遍真理同我国的具体实际结合起来，走自己的道路，建设有中国特色的社会主义”。这一重大命题回答了进入新时期后走什么样的道路的问题，成为指引改革开放和社会主义现代化建设的伟大旗帜。大会提出党在新时期的总任务，并明确努力建设高度的社会主义精神文明和高度的社会主义民主的战略方针。',
      quiz:{type:'choice',q:'“建设有中国特色的社会主义”这一命题是在党的哪次大会上提出的？',opts:['十一届三中全会','十二大','十三大','十四大'],a:1,exp:'十二大开幕词中的这一命题成为指引改革开放的伟大旗帜。'}},
    {ch:'c9',title:'“翻两番”小康目标与1982年宪法',speak:'十二大提出从1981年到20世纪末力争工农业年总产值翻两番，由1980年的7100亿元增加到2000年的2.8万亿元左右，人民生活达到小康水平；战略部署上分前十年打基础、积蓄力量，后十年进入新的经济振兴时期。把20世纪末奋斗目标由实现四个现代化改为实现小康，从战略指导上解决了长期存在的急于求成问题。1982年12月五届全国人大五次会议通过新宪法，以1954年宪法为基础。',
      quiz:{type:'fill',q:'党的十二大提出到20世纪末力争工农业年总产值翻 ______ 番，人民生活达到小康水平。',answer:'两',exp:'这一调整是党中央总结历史经验作出的历史性决策。'}},
    {ch:'c9',title:'人民公社体制终结与乡镇企业异军突起',speak:'1982至1984年党中央连续发出农村工作“一号文件”，稳定完善家庭联产承包责任制。到1987年全国98%的农户实行了这一制度，从根本上动摇了“三级所有、队为基础”和“政社合一”的人民公社体制。1982年宪法规定设立乡政府、普遍成立村民委员会，到1984年底全国基本完成政社分开。1985年一号文件改革农产品统购派购制度。乡镇企业异军突起，1987年产值第一次超过农业总产值。',
      quiz:{type:'choice',q:'1987年我国农村经济的历史性变化是？',opts:['粮食产量翻番','乡镇企业产值第一次超过农业总产值','重新建立人民公社','全面取消农业税'],a:1,exp:'乡镇企业的发展为农村富余劳动力转移开辟了新途径。'}},
    {ch:'c9',title:'十二届三中全会《关于经济体制改革的决定》',speak:'1984年10月十二届三中全会通过《中共中央关于经济体制改革的决定》，突破把计划经济同商品经济对立起来的观点，指出我国社会主义经济是在公有制基础上的有计划的商品经济；突破把全民所有同国家机构直接经营企业混为一谈的传统观念，提出所有权同经营权是可以适当分开的。会后经济体制改革以城市为重点全面展开，中心环节是增强全民所有制企业的活力，推行承包经营责任制。',
      quiz:{type:'choice',q:'1984年十二届三中全会提出的重要论断是？',opts:['我国社会主义经济是有计划的商品经济','立即实行社会主义市场经济','坚持以阶级斗争为纲','全面推行私有化'],a:0,exp:'这是党中央在计划与市场关系问题上取得的新认识。'}},
    {ch:'c9',title:'科技教育体制改革与“863”计划',speak:'1985年3月中央作出《关于科学技术体制改革的决定》，提出经济建设必须依靠科学技术、科学技术工作必须面向经济建设的战略方针；1986年11月我国决定实施发展高科技的“863”计划。1985年5月中央作出《关于教育体制改革的决定》，提出根本目的是提高民族素质、多出人才出好人才，要求有计划分步骤实施九年义务教育；1986年4月六届全国人大四次会议通过《义务教育法》。',
      quiz:{type:'fill',q:'1986年11月，我国决定实施发展高科技的“______”计划。',answer:'863',exp:'“863”计划推动了我国高技术研究的发展。'}},
    {ch:'c9',title:'对外开放基本国策与多层次开放格局',speak:'1984年初邓小平视察深圳、珠海、厦门后指出，特区是技术的窗口、管理的窗口、知识的窗口，也是对外政策的窗口。5月中央决定进一步开放天津、上海、大连等14个沿海港口城市。1985年2月中央决定在长江三角洲、珠江三角洲和闽南厦漳泉三角地区开辟沿海经济开放区，逐步形成经济特区到沿海开放城市再到沿海经济开放区多层次、有重点、点面结合的对外开放新格局。',
      quiz:{type:'choice',q:'1984年进一步开放的沿海港口城市共有多少个？',opts:['10个','14个','18个','24个'],a:1,exp:'14个沿海港口城市的开放扩大了对外开放的前沿地带。'}},
    {ch:'c9',title:'《关于党内政治生活的若干准则》与干部队伍“四化”',speak:'1980年2月十一届五中全会通过《关于党内政治生活的若干准则》，把党章规定和民主集中制原则具体化，提出12个方面要求。陈云尖锐指出“执政党的党风问题是有关党的生死存亡的问题”。为解决干部队伍老化，1982年2月中央作出《关于建立老干部退休制度的决定》，同年9月十二大把实现干部队伍革命化、年轻化、知识化、专业化写入党章。',
      quiz:{type:'fill',q:'党的十二大把实现干部队伍革命化、年轻化、知识化、______写入党章。',answer:'专业化',exp:'干部“四化”推动了新老交替和干部队伍结构改善。'}},
    {ch:'c9',title:'全面整党与社会主义精神文明建设',speak:'1983年10月十二届二中全会作出整党决定，任务是统一思想、整顿作风、加强纪律、纯洁组织，到1987年5月基本结束。1986年9月十二届六中全会通过《关于社会主义精神文明建设指导方针的决议》，提出以经济建设为中心，坚定不移进行经济体制改革、政治体制改革和精神文明建设，根本任务是培养有理想、有道德、有文化、有纪律的社会主义公民。这是党的第一个关于精神文明建设的纲领性文件。',
      quiz:{type:'choice',q:'社会主义精神文明建设的根本任务是？',opts:['培养“四有”社会主义公民','优先发展重工业','扩大对外开放','精简政府机构'],a:0,exp:'“四有”即有理想、有道德、有文化、有纪律。'}},
    {ch:'c9',title:'党的十三大与社会主义初级阶段理论',speak:'1987年10月党的十三大举行。大会系统阐述社会主义初级阶段理论，指出这个论断包括两层含义：我国社会已经是社会主义社会，必须坚持而不能离开社会主义；我国的社会主义社会还处在初级阶段，必须从这个实际出发而不能超越这个阶段。大会概括党在社会主义初级阶段的基本路线，主要内容是“一个中心、两个基本点”。以经济建设为中心是兴国之要，四项基本原则是立国之本，改革开放是强国之路。',
      quiz:{type:'fill',q:'党在社会主义初级阶段的基本路线，主要内容是“一个中心、______个基本点”。',answer:'两',exp:'基本路线是党和国家的生命线、人民的幸福线。'}},
    {ch:'c9',title:'“三步走”发展战略',speak:'1979年12月邓小平会见日本首相大平正芳时提出“小康之家”的概念。1987年4月他会见西班牙外宾时明确提出“三步走”现代化战略设想，并在党的十三大上得到确认：第一步实现国民生产总值比1980年翻一番，解决人民温饱问题；第二步到20世纪末使国民生产总值再增长一倍，人民生活达到小康水平；第三步到21世纪中叶人均国民生产总值达到中等发达国家水平，基本实现现代化。',
      quiz:{type:'choice',q:'“三步走”战略的第三步目标是？',opts:['解决人民温饱问题','人民生活达到小康水平','到21世纪中叶基本实现现代化','建成共产主义社会'],a:2,exp:'“三步走”战略对中国未来几十年的发展具有深远影响。'}},
    {ch:'c9',title:'治理整顿方针与1988年经济波动',speak:'1984至1988年我国国内生产总值年均增长12.1%，但也出现通货膨胀加剧、总量不平衡、结构不合理等问题。1988年夏准备进行“价格闯关”，消息传开后引发高通胀预期和抢购商品风潮。1988年9月十三届三中全会提出治理经济环境、整顿经济秩序、全面深化改革的方针。同年4月七届全国人大一次会议通过《全民所有制工业企业法》，确认私营经济的法律地位。',
      quiz:{type:'fill',q:'1988年9月党的十三届三中全会提出治理经济环境、整顿经济秩序、全面深化______的方针。',answer:'改革',exp:'治理整顿使过旺的社会需求得到相当程度的控制。'}},
    {ch:'c9',title:'国防战略转变与百万大裁军',speak:'三中全会后，军事战略方针由“积极防御、诱敌深入”改为“积极防御”。1981年9月邓小平明确提出建设强大的现代化、正规化革命军队的总目标。1985年五六月间中央军委扩大会议提出军队建设指导思想实行战略性重大转变，把军队工作从立足于“早打、大打、打核战争”的临战准备状态转入和平时期建设轨道，决定减少军队员额100万。1988年开始实行新的军衔制度，建立文职干部制度。',
      quiz:{type:'choice',q:'1985年中央军委扩大会议决定裁减军队员额？',opts:['50万','100万','150万','200万'],a:1,exp:'百万大裁军是国防和军队建设指导思想的战略性转变。'}},
    {ch:'c9',title:'“一国两制”科学构想与中英中葡谈判',speak:'1979年元旦全国人大常委会发表《告台湾同胞书》，宣示争取祖国和平统一的大政方针。1981年9月叶剑英就台湾回归祖国提出九条方针。1982年1月邓小平首次提出“一个国家，两种制度”的概念。1982年9月邓小平会见撒切尔夫人时明确表示主权问题不是一个可以讨论的问题。1984年12月中英签署联合声明，确认1997年7月1日对香港恢复行使主权；1987年4月中葡签署联合声明，确认1999年12月20日对澳门恢复行使主权。',
      quiz:{type:'fill',q:'1984年12月中英两国政府签署联合声明，确认中国政府于______年7月1日对香港恢复行使主权。',answer:'1997',exp:'“一国两制”构想首先被运用于解决港澳回归问题。'}},
    {ch:'c9',title:'外交方针政策的重大调整',speak:'三中全会前夕中国外交采取两个重大举措：1978年8月同日本签订和平友好条约，同年12月同美国发表正式建交的联合公报。此后实行两个重大转变：一是改变战争不可避免而且迫在眉睫的观点，1985年3月邓小平明确提出“和平和发展是当代世界的两大问题”；二是改变过去联美抗苏的“一条线”战略。中国坚持独立自主的和平外交政策，决不依附于任何一个超级大国。1989年5月中苏关系实现正常化。',
      quiz:{type:'choice',q:'1985年邓小平提出的当代世界两大问题是？',opts:['战争与革命','和平与发展','合作与竞争','改革与开放'],a:1,exp:'这一论断为新时期制定对外政策提供了重要依据。'}},
    {ch:'c9',title:'1989年政治风波与十三届四中全会',speak:'1989年春夏之交北京和其他一些城市发生政治风波，党和政府采取果断措施一举平息了北京地区的反革命暴乱。6月9日邓小平接见首都戒严部队军以上干部，指出这场风波迟早要来，强调十一届三中全会制定的路线方针政策没有错、十三大概括的“一个中心、两个基本点”的基本路线没有错。6月党的十三届四中全会召开，撤销赵紫阳党内一切领导职务，选举江泽民为中央委员会总书记。',
      quiz:{type:'fill',q:'1989年6月，党的十三届四中全会选举______为中共中央委员会总书记。',answer:'江泽民',exp:'十三届四中全会对稳定全国局势、保证路线延续性产生深远影响。'}},
    {ch:'c9',title:'邓小平南方谈话',speak:'1992年1月18日至2月21日，邓小平先后视察武昌、深圳、珠海、上海等地并发表重要谈话。他强调革命是解放生产力、改革也是解放生产力；提出判断姓“社”姓“资”的标准主要看是否有利于发展社会主义社会的生产力、增强社会主义国家的综合国力、提高人民的生活水平；指出计划多一点还是市场多一点不是社会主义与资本主义的本质区别，计划和市场都是经济手段；强调发展才是硬道理。南方谈话是把改革开放推向新阶段的又一个解放思想、实事求是的宣言书。',
      quiz:{type:'choice',q:'邓小平南方谈话提出的“三个有利于”标准不包括？',opts:['是否有利于发展社会主义社会的生产力','是否有利于增强社会主义国家的综合国力','是否有利于提高人民的生活水平','是否有利于扩大出口创汇'],a:3,exp:'南方谈话从理论上回答了长期困扰人们思想的重大问题。'}},

    /* ---------- 第九章第三节 把中国特色社会主义推向21世纪 ---------- */
    {ch:'c9',title:'第三代中央领导集体的形成',speak:'邓小平多次表示，新的领导班子一经建立威信就坚决退出中央领导岗位，强调任何一个领导集体都要有一个核心，没有核心的领导是靠不住的。1989年9月他正式提出辞去中共中央军委主席职务的请求，11月十三届五中全会同意其请求，决定江泽民任中央军委主席。经过十三届四中、五中全会，形成了以江泽民同志为核心的党的第三代中央领导集体，中央领导集体顺利实现新老交替。',
      quiz:{type:'fill',q:'经过党的十三届四中、五中全会，形成了以______同志为核心的党的第三代中央领导集体。',answer:'江泽民',exp:'新老交替保证了党的政策的稳定性和连续性。'}},
    {ch:'c9',title:'应对国际风云变幻与打破“制裁”',speak:'政治风波后以美国为首的西方国家对华实施“制裁”，随后苏联解体、东欧剧变。邓小平反复强调关键是要搞好自己的事情，要泰然处之，维护独立自主、不信邪、不怕鬼的形象。党和政府确定外交工作两个重点：开展睦邻外交、加强同发展中国家团结合作；打破西方“制裁”、恢复和稳定同发达国家关系。日本率先于1990年取消对华“制裁”，到1991年底中国同大多数西方国家关系基本回到正常轨道。',
      quiz:{type:'choice',q:'政治风波后率先取消对华“制裁”的西方国家是？',opts:['美国','日本','英国','法国'],a:1,exp:'中国有效应对了政治风波后的种种外部挑战。'}},
    {ch:'c9',title:'治理整顿完成与开发开放浦东',speak:'1989年11月十三届五中全会通过《关于进一步治理整顿和深化改革的决定》。经过治理整顿，过热的经济明显降温，通货膨胀得到有效控制，1992年3月七届全国人大五次会议宣布治理整顿的主要任务基本完成。1990年4月党中央、国务院批准开发开放浦东；12月上海证券交易所正式开业，是改革开放以来在大陆开业的第一家证券交易所；1991年7月深圳证券交易所开业。',
      quiz:{type:'fill',q:'1990年12月开业的______证券交易所，是改革开放以来大陆开业的第一家证券交易所。',answer:'上海',exp:'浦东开发和证券交易所开业向世界发出坚持改革开放的强烈信号。'}},
    {ch:'c9',title:'党的十四大与社会主义市场经济体制改革目标',speak:'1992年10月党的十四大举行，作出三项具有深远意义的决策：抓住机遇、加快发展，把90年代经济增长速度由原定6%调整为8%至9%；确定我国经济体制改革的目标是建立社会主义市场经济体制，使市场在社会主义国家宏观调控下对资源配置起基础性作用；提出用邓小平建设有中国特色社会主义理论武装全党的任务。以南方谈话和十四大为标志，改革开放进入从计划经济体制向社会主义市场经济体制转变的新阶段。',
      quiz:{type:'choice',q:'党的十四大确定的经济体制改革目标是？',opts:['建立计划经济体制','建立社会主义市场经济体制','建立有计划的商品经济','实行家庭联产承包'],a:1,exp:'把社会主义基本制度与市场经济结合起来是重大突破。'}},
    {ch:'c9',title:'十四届三中全会与市场经济体制基本框架',speak:'1993年11月十四届三中全会通过《中共中央关于建立社会主义市场经济体制若干问题的决定》，把十四大提出的改革目标和基本原则具体化，勾画了基本框架：在坚持以公有制为主体、多种经济成分共同发展的基础上，建立现代企业制度、全国统一开放的市场体系、完善的宏观调控体系、合理的收入分配制度和多层次的社会保障制度。',
      quiz:{type:'fill',q:'1993年11月党的十四届三中全会勾画了社会主义市场经济体制的______框架。',answer:'基本',exp:'经济体制改革开始向着建立市场经济体制的目标整体推进。'}},
    {ch:'c9',title:'国有企业改革与“软着陆”',speak:'国有企业改革是建立社会主义市场经济体制的中心环节。从1994年起按照建立现代企业制度的总体思路推进，选择100家国有大中型企业试点，全国各地先后选择2700多家国有企业进行公司制、股份制改革试点。针对固定资产投资过猛、房地产热、金融秩序混乱等问题，1993年6月中央提出以紧缩银根、整顿金融秩序为重点的16条措施，经3年努力实现“高增长、低通胀”的“软着陆”。',
      quiz:{type:'choice',q:'20世纪90年代宏观调控实现的“软着陆”是指？',opts:['从经济过热通胀转为高增长低通胀','经济陷入全面停滞','物价持续大幅上涨','取消计划经济体制'],a:0,exp:'“软着陆”避免了经济发展的大起大落。'}},
    {ch:'c9',title:'精神文明建设与民主法制建设',speak:'20世纪90年代党中央坚持“两手抓，两手都要硬”。从1991年起精神文明建设“五个一工程”奖评选活动开始实施。1996年10月十四届六中全会作出《关于加强社会主义精神文明建设若干重要问题的决议》，强调以科学的理论武装人、以正确的舆论引导人、以高尚的精神塑造人、以优秀的作品鼓舞人。1993至1997年全国人大及其常委会制定出台近百部法律，多数是社会主义市场经济方面的立法。',
      quiz:{type:'fill',q:'1996年10月，党的十四届六中全会作出加强社会主义______建设若干重要问题的决议。',answer:'精神文明',exp:'决议对新形势下的精神文明建设作出具体部署和规划。'}},
    {ch:'c9',title:'党的十五大与邓小平理论指导地位',speak:'1997年2月邓小平逝世。同年9月党的十五大举行，大会主题是高举邓小平理论伟大旗帜，把建设有中国特色社会主义事业全面推向21世纪。大会首次使用“邓小平理论”这个概念，把这一理论同马克思列宁主义、毛泽东思想一道确立为党的指导思想并写入党章，指出邓小平理论是当代中国的马克思主义，是中国特色社会主义理论体系的开篇之作。',
      quiz:{type:'choice',q:'首次使用“邓小平理论”概念并确立为党的指导思想的是？',opts:['党的十三大','党的十四大','党的十五大','党的十六大'],a:2,exp:'十五大在世纪之交的关键时刻承前启后、继往开来。'}},
    {ch:'c9',title:'社会主义初级阶段基本纲领与新“三步走”战略',speak:'十五大提出党在社会主义初级阶段的基本纲领，明确公有制为主体、多种所有制经济共同发展是基本经济制度；指出公有制实现形式可以而且应当多样化，非公有制经济是社会主义市场经济的重要组成部分；提出依法治国是党领导人民治理国家的基本方略。大会还提出新的“三步走”战略：21世纪第一个十年国民生产总值比2000年翻一番，到建党一百年时使国民经济更加发展、各项制度更加完善，到建国一百年时基本实现现代化。',
      quiz:{type:'fill',q:'党的十五大提出______是党领导人民治理国家的基本方略。',answer:'依法治国',exp:'这是党在探索什么是社会主义、怎样建设社会主义上的认识深化。'}},
    {ch:'c9',title:'国有企业改革攻坚与再就业保障',speak:'十五大后国有企业改革攻坚全面展开，按照鼓励兼并、规范破产、下岗分流、减员增效和实施再就业工程的思路，以纺织行业为突破口，通过债转股、国家技改专项资金、政策性关闭破产等举措打响三年脱困攻坚战，到2000年末国有大中型企业改革和脱困三年目标基本实现。1996年上海率先创建再就业服务中心，各级政府为下岗职工建立基本生活保障、失业保险、城市居民最低生活保障三条保障线。',
      quiz:{type:'choice',q:'为下岗职工建立的三条保障线不包括？',opts:['基本生活保障','失业保险','城市居民最低生活保障','住房公积金'],a:3,exp:'三条保障线在很大程度上消解了国企改革的困难和风险。'}},
    {ch:'c9',title:'加入世界贸易组织',speak:'1986年7月中国政府申请恢复关贸总协定缔约国地位。1995年世界贸易组织成立后，中国开始与成员国逐一进行双边谈判。党中央明确三项原则：中国加入世贸组织是中国经济发展和改革开放的需要，世贸组织也需要中国；中国只能以发展中国家的条件加入；权利和义务一定要平衡。2001年12月中国正式成为世贸组织第143个成员，在全球化进程中获得参与制定规则和竞争的有利位置，对外开放进入新阶段。',
      quiz:{type:'fill',q:'______年12月，中国正式成为世界贸易组织成员。',answer:'2001',exp:'加入世贸组织对推动经济体制改革和现代化建设产生深刻影响。'}},
    {ch:'c9',title:'科教兴国与可持续发展战略',speak:'1995年5月党中央确定实施科教兴国战略，坚持教育为本，把科技和教育摆在经济、社会发展的重要位置；在继续实施“863”计划的同时，1997年组织实施《国家重点基础研究发展计划》即“973”计划；1995年、1999年先后启动“211工程”和“985工程”。1992年联合国环境与发展大会后，我国明确提出实施可持续发展战略，1994年发表《中国21世纪议程》，坚持计划生育和环境保护的基本国策。',
      quiz:{type:'choice',q:'1995年党中央确定的重大战略是？',opts:['科教兴国战略','西部大开发战略','“走出去”战略','人才强国战略'],a:0,exp:'科教兴国战略把经济建设转移到依靠科技进步和提高劳动者素质的轨道。'}},
    {ch:'c9',title:'西部大开发与“走出去”战略',speak:'1999年9月十五届四中全会作出实施西部大开发战略的决定，2000年10月十五届五中全会部署全面启动，政策适用范围包括四川、云南、贵州、西藏、重庆、陕西、甘肃、青海、新疆、宁夏、内蒙古、广西12个省区市，青藏铁路、西气东输、西电东送等重点工程相继开工。1997年12月江泽民提出“引进来”和“走出去”是对外开放基本国策两个紧密联系、相互促进的方面，2000年10月十五届五中全会提出实施“走出去”战略。',
      quiz:{type:'fill',q:'1999年9月，党的十五届四中全会作出实施______大开发战略的决定。',answer:'西部',exp:'西部大开发对推动区域协调发展和实现共同富裕意义重大。'}},
    {ch:'c9',title:'中国特色军事变革',speak:'20世纪90年代党中央和中央军委提出“政治合格、军事过硬、作风优良、纪律严明、保障有力”的新时期军队建设总要求。1995年12月中央军委扩大会议明确提出科技强军战略和“两个根本性转变”：军事斗争准备上由准备应付一般条件下局部战争向准备打赢现代技术特别是高技术条件下局部战争转变；军队建设上由数量规模型向质量效能型、由人力密集型向科技密集型转变。在裁减员额100万基础上再裁减50万。',
      quiz:{type:'choice',q:'1995年中央军委扩大会议提出的军队建设“两个根本性转变”不包括？',opts:['数量规模型向质量效能型转变','人力密集型向科技密集型转变','准备打赢高技术条件下局部战争','实行雇佣兵制度'],a:3,exp:'中国特色军事变革着眼于打得赢、不变质。'}},
    {ch:'c9',title:'全方位多层次对外关系新格局',speak:'20世纪90年代我国提出发展以不结盟、不对抗、不针对第三方为主要特征的新型大国关系，分别同俄罗斯、美国、法国、英国、日本及欧盟建立发展面向21世纪双边关系的基本框架。中国倡导并推动建立“中国—东盟自由贸易区”，建立“上海合作组织”，倡导互信、互利、平等、协商、尊重多样文明、谋求共同发展的“上海精神”。2000年举办中非合作论坛北京部长级会议，2001年博鳌亚洲论坛成立，同年上海成功举办亚太经合组织第九次领导人非正式会议。',
      quiz:{type:'choice',q:'第一个由中国参与推动建立并以中国城市命名的地区性合作组织是？',opts:['上海合作组织','博鳌亚洲论坛','亚太经合组织','中国—东盟自由贸易区'],a:0,exp:'“上海精神”在当代国际关系中产生了重要影响。'}},
    {ch:'c9',title:'香港、澳门回归祖国',speak:'1997年6月30日午夜至7月1日凌晨，中英两国政府举行香港政权交接仪式，宣告中国政府对香港恢复行使主权，香港特别行政区正式成立。1999年12月20日澳门回归祖国，澳门特别行政区正式成立。港澳回归使“一国两制”从科学构想变为现实，标志着祖国统一大业向前迈出重要一步。港澳作为直辖于中央政府的特别行政区重新纳入国家治理体系，在亚洲金融危机冲击下保持了经济社会的稳定与繁荣。',
      quiz:{type:'fill',q:'______年7月1日，中国政府对香港恢复行使主权。',answer:'1997',exp:'“一国两制”是解决历史遗留港澳问题的最佳方案。'}},
    {ch:'c9',title:'海峡两岸交流与反“台独”斗争',speak:'1992年11月海协会与台湾海基会就坚持一个中国原则的表达达成共识，后被称为“九二共识”。1993年4月汪道涵与辜振甫在新加坡举行会谈，签署《汪辜会谈共同协议》等四项协议，建立两岸制度化联系与协商机制。1995年1月江泽民发表讲话提出发展两岸关系、推进祖国和平统一的八项主张。针对李登辉访美、抛出“两国论”和陈水扁否认“九二共识”，党和政府从政治、军事、外交、舆论等方面开展斗争。',
      quiz:{type:'fill',q:'1992年11月海协会与台湾海基会达成的共识，后被称为“______共识”。',answer:'九二',exp:'坚持一个中国原则是实现和平统一的基础和前提。'}},
    {ch:'c9',title:'党的建设新的伟大工程与“三个代表”重要思想',speak:'1994年9月十四届四中全会把新时期党的建设提到“新的伟大工程”的高度。2000年1月江泽民强调治国必先治党、治党务必从严，提出解决好提高领导水平和执政水平、增强拒腐防变和抵御风险能力两大历史性课题。1998年11月至2000年底全党开展“讲学习、讲政治、讲正气”的“三讲”教育。2000年2月江泽民在广东考察时明确提出“三个代表”要求，2001年7月1日系统阐述，指出始终做到“三个代表”是党的立党之本、执政之基、力量之源。',
      quiz:{type:'choice',q:'“三个代表”重要思想的内容不包括？',opts:['代表中国先进生产力的发展要求','代表中国先进文化的前进方向','代表中国最广大人民的根本利益','代表国有经济的垄断地位'],a:3,exp:'“三个代表”创造性回答了建设什么样的党、怎样建设党的问题。'}},

    /* ---------- 第九章第四节 在新形势下坚持和发展中国特色社会主义 ---------- */
    {ch:'c9',title:'党的十六大与全面建设小康社会目标',speak:'2002年11月党的十六大举行。大会把“三个代表”重要思想同马克思列宁主义、毛泽东思想、邓小平理论一道确立为党必须长期坚持的指导思想并写入党章。大会提出21世纪头20年是必须紧紧抓住并且可以大有作为的重要战略机遇期，要集中力量全面建设惠及十几亿人口的更高水平的小康社会，国内生产总值到2020年力争比2000年翻两番。大会明确回答了新世纪新阶段党举什么旗、走什么路、实现什么样的发展目标等重大问题。',
      quiz:{type:'fill',q:'党的十六大提出，国内生产总值到2020年力争比2000年翻______番。',answer:'两',exp:'十六大以后中国人民踏上了全面建设小康社会的新征程。'}},
    {ch:'c9',title:'抗击非典与科学发展观的提出',speak:'2003年春我国遭遇非典型肺炎重大疫情，举国上下紧急动员、坚持群防群控，6月取得抗击非典阶段性重大胜利。非典暴露出发展不够协调、公共卫生事业发展滞后、突发事件应急机制不健全等新矛盾，引发党中央对“实现什么样的发展、怎样发展”的深入思考。2003年8月底9月初胡锦涛在江西考察时提出“科学发展观”概念，同年10月十六届三中全会完整提出坚持以人为本，树立全面、协调、可持续的发展观。',
      quiz:{type:'choice',q:'科学发展观的核心是？',opts:['发展','以人为本','全面协调可持续','统筹兼顾'],a:1,exp:'科学发展观第一要义是发展，核心是以人为本。'}},
    {ch:'c9',title:'构建社会主义和谐社会',speak:'2006年10月十六届六中全会审议通过《中共中央关于构建社会主义和谐社会若干重大问题的决定》，提出按照民主法治、公平正义、诚信友爱、充满活力、安定有序、人与自然和谐相处的总要求构建社会主义和谐社会，强调必须坚持以人为本，始终把最广大人民的根本利益作为党和国家一切工作的出发点和落脚点，做到发展为了人民、发展依靠人民、发展成果由人民共享。',
      quiz:{type:'fill',q:'构建社会主义和谐社会的总要求包括民主法治、公平正义、诚信友爱、充满活力、安定有序、人与自然______相处。',answer:'和谐',exp:'社会和谐是中国特色社会主义的本质属性。'}},
    {ch:'c9',title:'完善社会主义市场经济体制与“又好又快”方针',speak:'2003年10月十六届三中全会通过《中共中央关于完善社会主义市场经济体制若干问题的决定》，提出发展混合所有制经济、放宽市场准入、建立现代产权制度、逐步改变城乡二元经济结构等重大政策措施。2006年10月十六届六中全会提出“促进经济又好又快发展”的新的发展方针，从持续使用多年的“又快又好”到“又好又快”，不只是顺序调整，更体现了科学发展的本质要求。',
      quiz:{type:'choice',q:'2006年党中央提出的经济发展新方针是？',opts:['多快好省','又快又好','又好又快','超常规跨越式发展'],a:2,exp:'“好”字当头体现了注重优化结构、提高质量和效益。'}},
    {ch:'c9',title:'区域协调发展战略与青藏铁路',speak:'根据科学发展观的要求，党中央作出西部大开发、振兴东北地区等老工业基地、促进中部地区崛起、支持东部地区率先发展等重大决策。2006年7月1日全长1956公里的青藏铁路全线通车，结束了西藏不通铁路的历史。国家批准上海浦东新区和天津滨海新区为全国综合配套改革试验区，长三角、珠三角和京津冀三大都市圈始终保持我国经济发展的“三大引擎”地位。',
      quiz:{type:'fill',q:'2006年7月1日，全长1956公里的______铁路全线通车，结束了西藏不通铁路的历史。',answer:'青藏',exp:'青藏铁路有力推动了雪域高原的跨越式发展。'}},
    {ch:'c9',title:'社会主义新农村建设与取消农业税',speak:'十六届四中全会提出“两个趋向”的重要论断：工业化初始阶段农业支持工业、为工业提供积累带有普遍性；工业化达到相当程度以后工业反哺农业、城市支持农村也具有普遍性。2005年10月十六届五中全会提出建设社会主义新农村的重大战略任务。同年12月十届全国人大常委会决定自2006年1月1日起废止《农业税条例》，在我国存在2600年的农业税成为历史。',
      quiz:{type:'fill',q:'自2006年1月1日起我国废止《______税条例》，存在2600年的农业税成为历史。',answer:'农业',exp:'取消农业税根本性地扭转了农民负担过重的状况。'}},
    {ch:'c9',title:'“十一五”规划与“计划”改“规划”',speak:'2005年10月十六届五中全会通过关于制定“十一五”规划的建议，2006年3月十届全国人大四次会议审议通过规划纲要。“十一五”规划第一次将延续50多年的“计划”改为“规划”，一字之差体现了社会主义市场经济条件下中长期规划的功能定位，反映了我国发展理念、经济体制、政府职能的重大变革。2005年“十五”计划主要目标提前实现，人均国内生产总值突破1000美元。',
      quiz:{type:'choice',q:'“十一五”规划的一个标志性变化是？',opts:['首次称为“规划”而非“计划”','首次提出小康目标','首次提出四个现代化','首次提出改革开放'],a:0,exp:'这一字之差反映了发展理念和政府职能的重大变革。'}},
    {ch:'c9',title:'党的十七大与中国特色社会主义理论体系',speak:'2007年10月党的十七大举行。大会阐述了中国特色社会主义道路的基本内涵，首次提出中国特色社会主义理论体系的概念并作概括，指出这一体系包括邓小平理论、“三个代表”重要思想以及科学发展观等重大战略思想。大会全面阐述科学发展观的科学内涵：第一要义是发展，核心是以人为本，基本要求是全面协调可持续，根本方法是统筹兼顾，并决定将这一成果写入党章。大会还提出实现人均国内生产总值到2020年比2000年翻两番的更高要求。',
      quiz:{type:'fill',q:'党的十七大首次提出______社会主义理论体系的概念并作了概括。',answer:'中国特色',exp:'改革开放取得一切成绩和进步的根本原因就是开辟了道路、形成了理论体系。'}},
    {ch:'c9',title:'应对国际金融危机与抗击汶川特大地震',speak:'2008年国际金融危机爆发后，党中央、国务院果断把宏观调控着力点转到防止经济增速过快下滑上来，实施积极的财政政策和适度宽松的货币政策，形成大规模增加政府投资、结构性减税、十个重点产业调整振兴规划等一揽子计划，我国在世界上率先实现经济回升向好，2009年增长9.2%。2008年5月12日四川汶川发生里氏8.0级特大地震，我国开展了历史上救援速度最快、动员范围最广、投入力量最大的抗震救灾斗争，到2010年9月底重建任务提前一年基本完成。',
      quiz:{type:'fill',q:'2009年我国经济在世界范围内率先回升向好，全年增长______%。',answer:'9.2',exp:'抗震救灾彰显了一方有难、八方支援、集中力量办大事的制度优势。'}},
    {ch:'c9',title:'加快转变经济发展方式与深化重要领域改革',speak:'党的十七大提出加快转变经济发展方式的战略任务。2010年10月十七届五中全会明确要求把经济结构战略性调整作为主攻方向，把科技进步和创新作为重要支撑，把保障和改善民生作为根本出发点和落脚点，把建设资源节约型、环境友好型社会作为重要着力点，把改革开放作为强大动力。国有经济战略性调整加快推进，中央企业由2007年的159家减少到2011年的117家；2008年10月十七届三中全会要求坚决守住18亿亩耕地红线。',
      quiz:{type:'choice',q:'2010年十七届五中全会提出加快转变经济发展方式的主攻方向是？',opts:['经济结构战略性调整','扩大出口规模','增加固定资产投资','提高税率水平'],a:0,exp:'转变经济发展方式要着力解决结构性矛盾和增长方式粗放问题。'}},
    {ch:'c9',title:'民主法治、文化建设与社会建设',speak:'2010年3月十一届全国人大三次会议通过新修改的选举法，明确城乡按相同人口比例选举人大代表，实现新中国历史上城乡“同票同权”。到2010年底，中国特色社会主义法律体系形成。2011年10月十七届六中全会提出坚持中国特色社会主义文化发展道路、努力建设社会主义文化强国的战略任务。2008年城乡义务教育全部免除学杂费，新型农村合作医疗制度覆盖全国，到2012年城乡基本养老保险制度全面建立、全民医保基本实现。',
      quiz:{type:'fill',q:'2010年修改选举法，明确城乡按相同人口比例选举人大代表，实现了城乡“______同权”。',answer:'同票',exp:'这是社会主义民主政治建设的重要进展。'}},
    {ch:'c9',title:'“十一五”成就与北京奥运、上海世博',speak:'“十一五”时期我国国内生产总值年均增长11.3%，2010年中国经济总量超过日本成为世界第二大经济体。载人航天、探月工程、超级计算机等实现新的重大突破，“神舟七号”航天员成功进行中国人第一次太空漫步，“嫦娥一号”首次完成绕月探测。2008年8月北京成功举办第二十九届夏季奥运会，中国体育代表团居金牌榜首位；2010年5月至10月上海世界博览会举行，是第一次在发展中国家举办的注册类世博会。',
      quiz:{type:'choice',q:'2010年中国经济总量超过日本，成为世界第几大经济体？',opts:['第一','第二','第三','第四'],a:1,exp:'这标志着我国综合国力和国际影响力显著提升。'}},
    {ch:'c9',title:'国防和军队现代化建设与“辽宁舰”',speak:'2004年中央军委提出，要把军事斗争准备的基点放在打赢信息化条件下的局部战争上。为适应中国特色军事变革要求，中央对军队体制编制进行调整改革，推动作战力量编成向精干、联合、多能、高效方向发展，着力提升国防科技和武器装备自主创新能力。2012年9月我国第一艘航空母舰“辽宁舰”正式交付海军。全军和武警部队出色完成一系列急难险重任务，展示了威武之师、文明之师、和平之师形象。',
      quiz:{type:'fill',q:'2012年9月，我国第一艘航空母舰“______舰”正式交付海军。',answer:'辽宁',exp:'“辽宁舰”入列标志着国防和军队现代化建设迈出重要步伐。'}},
    {ch:'c9',title:'和平发展外交',speak:'中国始终不渝走和平发展道路，按照“大国是关键、周边是首要、发展中国家是基础、多边是重要舞台”的外交工作总体布局开展富有成效的外交活动。2002年11月中国同东盟签署《南海各方行为宣言》，2010年1月“中国—东盟自由贸易区”正式启动，2006年11月在北京成功举办中非合作论坛。中国积极推动全球经济治理机制改革，参与安全反恐等国际合作。',
      quiz:{type:'choice',q:'中国外交工作总体布局中，周边是？',opts:['关键','首要','基础','重要舞台'],a:1,exp:'大国是关键、周边是首要、发展中国家是基础、多边是重要舞台。'}},
    {ch:'c9',title:'推进“一国两制”实践与祖国和平统一大业',speak:'中央政府坚定不移贯彻“一国两制”、“港人治港”、“澳人治澳”、高度自治的方针。全国人大常委会先后于1999年、2004年、2005年、2011年对香港基本法及其附件有关条款作出解释。从2003年起内地与香港、澳门分别签署关于建立更紧密经贸关系的安排。2005年3月十届全国人大三次会议高票通过《反分裂国家法》；4月胡锦涛会见中国国民党主席连战，实现60年来两党主要领导人第一次历史性握手；2008年12月两岸“三通”迈开历史性步伐；2010年6月签署《海峡两岸经济合作框架协议》。',
      quiz:{type:'fill',q:'2005年3月，十届全国人大三次会议高票通过《______国家法》。',answer:'反分裂',exp:'这充分表明全中国人民反对“台独”、维护国家统一的共同意志。'}},
    {ch:'c9',title:'提高党的建设科学化水平与反腐败斗争',speak:'十六大后党中央以执政能力建设和先进性建设为主线推进党的建设新的伟大工程。2004年9月十六届四中全会通过《关于加强党的执政能力建设的决定》，提出不断提高驾驭社会主义市场经济、发展社会主义民主政治、建设社会主义先进文化、构建社会主义和谐社会、应对国际局势和处理国际事务五种能力。2009年9月十七届四中全会提出提高党的建设科学化水平的重大命题。2006年2月我国成为《联合国反腐败公约》缔约国，坚决查处了陈良宇等重大违纪违法案件。',
      quiz:{type:'choice',q:'2004年十六届四中全会提出的党的执政能力不包括？',opts:['驾驭社会主义市场经济的能力','发展社会主义民主政治的能力','构建社会主义和谐社会的能力','直接经营管理企业的能力'],a:3,exp:'党要提高的是执政能力，而不是直接干预企业经营。'}},
    {ch:'c9',title:'科学发展观确立为党的指导思想',speak:'2012年党的十八大通过的《中国共产党章程（修正案）》，把科学发展观同马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想一道确立为党的指导思想并载入党章。以邓小平为主要代表的中国共产党人成功开创中国特色社会主义，以江泽民为主要代表的中国共产党人成功把中国特色社会主义推向21世纪，以胡锦涛为主要代表的中国共产党人成功在新形势下坚持和发展了中国特色社会主义。',
      quiz:{type:'fill',q:'2012年，党的十八大把______确立为党的指导思想并载入党章。',answer:'科学发展观',exp:'科学发展观把党对中国特色社会主义规律的认识提高到新的水平。'}},

    /* 大纲补缺：农业“两个飞跃”、江八点、90年代后期风险考验 */
    {ch:'c9',title:'中国农业改革和发展的“两个飞跃”',speak:'1990年3月，邓小平提出中国社会主义农业的改革和发展要有“两个飞跃”：第一个飞跃是废除人民公社，实行家庭联产承包为主的责任制；第二个飞跃是适应科学种田和生产社会化的需要，发展适度规模经营，发展集体经济。这一思想为深化农村改革指明了方向。',
      quiz:{type:'fill',q:'邓小平提出的农业“两个飞跃”中，第一个飞跃是废除人民公社、实行 ______ 。',answer:'家庭联产承包责任制',exp:'第一个飞跃是实行家庭联产承包责任制，第二个飞跃是发展适度规模经营和集体经济。'}},
    {ch:'c9',title:'《为促进祖国统一大业的完成而继续奋斗》',speak:'1995年1月30日，江泽民发表《为促进祖国统一大业的完成而继续奋斗》的重要讲话（“江八点”），就发展两岸关系、推进祖国和平统一进程提出八项主张：坚持一个中国原则是实现和平统一的基础和前提；不承诺放弃使用武力，是针对外国势力干涉中国统一和“台独”图谋的；大力发展两岸经济交流与合作等。这是解决台湾问题的重要纲领性文件。',
      quiz:{type:'choice',q:'1995年提出发展两岸关系、推进和平统一八项主张的文献是？',opts:['《为促进祖国统一大业的完成而继续奋斗》','《告台湾同胞书》','叶剑英九条方针','《反分裂国家法》'],a:0,exp:'“江八点”即《为促进祖国统一大业的完成而继续奋斗》，是两岸关系的重要纲领性文件。'}},
    {ch:'c9',title:'20世纪90年代后期经受的风险考验',speak:'1997年下半年亚洲金融危机爆发，党中央坚持人民币不贬值，采取扩大内需、实行积极财政政策和稳健货币政策等措施，成功应对了冲击。1998年长江、嫩江、松花江流域发生特大洪水，全党全军全国人民团结奋战，取得抗洪抢险斗争的伟大胜利。党和人民经受住了经济风险和严重自然灾害的严峻考验，保持了改革开放和现代化建设的稳定发展。',
      quiz:{type:'choice',q:'1997年亚洲金融危机中我国采取的重要对策是？',opts:['坚持人民币不贬值、扩大内需','人民币大幅贬值','关闭全部金融机构','停止对外贸易'],a:0,exp:'我国坚持人民币不贬值并扩大内需，为亚洲经济稳定作出贡献，也保持了自身发展。'}},

    /* ============ 第十章 ============ */
    {ch:'c10',title:'中国特色社会主义进入新时代',speak:'党的十八大以来，中国特色社会主义进入新时代，这是我国发展新的历史方位，意味着中华民族迎来从站起来、富起来到强起来的飞跃。',
      quiz:{type:'choice',q:'中国特色社会主义进入新时代的标志是？',opts:['1978 年十一届三中全会','2012 年党的十八大以来','1992 年邓小平南方谈话','2001 年入世'],a:1,exp:'2012 年党的十八大以来，中国特色社会主义进入新时代。'}},
    {ch:'c10',title:'习近平新时代中国特色社会主义思想的指导地位',speak:'党的十九大确立习近平新时代中国特色社会主义思想的指导地位并写入党章，十三届全国人大一次会议写入宪法。',
      quiz:{type:'choice',q:'习近平新时代中国特色社会主义思想写入宪法是在？',opts:['党的十八大','党的十九大','十三届全国人大一次会议','十四届全国人大一次会议'],a:2,exp:'2018 年十三届全国人大一次会议将其写入宪法。'}},
    {ch:'c10',title:'全面建成小康社会与第一个百年目标',speak:'2021年建党百年，我国历史性地解决了绝对贫困问题，全面建成小康社会，实现第一个百年奋斗目标。',
      quiz:{type:'fill',q:'______ 年我国全面建成小康社会，实现第一个百年奋斗目标。',answer:'2021',exp:'2021 年建党百年，全面建成小康社会，历史性地解决绝对贫困。'}},
    {ch:'c10',title:'中国式现代化与新征程',speak:'党的二十大擘画以中国式现代化全面推进中华民族伟大复兴；建成现代化强国分两步走：2035年基本实现现代化，本世纪中叶建成现代化强国。',
      quiz:{type:'choice',q:'全面建成社会主义现代化强国"两步走"，到2035年要？',opts:['基本实现社会主义现代化','建成现代化强国','实现共产主义','完成工业化'],a:0,exp:'第一步到 2035 年基本实现社会主义现代化，第二步到本世纪中叶建成现代化强国。'}},

    /* ---------- 第十章第一节 开拓中国特色社会主义更为广阔的发展前景 ---------- */
    {ch:'c10',title:'党的十八大的召开',speak:'2012年11月8日至14日，中国共产党第十八次全国代表大会在北京举行。大会贯穿始终的一条主线是坚持和发展中国特色社会主义，阐明道路、理论体系、制度的科学内涵及相互关系，指出建设中国特色社会主义的总依据是社会主义初级阶段，总布局是经济、政治、文化、社会、生态文明建设“五位一体”，总任务是实现社会主义现代化和中华民族伟大复兴，并提出夺取新胜利必须牢牢把握的八项基本要求。大会确立了科学发展观的历史地位。',
      quiz:{type:'fill',q:'2012年11月党的______大提出“五位一体”总体布局，确立了科学发展观的历史地位。',answer:'十八',exp:'党的十八大是进入全面建成小康社会决定性阶段召开的一次十分重要的大会。'}},
    {ch:'c10',title:'新时代：我国发展新的历史方位',speak:'党的十八大以来，以习近平同志为核心的党中央统筹把握中华民族伟大复兴战略全局和世界百年未有之大变局，开创了中国特色社会主义新时代。新时代是我国发展新的历史方位，是承前启后、继往开来、继续夺取中国特色社会主义伟大胜利的时代，是决胜全面建成小康社会、进而全面建设社会主义现代化强国的时代。这一重大政治判断意味着中华民族迎来了从站起来、富起来到强起来的伟大飞跃，意味着科学社会主义在21世纪的中国焕发出强大生机活力。',
      quiz:{type:'fill',q:'中国特色社会主义进入新时代，意味着中华民族迎来了从站起来、富起来到______的伟大飞跃。',answer:'强起来',exp:'新时代是十九大作出的重大政治判断。'}},
    {ch:'c10',title:'提出实现中华民族伟大复兴的中国梦',speak:'2012年11月29日，习近平在参观《复兴之路》展览时首次提出并阐释实现中华民族伟大复兴的中国梦。在十二届全国人大一次会议上，他阐明中国梦的基本内涵是国家富强、民族振兴、人民幸福，强调实现中国梦必须走中国道路、必须弘扬中国精神、必须凝聚中国力量。中国梦归根到底是人民的梦，是和平、发展、合作、共赢的梦。',
      quiz:{type:'choice',q:'实现中国梦必须弘扬中国精神，这就是以爱国主义为核心的民族精神和以什么为核心的时代精神？',opts:['改革创新','艰苦奋斗','集体主义','实事求是'],a:0,exp:'中国精神是凝心聚力的兴国之魂、强国之魂。'}},
    {ch:'c10',title:'确立习近平同志党中央的核心、全党的核心地位',speak:'党的十八大以来，习近平在治国理政新实践中展现出坚定信仰信念、鲜明人民立场、非凡政治智慧、强烈历史担当，提出一系列原创性治国理政新理念新思想新战略，事实上已经成为党中央的核心、全党的核心。2016年10月，党的十八届六中全会正式提出“以习近平同志为核心的党中央”并郑重写入全会文件；2017年10月，党的十九大把“坚定维护以习近平同志为核心的党中央权威和集中统一领导”写入党章。',
      quiz:{type:'fill',q:'2016年10月，党的十八届六中全会正式明确习近平同志党中央的核心、全党的______地位。',answer:'核心',exp:'确立核心地位是实践的选择、历史的选择，是全党、人民的选择。'}},
    {ch:'c10',title:'经济发展新常态与新发展理念',speak:'2013年12月，习近平在中央经济工作会议上提出“新常态”。2014年12月中央经济工作会议总结出新常态下我国经济发展的四个主要特点：增长速度从高速转向中高速，发展方式从规模速度型粗放增长转向质量效率型集约增长，经济结构从增量扩能为主转向调整存量、做优增量并举，发展动力从传统增长点转向新的增长点。2015年10月十八届五中全会提出以人民为中心的发展思想，提出创新、协调、绿色、开放、共享的新发展理念。',
      quiz:{type:'choice',q:'2015年党的十八届五中全会提出的新发展理念是？',opts:['创新、协调、绿色、开放、共享','多快好省','效率优先、兼顾公平','去产能、去库存、去杠杆'],a:0,exp:'新发展理念是管全局、管根本、管长远的导向。'}},
    {ch:'c10',title:'供给侧结构性改革与重大发展战略',speak:'2015年11月，习近平在中央财经领导小组第十一次会议上首次提出推进“供给侧结构性改革”。12月中央经济工作会议强调要抓好去产能、去库存、去杠杆、降成本、补短板五大任务。党的十八大后，党中央提出并实施创新驱动发展、京津冀协同发展、长江经济带建设、“一带一路”建设、新型城镇化、国家粮食安全、粤港澳大湾区建设、能源安全新战略等一系列重大战略。',
      quiz:{type:'fill',q:'供给侧结构性改革的五大任务是去产能、去库存、去杠杆、降成本、______。',answer:'补短板',exp:'供给侧结构性改革是适应和引领经济发展新常态的重大创新。'}},
    {ch:'c10',title:'十八届三中全会与全面深化改革',speak:'2013年11月9日至12日，党的十八届三中全会审议通过《中共中央关于全面深化改革若干重大问题的决定》，明确全面深化改革的总目标是“完善和发展中国特色社会主义制度，推进国家治理体系和治理能力现代化”，提出“使市场在资源配置中起决定性作用和更好发挥政府作用”等新论断，出台336项改革举措，并决定成立中央全面深化改革领导小组，习近平任组长。全会实现了改革由局部探索、破冰突围到系统集成、全面深化的转变。',
      quiz:{type:'choice',q:'党的十八届三中全会确定的全面深化改革总目标是？',opts:['完善和发展中国特色社会主义制度，推进国家治理体系和治理能力现代化','建立社会主义市场经济体制','全面建成小康社会','建设社会主义法治国家'],a:0,exp:'十八届三中全会是继十一届三中全会之后又一次具有划时代意义的重要会议。'}},
    {ch:'c10',title:'十八届四中全会与全面依法治国',speak:'2014年10月，党的十八届四中全会通过《中共中央关于全面推进依法治国若干重大问题的决定》，明确全面推进依法治国的总目标是建设中国特色社会主义法治体系、建设社会主义法治国家，提出180多项重要改革举措。党中央明确坚持依法治国首先要坚持依宪治国：2014年11月十二届全国人大常委会以立法形式将12月4日设立为国家宪法日，2015年7月又明确规定国家工作人员就职时应当公开进行宪法宣誓。',
      quiz:{type:'fill',q:'2014年11月，十二届全国人大常委会以立法形式将12月4日设立为国家______日。',answer:'宪法',exp:'全面依法治国在“四个全面”战略布局中具有基础性、保障性作用。'}},
    {ch:'c10',title:'全面从严治党',speak:'全面从严治党是“四个全面”战略布局的根本保证。党中央从制定和落实中央八项规定破题，以上率下改进作风；先后开展党的群众路线教育实践活动、“三严三实”专题教育、“两学一做”学习教育；坚持纪在法前、纪严于法，创造性提出并运用监督执纪“四种形态”。党的十八大后五年，经党中央批准立案审查的省军级以上党员干部及其他中管干部440人，坚决查处了周永康、薄熙来、孙政才、令计划等严重违纪违法问题，反腐败斗争压倒性态势已经形成并巩固发展。',
      quiz:{type:'choice',q:'党的十八大后全面从严治党的破题之举是？',opts:['制定和落实中央八项规定','开展全面整党','开展“三反”“五反”','进行整风运动'],a:0,exp:'作风建设从中央政治局做起，以上率下，党风政风为之一新。'}},
    {ch:'c10',title:'全面推进国防和军队现代化',speak:'2013年3月，习近平明确指出建设一支听党指挥、能打胜仗、作风优良的人民军队，是党在新形势下的强军目标。其中听党指挥是灵魂，能打胜仗是核心，作风优良是保证。2014年10月全军政治工作会议在古田召开，确立新时代政治建军方略。2015年11月中央军委改革工作会议后，领导指挥体制改革率先展开，打破长期实行的总部体制、大军区体制、大陆军体制，形成军委管总、战区主战、军种主建新格局。',
      quiz:{type:'fill',q:'党在新形势下的强军目标是建设一支听党指挥、能打胜仗、______的人民军队。',answer:'作风优良',exp:'强军目标是党在新时代建军治军的总方略。'}},
    {ch:'c10',title:'全面加强国家安全与总体国家安全观',speak:'2014年4月，习近平在十八届中央国家安全委员会第一次会议上首次提出“总体国家安全观”，强调以人民安全为宗旨，以政治安全为根本，以经济安全为基础，以军事、文化、社会安全为保障，以促进国际安全为依托，走出一条中国特色国家安全道路。2015年7月十二届全国人大常委会通过《中华人民共和国国家安全法》，以法律形式确立总体国家安全观的指导地位。',
      quiz:{type:'choice',q:'总体国家安全观以什么为宗旨？',opts:['人民安全','政治安全','经济安全','军事安全'],a:0,exp:'政治安全是根本，经济安全是基础。'}},
    {ch:'c10',title:'社会主义民主政治与文化建设',speak:'2012年12月，习近平概括中国特色社会主义政治发展道路的核心内涵，强调关键是要坚持党的领导、人民当家作主、依法治国有机统一。2015年1月中共中央印发《关于加强社会主义协商民主建设的意见》，2015年3月修改立法法赋予设区的市地方立法权。文化建设方面，党中央大力培育和践行社会主义核心价值观，召开文艺工作座谈会、全国宣传思想工作会议，提出坚持中国特色社会主义文化发展道路、建设社会主义文化强国的战略任务，推动中华优秀传统文化创造性转化、创新性发展。',
      quiz:{type:'choice',q:'坚持中国特色社会主义政治发展道路，关键是要坚持党的领导、人民当家作主和什么的有机统一？',opts:['依法治国','改革开放','共同富裕','民主集中制'],a:0,exp:'三者的有机统一是中国特色社会主义政治发展道路的核心内涵。'}},
    {ch:'c10',title:'生态文明建设与美丽中国',speak:'党中央树立和践行绿水青山就是金山银山的理念，把生态文明建设纳入“五位一体”总体布局。2015年中央印发《生态文明体制改革总体方案》，2018年宪法修正案将生态文明写入宪法。2015年底，我国在联合国气候变化巴黎大会上积极推动达成《巴黎协定》这一历史性文件。塞罕坝林场建设者创造了荒原变林海的人间奇迹，成为全球生态文明建设的重要参与者、贡献者、引领者。',
      quiz:{type:'fill',q:'2015年底，我国积极推动联合国气候变化巴黎大会达成《______协定》。',answer:'巴黎',exp:'中国成为全球生态文明建设的重要参与者、贡献者、引领者。'}},
    {ch:'c10',title:'精准扶贫理念的提出',speak:'2012年12月，习近平到河北阜平考察扶贫开发工作，指出全面建成小康社会最艰巨最繁重的任务在农村特别是贫困地区。2013年11月，他在湖南湘西州十八洞村考察时创造性地提出“精准扶贫”的重要理念，标志着我国扶贫方式的重大转变。2015年6月他进一步强调做到“六个精准”，即扶持对象、项目安排、资金使用、措施到户、因村派人、脱贫成效精准。',
      quiz:{type:'fill',q:'2013年11月，习近平在湖南湘西十八洞村考察时提出“______扶贫”的重要理念。',answer:'精准',exp:'精准扶贫标志着我国扶贫方式的重大转变。'}},

    /* ---------- 第十章第二节 把新时代中国特色社会主义不断推向前进 ---------- */
    {ch:'c10',title:'党的十九大的召开',speak:'2017年10月18日至24日，中国共产党第十九次全国代表大会在北京举行。大会的主题是：不忘初心，牢记使命，高举中国特色社会主义伟大旗帜，决胜全面建成小康社会，夺取新时代中国特色社会主义伟大胜利，为实现中华民族伟大复兴的中国梦不懈奋斗。习近平作题为《决胜全面建成小康社会，夺取新时代中国特色社会主义伟大胜利》的报告。大会把习近平新时代中国特色社会主义思想确立为党必须长期坚持的指导思想并写入党章。',
      quiz:{type:'fill',q:'2017年10月召开的党的______大，把习近平新时代中国特色社会主义思想写入党章。',answer:'十九',exp:'大会作出了中国特色社会主义进入新时代的重大政治判断。'}},
    {ch:'c10',title:'新时代我国社会主要矛盾的转化',speak:'党的十九大作出我国社会主要矛盾已经发生转化的重大政治论断：中国特色社会主义进入新时代，我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。这一变化没有改变我们对我国社会主义所处历史阶段的判断：我国仍处于并将长期处于社会主义初级阶段的基本国情没有变，我国是世界最大发展中国家的国际地位没有变。',
      quiz:{type:'choice',q:'新时代我国社会主要矛盾是？',opts:['人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾','人民日益增长的物质文化需要同落后的社会生产之间的矛盾','无产阶级同资产阶级的矛盾','生产力与生产关系的矛盾'],a:0,exp:'主要矛盾变化是关系全局的历史性变化。'}},
    {ch:'c10',title:'习近平新时代中国特色社会主义思想指导地位的确立',speak:'党的十九大用“八个明确”和“十四个坚持”全面阐述了习近平新时代中国特色社会主义思想的科学内涵和实践要求，并把这一思想确立为党必须长期坚持的指导思想写入党章。2018年3月，十三届全国人大一次会议通过的宪法修正案把习近平新时代中国特色社会主义思想载入宪法，实现国家指导思想的与时俱进。习近平经济思想、法治思想、生态文明思想、强军思想、外交思想是这一理论体系在相关领域的展开。',
      quiz:{type:'fill',q:'党的十九大用“八个明确”和“______个坚持”阐述习近平新时代中国特色社会主义思想的科学内涵。',answer:'十四',exp:'2018年3月，该思想被载入宪法。'}},
    {ch:'c10',title:'坚持党的全面领导',speak:'党的十九大把“党是领导一切的”这一重大政治原则写入党章。2018年3月，十三届全国人大一次会议通过宪法修正案，在总纲中明确规定中国共产党领导是中国特色社会主义最本质的特征，强化了党总揽全局、协调各方的领导地位。党中央先后审议通过《中共中央政治局关于加强和维护党中央集中统一领导的若干规定》，印发《中国共产党重大事项请示报告条例》，从制度上保证党中央权威和集中统一领导。',
      quiz:{type:'choice',q:'2018年宪法修正案在总纲中明确规定，中国特色社会主义最本质的特征是？',opts:['中国共产党领导','公有制为主体','共同富裕','人民民主专政'],a:0,exp:'中国特色社会主义制度的最大优势是中国共产党领导。'}},
    {ch:'c10',title:'推进党的自我革命',speak:'党的十九大提出新时代党的建设总要求，对推进党的建设新的伟大工程作出顶层设计。党中央把党的政治建设摆在首位，印发《关于加强党的政治建设的意见》，把“两个维护”作为首要任务；2018年8月修订《中国共产党纪律处分条例》，对搞两面派、做“两面人”等行为作出具体规定。党在革命性锻造中更加坚强，自我净化、自我完善、自我革新、自我提高能力显著增强。',
      quiz:{type:'fill',q:'党的十九大提出新时代党的建设总要求，把党的______建设摆在首位。',answer:'政治',exp:'党的政治建设决定党的建设方向和效果，是党的建设的“灵魂”和“根基”。'}},
    {ch:'c10',title:'党和国家机构改革与国家治理体系建设',speak:'2018年2月，党的十九届三中全会通过《中共中央关于深化党和国家机构改革的决定》和《深化党和国家机构改革方案》，从机构职能上把加强党的领导落实到各领域各方面各环节。全会把组建国家监察委员会列为深化党中央机构改革第一项任务，2018年3月十三届全国人大一次会议通过宪法修正案确立监察委员会的宪法地位并通过《监察法》。2019年10月十九届四中全会专题研究坚持和完善中国特色社会主义制度、推进国家治理体系和治理能力现代化问题。',
      quiz:{type:'choice',q:'2019年10月党的十九届四中全会专题研究的问题是？',opts:['坚持和完善中国特色社会主义制度、推进国家治理体系和治理能力现代化','全面深化改革','全面推进依法治国','制定“十四五”规划'],a:0,exp:'全会概括了我国国家制度和国家治理体系13个方面的显著优势。'}},
    {ch:'c10',title:'抗击新冠疫情与应对风险挑战',speak:'2020年初新冠肺炎疫情突如其来，以习近平同志为核心的党中央坚持人民至上、生命至上，开展抗击疫情人民战争、总体战、阻击战，举全国之力实施规模空前的生命大救援，武汉保卫战、湖北保卫战取得决定性成果。党中央提出做好“六稳”工作、落实“六保”任务。2020年5月，十三届全国人大三次会议通过《中华人民共和国民法典》。我国成为2020年全球唯一实现经济正增长的主要经济体。',
      quiz:{type:'fill',q:'2020年5月，十三届全国人大三次会议通过《中华人民共和国______法典》。',answer:'民',exp:'这是新中国第一部以“法典”命名的法律。'}},
    {ch:'c10',title:'坚持“一国两制”与推进祖国统一',speak:'面对2019年香港“修例风波”，党中央果断决策：2020年5月十三届全国人大三次会议通过建立健全香港特别行政区维护国家安全的法律制度和执行机制的决定，6月全国人大常委会通过《中华人民共和国香港特别行政区维护国家安全法》，2021年3月十三届全国人大四次会议通过完善香港特别行政区选举制度的决定，推动香港局势实现由乱到治的重大转折。两岸方面，2015年11月7日习近平同马英九在新加坡会晤，是1949年以来两岸领导人首次会晤。',
      quiz:{type:'fill',q:'2020年6月，十三届全国人大常委会通过《中华人民共和国香港特别行政区维护______法》。',answer:'国家安全',exp:'香港国安法推动香港局势实现由乱到治的重大转折。'}},
    {ch:'c10',title:'中国特色大国外交与人类命运共同体',speak:'2014年11月中央外事工作会议明确提出，中国必须有自己特色的大国外交。我国实施共建“一带一路”，发起创办亚洲基础设施投资银行，设立丝路基金，举办“一带一路”国际合作高峰论坛、亚太经合组织第二十二次领导人非正式会议、二十国集团领导人杭州峰会、金砖国家领导人厦门会晤、首届亚洲文明对话大会等。2013年3月习近平在莫斯科国际关系学院提出当今世界“越来越成为你中有我、我中有你的命运共同体”。',
      quiz:{type:'choice',q:'2014年11月中央外事工作会议提出的重大命题是？',opts:['中国必须有自己特色的大国外交','韬光养晦、绝不当头','建立国际反霸统一战线','输出中国模式'],a:0,exp:'以这次会议为标志，中国特色大国外交迈出新的步伐。'}},

    /* ---------- 第十章第三节 开启全面建设社会主义现代化国家新征程 ---------- */
    {ch:'c10',title:'脱贫攻坚战取得全面胜利',speak:'2020年11月，随着新疆、云南、贵州等最后52个贫困县宣布退出，全国832个贫困县全部摘帽，12.8万个贫困村全部出列，现行标准下9899万农村贫困人口全部脱贫，区域性整体贫困得到解决。2021年2月25日，党中央、国务院隆重举行全国脱贫攻坚总结表彰大会，习近平庄严宣告我国脱贫攻坚战取得了全面胜利。党的十八大以来平均每年1000多万人脱贫，全国累计选派25.5万个驻村工作队、300多万名第一书记和驻村干部，1800多名同志将生命定格在脱贫攻坚征程上。',
      quiz:{type:'fill',q:'2021年2月25日，全国脱贫攻坚总结表彰大会宣告我国脱贫攻坚战取得全面______。',answer:'胜利',exp:'这是中国人民、中国共产党、中华民族的伟大光荣。'}},
    {ch:'c10',title:'全面建成小康社会',speak:'2021年7月1日，习近平在庆祝中国共产党成立100周年大会上庄严宣告，经过全党全国各族人民持续奋斗，我们实现了第一个百年奋斗目标，在中华大地上全面建成了小康社会，历史性地解决了绝对贫困问题。从“小康之家”到“小康社会”，从“总体小康”到“全面小康”，从“全面建设”到“全面建成”，小康目标不断实现，千年梦想成为现实。',
      quiz:{type:'choice',q:'2021年7月1日，习近平庄严宣告我国全面建成了？',opts:['小康社会','社会主义现代化强国','共同富裕社会','发达社会主义社会'],a:0,exp:'全面建成小康社会实现了第一个百年奋斗目标。'}},
    {ch:'c10',title:'把握新发展阶段、贯彻新发展理念、构建新发展格局',speak:'2020年10月，党的十九届五中全会锚定2035年基本实现社会主义现代化的远景目标，对“十四五”时期发展作出系统谋划。2021年1月11日，习近平在省部级主要领导干部专题研讨班上指出，新发展阶段是社会主义初级阶段中的一个阶段，是其中经过几十年积累、站到了新的起点上的一个阶段。构建新发展格局，是以国内大循环为主体、国内国际双循环相互促进，是开放的国内国际双循环，不是封闭的国内单循环。',
      quiz:{type:'fill',q:'构建新发展格局，是以国内大循环为主体、国内国际______相互促进。',answer:'双循环',exp:'三者紧密关联：新发展阶段明确历史方位，新发展理念明确指导原则，新发展格局明确路径选择。'}},
    {ch:'c10',title:'隆重庆祝中国共产党成立一百周年',speak:'2021年2月20日党史学习教育动员大会召开，习近平要求做到学史明理、学史增信、学史崇德、学史力行。6月18日中国共产党历史展览馆开馆，6月28日文艺演出《伟大征程》举行，6月29日“七一勋章”颁授仪式举行，党中央首次向710多万名老党员颁发“光荣在党50年”纪念章。7月1日庆祝大会在北京天安门广场隆重举行，各界代表7万余人参加。习近平精辟概括伟大建党精神：坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民。',
      quiz:{type:'choice',q:'伟大建党精神的内容是？',opts:['坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民','自力更生、艰苦奋斗','解放思想、实事求是','敢于斗争、敢于胜利'],a:0,exp:'伟大建党精神是中国共产党的精神之源。'}},
    {ch:'c10',title:'党的十九届六中全会与第三个历史决议',speak:'2021年11月，党的十九届六中全会审议通过《中共中央关于党的百年奋斗重大成就和历史经验的决议》。这是党成立一百周年的重要历史时刻作出的第三个历史决议。《决议》回顾党百年奋斗历程，总结四个历史时期党面临的主要任务和创造的伟大成就，着重阐释党的十八大以来党和国家事业取得的历史性成就、发生的历史性变革，从坚持党的全面领导、全面从严治党、经济建设等13个方面分领域进行总结。',
      quiz:{type:'fill',q:'2021年11月，党的十九届六中全会通过《中共中央关于党的百年奋斗重大成就和历史经验的______》。',answer:'决议',exp:'这是党历史上的第三个历史决议。'}},
    {ch:'c10',title:'“两个确立”的决定性意义',speak:'党的十九届六中全会《决议》作出重大政治论断：党确立习近平同志党中央的核心、全党的核心地位，确立习近平新时代中国特色社会主义思想的指导地位，反映了全党全军全国各族人民共同心愿，对新时代党和国家事业发展、对推进中华民族伟大复兴历史进程具有决定性意义。“两个确立”是深刻总结党的百年奋斗历史经验特别是新时代伟大实践得出的重大历史结论，是党的十八大以来最重要的政治成果。',
      quiz:{type:'choice',q:'“两个确立”是指？',opts:['确立习近平同志党中央的核心、全党的核心地位，确立习近平新时代中国特色社会主义思想的指导地位','确立社会主义初级阶段，确立社会主义市场经济','确立四项基本原则，确立改革开放','确立小康社会目标，确立现代化强国目标'],a:0,exp:'“两个确立”是党的十八大以来最重要的政治成果。'}},
    {ch:'c10',title:'党的二十大的召开',speak:'2022年10月16日，中国共产党第二十次全国代表大会在北京开幕。习近平作题为《高举中国特色社会主义伟大旗帜，为全面建设社会主义现代化国家而团结奋斗》的报告。大会指出，新时代十年经历了三件大事：迎来中国共产党成立一百周年，中国特色社会主义进入新时代，完成脱贫攻坚、全面建成小康社会的历史任务、实现第一个百年奋斗目标。大会强调“两个结合”，即把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，提出必须坚持人民至上、自信自立、守正创新、问题导向、系统观念、胸怀天下。',
      quiz:{type:'choice',q:'党的二十大指出新时代十年经历的三件大事不包括？',opts:['迎来中国共产党成立一百周年','中国特色社会主义进入新时代','完成脱贫攻坚、全面建成小康社会的历史任务','加入世界贸易组织'],a:3,exp:'三件大事是党和人民团结奋斗赢得的历史性胜利。'}},
    {ch:'c10',title:'中国式现代化与全面建成社会主义现代化强国',speak:'党的二十大明确，新时代新征程中国共产党的中心任务就是团结带领全国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全面推进中华民族伟大复兴。中国式现代化是人口规模巨大的现代化、全体人民共同富裕的现代化、物质文明和精神文明相协调的现代化、人与自然和谐共生的现代化、走和平发展道路的现代化。大会重申两步走战略安排：从2020年到2035年基本实现社会主义现代化；从2035年到本世纪中叶把我国建成富强民主文明和谐美丽的社会主义现代化强国。党的二十大还宣告，经过新时代十年的奋斗，中华民族伟大复兴进入了不可逆转的历史进程。',
      quiz:{type:'choice',q:'下列不属于中国式现代化中国特色的是？',opts:['人口规模巨大','全体人民共同富裕','人与自然和谐共生','照搬西方现代化模式'],a:3,exp:'中国式现代化是中国共产党领导的社会主义现代化，既有各国现代化的共同特征，更有基于自己国情的中国特色。'}},
    /* 大纲补缺：三个务必、三期叠加、全过程人民民主、平安中国、高质量发展 */
    {ch:'c10',title:'党的二十大提出的“三个务必”',speak:'2022年10月，党的二十大提出“三个务必”：务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争。“三个务必”是对毛泽东在七届二中全会上提出的“两个务必”的继承和发展，体现了新时代新征程上党的清醒和坚定，是激励全党全国各族人民团结奋斗的重要要求。',
      quiz:{type:'fill',q:'党的二十大提出的“三个务必”包括务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必 ______ 、善于斗争。',answer:'敢于斗争',exp:'“三个务必”是对“两个务必”的继承和发展，新增了敢于斗争、善于斗争的要求。'}},
    {ch:'c10',title:'经济发展“三期叠加”与新常态',speak:'2013年前后，党中央判断我国经济发展面临“三期叠加”：增长速度换挡期、结构调整阵痛期、前期刺激政策消化期。这是提出经济发展新常态的重要依据。2014年5月，习近平首次提出“新常态”，强调认识新常态、适应新常态、引领新常态是当前和今后一个时期我国经济发展的大逻辑。',
      quiz:{type:'choice',q:'我国经济发展“三期叠加”不包括？',opts:['高速扩张增长期','增长速度换挡期','结构调整阵痛期','前期刺激政策消化期'],a:0,exp:'“三期叠加”指增长速度换挡期、结构调整阵痛期、前期刺激政策消化期。'}},
    {ch:'c10',title:'发展全过程人民民主',speak:'2019年11月，习近平在上海考察时提出“人民民主是一种全过程的民主”。全过程人民民主是社会主义民主政治的本质属性，包括民主选举、民主协商、民主决策、民主管理、民主监督各个环节，实现过程民主与成果民主、程序民主与实质民主、直接民主与间接民主相统一，是最广泛、最真实、最管用的民主。',
      quiz:{type:'choice',q:'我国社会主义民主政治的本质属性是？',opts:['全过程人民民主','代议制民主','基层群众自治','协商民主'],a:0,exp:'全过程人民民主是社会主义民主政治的本质属性，是最广泛、最真实、最管用的民主。'}},
    {ch:'c10',title:'建设更高水平的平安中国',speak:'党的十八大以来，平安中国建设成效显著：完善社会治安防控体系，开展扫黑除恶专项斗争并于2020年取得全面胜利；推进市域社会治理现代化，坚持和发展新时代“枫桥经验”；我国成为世界上命案发案率最低、刑事犯罪率最低的国家之一。建设更高水平的平安中国，是推进国家治理体系和治理能力现代化的重要内容。',
      quiz:{type:'choice',q:'新时代社会治理中坚持和发展的基层治理经验是？',opts:['新时代“枫桥经验”','“两参一改三结合”','“四议两公开”','“三治合一”'],a:0,exp:'新时代“枫桥经验”强调小事不出村、大事不出镇、矛盾不上交，是基层治理的重要经验。'}},
    {ch:'c10',title:'推动高质量发展',speak:'党的十九大指出，我国经济已由高速增长阶段转向高质量发展阶段。党的二十大把高质量发展确定为全面建设社会主义现代化国家的首要任务，强调构建高水平社会主义市场经济体制、建设现代化产业体系、全面推进乡村振兴、促进区域协调发展、推进高水平对外开放。高质量发展是体现新发展理念的发展。',
      quiz:{type:'fill',q:'党的二十大把 ______ 确定为全面建设社会主义现代化国家的首要任务。',answer:'高质量发展',exp:'高质量发展是全面建设社会主义现代化国家的首要任务。'}},
  ];

