  // 章节详情（含要点）
  const chapterDetail = {
    intro:{html:`<h3>一、时间界定</h3><p><span class="key">中国近现代史</span>是指 <span class="key">1840 年</span>以来的中国历史。</p>
      <ul><li><b>中国近代史</b>：1840 年鸦片战争 → 1949 年新中国成立前夕。</li>
      <li><b>中国现代史</b>：1949 年中华人民共和国成立以来。</li></ul>
      <h3>二、主流与本质</h3><p>是中国人民为<span class="key">救亡图存</span>和实现中华民族伟大复兴而英勇奋斗、艰辛探索并不断取得伟大成就的历史。</p>
      <h3>三、党的初心使命与两个保证</h3><p>党的最高理想是实现<b>共产主义</b>；初心使命是为中国人民谋幸福、为中华民族谋复兴。坚持和发展中国特色社会主义是<span class="key">必由之路</span>，坚持党的领导是<span class="key">根本保证</span>。</p>
      <h3>四、近代中国的社会性质与主要矛盾</h3><p>鸦片战争后中国逐步沦为<span class="key">半殖民地半封建社会</span>（两个根本变化：独立→半殖民地、封建→半封建）。社会性质决定主要矛盾：<b>帝国主义和中华民族</b>、<b>封建主义和人民大众</b>。</p>
      <h3>五、反侵略失败与两大历史任务</h3><p>反侵略战争失败根源：<span class="key">社会制度腐败、经济技术落后</span>。两大历史任务：<b>民族独立人民解放</b>（为后一任务扫清障碍）、<b>国家富强人民幸福</b>。</p>
      <h3>六、阶级、三座大山与三种建国方案</h3><p>新兴<b>工人阶级</b>是近代中国最革命的阶级。压在人民头上的<span class="key">三座大山</span>：帝国主义、封建主义、官僚资本主义。三种建国方案中，只有<b>工人阶级领导的人民共和国</b>赢得人民拥护——接受党的领导是历史性选择。</p>
      <h3>七、新民主主义革命与胜利意义</h3><p><span class="key">五四运动</span>是开端，<b>领导权变化</b>是区分新旧民主主义革命的根本标志。新民主主义革命胜利，结束半殖民地半封建社会、实现人民民主伟大飞跃，创立<b>毛泽东思想</b>（马克思主义中国化第一次历史性飞跃），中国人民从此站起来。</p>
      <h3>八、中国现代史综述</h3><p>1949 年以来，党团结带领人民探索、开创、坚持、捍卫、发展<span class="key">中国特色社会主义</span>：社会主义革命和建设时期、改革开放和社会主义现代化建设新时期（1978 年十一届三中全会为标志）、中国特色社会主义进入新时代。</p>
      <div class="quote">近代以来的历史证明：历史和人民选择了马克思主义、中国共产党、社会主义道路、改革开放。</div>`},
    c1:{html:`<h3>第一节 鸦片战争前后的中国与世界</h3><ul>
      <li><b>中国封建社会由盛转衰</b>：政治腐败、军备废弛、土地兼并。</li>
      <li><b>世界资本主义发展与殖民扩张</b>：英国以鸦片打开中国大门。</li></ul>
      <h3>第二节 西方列强对中国的侵略</h3><p>军事侵略、政治控制、经济掠夺、文化渗透，迫使中国签订不平等条约。</p>
      <h3>第三节 反抗外国武装侵略的斗争</h3><p>三元里抗英、太平天国、左宗棠收复新疆、义和团运动，粉碎列强瓜分图谋。</p>
      <h3>第四节 反侵略战争的失败与民族意识的觉醒</h3><p>失败根源：<span class="key">社会制度腐败、经济技术落后</span>；甲午战后民族意识普遍觉醒。</p>
      <div class="quote">鸦片战争后中国逐步沦为半殖民地半封建社会（1840—1949）；两大历史任务是民族独立人民解放与国家富强人民幸福。</div>`},
    c2:{html:`<h3>第一节 太平天国运动的起落</h3><p>1851 金田起义；《天朝田亩制度》《资政新篇》；因农民阶级局限与中外镇压失败。</p>
      <h3>第二节 洋务运动的兴衰</h3><p>"自强""求富"，办近代工业、新式海陆军、新学堂；未使中国富强但开启近代化。</p>
      <h3>第三节 维新运动的兴起和夭折</h3><p>1898 戊戌变法（百日维新），主张君主立宪；被顽固势力镇压，改良道路行不通。</p>`},
    c3:{html:`<h3>第一节 举起近代民族民主革命的旗帜</h3><p>革命条件成熟；革命派活动；<span class="key">三民主义</span>（民族、民权、民生）；革命与改良之辩。</p>
      <h3>第二节 辛亥革命与中华民国的建立</h3><p>1911 武昌起义；1912 中华民国建立，清帝退位，终结君主专制；果实被袁世凯窃取。</p>
      <h3>第三节 北洋军阀统治与旧民主主义革命的失败</h3><p>军阀混战专制；资产阶级共和国方案行不通，呼唤新的领导力量。</p>`},
    c4:{html:`<h3>第一节 新文化运动和五四运动</h3><p>新文化运动倡民主与科学；十月革命送来马克思主义；<span class="key">1919 五四运动</span>标志新民主主义革命开端。</p>
      <h3>第二节 马克思主义传播与中国共产党诞生</h3><p>早期马克思主义思想运动；马克思主义与工人运动结合；<span class="key">1921 中共一大</span>召开，党诞生。</p>
      <h3>第三节 中国革命的新局面</h3><p>制定民主革命纲领、发动工农运动、推动国共合作与北伐（大革命）。</p>`},
    c5:{html:`<h3>第一节 中国共产党对革命新道路的探索</h3><p>南昌起义等武装起义；<span class="key">农村包围城市、武装夺取政权</span>道路开辟。</p>
      <h3>第二节 中国革命在曲折中前进</h3><p>土地革命发展及挫折；<span class="key">1935 遵义会议</span>伟大转折；红军长征胜利，打开新局面。</p>`},
    c6:{html:`<h3>第一节 日本发动企图灭亡中国的侵略战争</h3><p>1931 九一八侵占东北；1937 卢沟桥事变全面侵华；残暴殖民统治与南京大屠杀。</p>
      <h3>第二节 中国人民奋起抗击日本侵略者</h3><p>中共举起武装抗日旗帜；抗日救亡兴起；<span class="key">抗日民族统一战线</span>建立，全民族抗战开始。</p>
      <h3>第三节 抗日战争的正面战场</h3><p>战略防御与相持阶段的正面战场会战。</p>
      <h3>第四节 抗日战争的中流砥柱</h3><p>全面抗战路线与持久战方针；敌后战场与游击战争；<span class="key">共产党成为中流砥柱</span>；根据地建设与自身建设。</p>
      <h3>第五节 抗日战争的胜利及其意义</h3><p>1945 胜利；近代以来第一次反侵略完全胜利，是世界反法西斯战争重要组成部分。</p>`},
    c7:{html:`<h3>第一节 从争取和平民主到击退国民党军事进攻</h3><p>重庆谈判"双十协定"；国民党发动全面内战，解放区军民坚决反击。</p>
      <h3>第二节 全国解放战争的发展和第二条战线</h3><p>解放区土地改革（耕者有其田）；国统区第二条战线形成。</p>
      <h3>第三节 中国共产党与民主党派的团结合作</h3><p>多党合作与政治协商格局形成。</p>
      <h3>第四节 建立人民民主专政的新中国</h3><p>南京国民党政权覆灭；人民政协与《共同纲领》；革命胜利的原因、意义和基本经验。</p>`},
    c8:{html:`<h3>第一节 建国和新生人民政权的巩固</h3><p>中国人民站立起来；抗美援朝、土改、镇反捍卫政权。</p>
      <h3>第二节 过渡时期总路线及其实施</h3><p>"<span class="key">一化三改</span>"；工业化起步；改造农业、手工业、资本主义工商业。</p>
      <h3>第三节 初步确立社会主义基本制度</h3><p>建立社会主义经济与政治制度，进入社会主义初级阶段。</p>
      <h3>第四节、第五节 探索与曲折</h3><p>探索适合国情的建设道路取得成就；也经历"大跃进""文革"的曲折，留下深刻教训。</p>`},
    c9:{html:`<h3>第一节 历史性的伟大转折和改革开放的起步</h3><p><span class="key">1978 十一届三中全会</span>伟大转折，开创中国特色社会主义；拨乱反正；改革开放起步。</p>
      <h3>第二节 改革开放和现代化建设新局面</h3><p>改革开放全面展开；社会主义初级阶段理论；邓小平南方谈话。</p>
      <h3>第三节 把中国特色社会主义推向21世纪</h3><p>社会主义市场经济目标确立；港澳回归；推进党的建设新的伟大工程。</p>
      <h3>第四节 在新形势下坚持和发展中国特色社会主义</h3><p>全面建设小康社会；深化改革开放；"一国两制"与党建科学化。</p>`},
    c10:{html:`<h3>第一节 开拓更为广阔的发展前景</h3><p><span class="key">中国特色社会主义进入新时代</span>；习近平同志核心地位确立；"五位一体""四个全面"；国防与国家安全。</p>
      <h3>第二节 把新时代中国特色社会主义不断推向前进</h3><p>习近平新时代中国特色社会主义思想指导地位确立；党的全面领导与自我革命；治理体系现代化；"一国两制"与人类命运共同体。</p>
      <h3>第三节 开启全面建设社会主义现代化国家新征程</h3><p>脱贫攻坚、全面建成小康社会（第一个百年）；把握新发展阶段；庆祝建党百年；全面总结百年奋斗；<span class="key">以中国式现代化</span>全面推进中华民族伟大复兴。</p>`}
  };

